def normalize_cuisine(cuisine_input: str) -> str:
    if not cuisine_input:
        return 'global'
    
    normalized = str(cuisine_input).lower().strip()
    if normalized in CUISINE_NORMALIZATION:
        return CUISINE_NORMALIZATION[normalized]
    return normalized

def fuzzy_cuisine_match(cuisine1: str, cuisine2: str, threshold: float = 0.85) -> bool:

    if not cuisine1 or not cuisine2:
        return False
    
    if cuisine1 == cuisine2:
        return True

    words1 = set(re.split(r'[\s/\-]+', cuisine1.lower()))
    words2 = set(re.split(r'[\s/\-]+', cuisine2.lower()))
    

    if words1 == words2:
        return True

    if cuisine1 in cuisine2 or cuisine2 in cuisine1:
        intersection = words1 & words2
        union = words1 | words2
        if union:
            jaccard = len(intersection) / len(union)
            return jaccard >= threshold
    
    return False

