    def _get_tdee_based_meal_structure(self, tdee: float) -> dict:
        if tdee <= 1800:
            structure_name = "3-1-4-1-4 (≤1800 kcal)"
            breakfast_slots = [
                ["lean_protein"],  
                ["beverage", "warm_beverage", "dairy_or_alt", "light_grain"], 
                ["fruit", "nut_seed", "fruit_snack"]   
            ]
            morning_snack_slots = [
                ["fruit", "fruit_snack", "dairy_or_alt"] 
            ]
            evening_snack_slots = [
                ["fruit", "fruit_snack","dairy_or_alt"] 
            ]
            
        elif tdee <= 2400:
            structure_name = "3-1-4-1-4 (1800-2400 kcal)"
            breakfast_slots = [
                ["lean_protein"], 
                ["beverage", "warm_beverage", "dairy_or_alt", "light_grain"], 
                ["fruit", "nut_seed", "fruit_snack"]   
            ]
            morning_snack_slots = [
                ["fruit", "fruit_snack", "dairy_or_alt"]  
            ]
            evening_snack_slots = [
                ["fruit", "fruit_snack","dairy_or_alt"] 
            ]
            
        else:  
            structure_name = "3-1-4-1-4 (>2400 kcal)"
            breakfast_slots = [
                ["lean_protein"], 
                ["beverage", "warm_beverage", "dairy_or_alt", "light_grain"], 
                ["fruit", "nut_seed","fruit_snack"],  
            ]
            morning_snack_slots = [
                ["fruit", "fruit_snack", "dairy_or_alt"]   
            ]
            evening_snack_slots = [
                ["fruit", "fruit_snack", "dairy_or_alt"]  
            ]
        
        lunch_slots = [
            ["protein_main", "lean_protein", "protein_source"], 
            ["grain_base", "starch_base", "light_grain"], 
            ["primary_vegetable", "cooked_vegetable"],  
            ["fat_source", "soup_or_broth", "condiment_side", "fermented_side", "fruit", "fruit_snack"]   
        ]
        
        dinner_slots = [
            ["protein_main", "lean_protein", "protein_source"],
            ["grain_base", "starch_base", "light_grain"], 
            ["primary_vegetable", "cooked_vegetable"], 
            ["fat_source", "soup_or_broth", "condiment_side", "fermented_side", "fruit", "fruit_snack"]   
        ]
        
        logger.info(f" TDEE-based meal structure: {structure_name} for {tdee:.0f} kcal")
        
        return {
            "breakfast": breakfast_slots,
            "morning_snack": morning_snack_slots,
            "lunch": lunch_slots,
            "evening_snack": evening_snack_slots,
            "dinner": dinner_slots
        }
    
