    def _compute_profile_hash(self, user_profile: Dict, blacklist: set = None) -> str:

        
        cache_key_data = {
            'allergies': sorted(user_profile.get('allergies', [])),
            'restrictions': sorted(user_profile.get('restrictions', [])),
            'dietary_preference': sorted(user_profile.get('dietary_preference', [])),
            'medical_conditions': sorted(user_profile.get('medical_conditions', [])),
            'digestive_issues': sorted(user_profile.get('digestive_issues', [])),
            'symptom_aggravating_foods': sorted(user_profile.get('symptom_aggravating_foods', [])),
            'blacklist_size': len(blacklist) if blacklist else 0  
        }
        
        json_str = json.dumps(cache_key_data, sort_keys=True, default=str)
        return hashlib.sha256(json_str.encode()).hexdigest()[:16]
    
    def _normalize_user_conditions(self, user_profile: Dict) -> List[str]:
        medical_conditions = user_profile.get('medical_conditions', [])
        if isinstance(medical_conditions, str):
            medical_conditions = [medical_conditions]
        
        DIETARY_RESTRICTIONS = {
            'gluten-free', 'gluten free', 'glutenfree',
            'dairy-free', 'dairy free', 'dairyfree', 'lactose-free', 'lactose free',
            'low-sodium', 'low sodium', 'sodium-free', 'sodium free',
            'low-carb', 'low carb', 'keto', 'ketogenic',
            'low-sugar', 'low sugar', 'sugar-free', 'sugar free',
            'vegan', 'vegetarian', 'non-vegetarian', 'non vegetarian',
            'paleo', 'whole30', 'mediterranean'
        }
        
        normalized = set()
        for cond in medical_conditions:
            if not cond:
                continue
            cond_lower = str(cond).lower().strip()
            
            if cond_lower in DIETARY_RESTRICTIONS:
                continue
            
            if cond_lower in self.MEDICAL_CONDITION_NORMALIZE:
                normalized.add(self.MEDICAL_CONDITION_NORMALIZE[cond_lower])
                continue
            
            matched = False
            for key, canonical in self.MEDICAL_CONDITION_NORMALIZE.items():
                if key in cond_lower or cond_lower in key:
                    normalized.add(canonical)
                    matched = True
                    break
            
            if not matched:
                normalized.add(cond_lower)
        
        return list(normalized)
    
    def _normalize_digestive_conditions(self, user_profile: Dict) -> List[str]:

        all_digestive = []
        digestive_issues = user_profile.get('digestive_issues', [])
        if isinstance(digestive_issues, str):
            digestive_issues = [digestive_issues]
        all_digestive.extend(digestive_issues)
        
        symptom_foods = user_profile.get('symptom_aggravating_foods', [])
        if isinstance(symptom_foods, str):
            symptom_foods = [symptom_foods]
        all_digestive.extend(symptom_foods)
        
        normalized = set()
        for cond in all_digestive:
            if not cond:
                continue
            cond_lower = str(cond).lower().strip()
            
            if cond_lower in self.MEDICAL_CONDITION_NORMALIZE:
                normalized.add(self.MEDICAL_CONDITION_NORMALIZE[cond_lower])
                continue
            
            matched = False
            for key, canonical in self.MEDICAL_CONDITION_NORMALIZE.items():
                if key in cond_lower or cond_lower in key:
                    normalized.add(canonical)
                    matched = True
                    break
            
            if not matched:
                normalized.add(cond_lower)
        
        return list(normalized)
    
    def _food_is_medically_safe(self, food_medical_safe: List[str], normalized_conditions: List[str]) -> bool:

        if not normalized_conditions:
            return True
        
        if not food_medical_safe:
            return True  
        
        food_safe_lower = [m.lower().strip() for m in food_medical_safe if m and m != 'None']
        
        if not food_safe_lower:
            return True  
        
        normalized_food_tags = set()
        for tag in food_safe_lower:
            if tag in self.MEDICAL_CONDITION_NORMALIZE:
                normalized_food_tags.add(self.MEDICAL_CONDITION_NORMALIZE[tag])
                continue
            
            matched = False
            for key, canonical in self.MEDICAL_CONDITION_NORMALIZE.items():
                if key in tag or tag in key:
                    normalized_food_tags.add(canonical)
                    matched = True
                    break
            
            if not matched:
                normalized_food_tags.add(tag) 
        
        for user_cond in normalized_conditions:
            condition_matched = False
            for safe_cond in normalized_food_tags:
                if (user_cond == safe_cond or
                    (len(user_cond) > 4 and user_cond in safe_cond) or
                    (len(safe_cond) > 4 and safe_cond in user_cond)):
                    condition_matched = True
                    break
            if not condition_matched:
                return False
        
        return True
    
