        self.previous_plan_food_groups = previous_groups
        logger.info(f" FOOD GROUP ROTATION: Loaded previous plan's food groups for {len(previous_groups)} meals")
        for meal, groups in previous_groups.items():
            logger.debug(f"   {meal}: {groups}")
    
