    def _initialize_meal_specific_pools_from_database(self, user_profile: Dict):

        if self.foods_raw is None:
            logger.warning(" Cannot build meal-specific pools: foods database not loaded yet")
            return
        
        logger.info(" Building meal-specific global failsafe pools from foods 1.json database...")
        
        all_foods_array = []
        if 'main_dishes' in self.foods_raw and 'side_dishes' in self.foods_raw:
            all_foods_array.extend(self.foods_raw.get('main_dishes', []))
            all_foods_array.extend(self.foods_raw.get('side_dishes', []))
        elif isinstance(self.foods_raw, list):
            all_foods_array = self.foods_raw
        elif 'data' in self.foods_raw and isinstance(self.foods_raw['data'], dict):
            data_dict = self.foods_raw['data']
            for category_foods in data_dict.values():
                if isinstance(category_foods, list):
                    all_foods_array.extend(category_foods)
        elif 'foods' in self.foods_raw:
            foods_data = self.foods_raw['foods']
            if isinstance(foods_data, list):
                all_foods_array = foods_data
            elif isinstance(foods_data, dict):
                for category_foods in foods_data.values():
                    if isinstance(category_foods, list):
                        all_foods_array.extend(category_foods)
        
        if not all_foods_array:
            logger.error(" No foods found in database for meal-specific pool building")
            return
        
        logger.info(f" Total foods in database: {len(all_foods_array)}")
        
        all_foods_dict = {}
        for food_item in all_foods_array:
            if isinstance(food_item, dict):
                food_name = food_item.get('name', food_item.get('item_name', ''))
                if food_name:
                    all_foods_dict[food_name] = food_item
        
        logger.info(f" Extracted {len(all_foods_dict)} unique foods")
        
        filtered_foods = self._apply_bulletproof_allergen_filter(all_foods_dict, user_profile)
        logger.info(f" After allergen filter: {len(filtered_foods)} foods")
        
        dietary_preference = user_profile.get('dietary_preference', 'non vegetarian')
        if isinstance(dietary_preference, list):
            dietary_preference = dietary_preference[0] if dietary_preference else 'non vegetarian'
        
        dietary_preference_lower = str(dietary_preference).lower()
        
        if dietary_preference_lower in ['vegetarian', 'vegan', 'lacto-vegetarian', 'ovo-vegetarian']:
            MEAT_SEAFOOD_KEYWORDS = [
                'chicken', 'turkey', 'duck', 'beef', 'pork', 'lamb', 'mutton', 'veal',
                'fish', 'salmon', 'tuna', 'cod', 'tilapia', 'shrimp', 'prawn', 
                'crab', 'lobster', 'meat', 'seafood', 'rump', 'steak', 'sirloin', 'tenderloin'
            ]
            
            if dietary_preference_lower == 'vegan':
                MEAT_SEAFOOD_KEYWORDS.extend(['egg', 'eggs', 'milk', 'cheese', 'yogurt', 'dairy', 'paneer'])
            
            dietary_filtered = {}
            for food_name, macros in filtered_foods.items():
                name_lower = food_name.lower()
                contains_meat = any(kw in name_lower for kw in MEAT_SEAFOOD_KEYWORDS)
                if not contains_meat:
                    dietary_filtered[food_name] = macros
            
            filtered_foods = dietary_filtered
            logger.info(f" After {dietary_preference} filter: {len(filtered_foods)} foods")
        
        global_foods = {}
        for food_name, macros in filtered_foods.items():
            cuisine_origin = macros.get('_cuisine_origin', macros.get('cuisine', '')).lower()
            
            if 'global' in cuisine_origin:
                global_foods[food_name] = macros
                continue

            food_category = macros.get('food_category', '').lower()
            food_group = macros.get('food_group_full', [])
            if isinstance(food_group, str):
                food_group = [food_group]
            food_group_lower = [str(g).lower() for g in food_group]
            
            is_fruit = (food_category == 'fruits' or 
                       any('fruit' in g for g in food_group_lower))
            
            if is_fruit:
                global_foods[food_name] = macros
                continue
            
            name_lower = food_name.lower()
            global_patterns = [
                'egg', 'rice', 'quinoa', 'oatmeal', 'oats', 'chicken', 'salmon', 'tilapia',
                'broccoli', 'spinach', 'carrot', 'tomato', 'cucumber', 'apple', 'banana',
                'almond', 'walnut', 'avocado', 'sweet potato', 'zucchini', 'bell pepper'
            ]
            
            if any(pattern in name_lower for pattern in global_patterns):
                global_foods[food_name] = macros
        
        logger.info(f" After global cuisine filter: {len(global_foods)} foods (fruits via food_category OR food_group fields)")
        
        self._build_pools_by_meal_timing(global_foods, user_profile)
        
        logger.info(f" Meal-specific global failsafe pools built from database:")
        logger.info(f"   Breakfast: {len(self.failsafe_breakfast_pool)} items")
        logger.info(f"   Morning Snack: {len(self.failsafe_morning_snack_pool)} items")
        logger.info(f"   Lunch: {len(self.failsafe_lunch_pool)} items")
        logger.info(f"   Evening Snack: {len(self.failsafe_evening_snack_pool)} items")
        logger.info(f"   Dinner: {len(self.failsafe_dinner_pool)} items")
        
        if not self.failsafe_breakfast_pool:
            logger.error(f"  BREAKFAST FAILSAFE POOL IS EMPTY - foods missing 'breakfast' meal_timing tags!")
        if not self.failsafe_lunch_pool:
            logger.error(f"  LUNCH FAILSAFE POOL IS EMPTY - foods missing 'lunch' meal_timing tags!")
        if not self.failsafe_dinner_pool:
            logger.error(f"  DINNER FAILSAFE POOL IS EMPTY - foods missing 'dinner' meal_timing tags!")
        if not self.failsafe_morning_snack_pool and not self.failsafe_evening_snack_pool:
            logger.error(f"  SNACK FAILSAFE POOLS ARE EMPTY - foods missing 'snack' meal_timing tags!")
    
    def _build_pools_by_meal_timing(self, filtered_foods: Dict[str, Dict], user_profile: Dict):
        breakfast_candidates = []
        morning_snack_candidates = []
        lunch_candidates = []
        evening_snack_candidates = []
        dinner_candidates = []
        
        foods_without_timing = []
        
        for food_name, macros in filtered_foods.items():
            meal_timing = macros.get('meal_timing', macros.get('meal_tags', []))
            if not meal_timing:
                foods_without_timing.append(food_name)
                continue
            
            if isinstance(meal_timing, str):
                meal_timing = [meal_timing]
            
            meal_timing_lower = [tag.lower().strip() for tag in meal_timing if tag]
            
            if not meal_timing_lower:
                foods_without_timing.append(food_name)
                continue
            
            try:
                protein = float(macros.get('protein', 0))
                fiber = float(macros.get('fiber', 0))
                calories = float(macros.get('calories', 100))
                
                score = protein + (fiber * 2) - (calories / 100)
            except:
                score = 0
            
            food_entry = {
                'name': food_name,
                'macros': macros,
                'score': score
            }
            
            if 'breakfast' in meal_timing_lower:
                breakfast_candidates.append(food_entry)
            
            if 'snack' in meal_timing_lower or 'morning snack' in meal_timing_lower:
                morning_snack_candidates.append(food_entry)
            
            if 'lunch' in meal_timing_lower:
                lunch_candidates.append(food_entry)
            
            if 'snack' in meal_timing_lower or 'evening snack' in meal_timing_lower:
                evening_snack_candidates.append(food_entry)
            
            if 'dinner' in meal_timing_lower:
                dinner_candidates.append(food_entry)
        
        self.failsafe_breakfast_pool = self._select_top_items(breakfast_candidates, 15)
        self.failsafe_morning_snack_pool = self._select_top_items(morning_snack_candidates, 15)
        self.failsafe_lunch_pool = self._select_top_items(lunch_candidates, 15)
        self.failsafe_evening_snack_pool = self._select_top_items(evening_snack_candidates, 15)
        self.failsafe_dinner_pool = self._select_top_items(dinner_candidates, 15)
        
        logger.info(f" Meal timing pool builder statistics:")
        logger.info(f"   Breakfast candidates: {len(breakfast_candidates)}")
        logger.info(f"   Morning snack candidates: {len(morning_snack_candidates)}")
        logger.info(f"   Lunch candidates: {len(lunch_candidates)}")
        logger.info(f"   Evening snack candidates: {len(evening_snack_candidates)}")
        logger.info(f"   Dinner candidates: {len(dinner_candidates)}")
        logger.info(f"   Foods without meal_timing tags: {len(foods_without_timing)}")
        
        if foods_without_timing:
            logger.warning(f"  {len(foods_without_timing)} foods skipped due to missing meal_timing tags")
            logger.warning(f"   Sample foods: {', '.join(foods_without_timing[:5])}")
            logger.warning(f"   These foods will not be available in meal-specific failsafe pools")
    
    def _select_top_items(self, candidates: List[Dict], max_items: int) -> List[Dict]:

        if not candidates:
            return []
        
        sorted_candidates = sorted(candidates, key=lambda x: x['score'], reverse=True)
        
        top_items = sorted_candidates[:max_items]
        
        pool = []
        for item in top_items:
            food_name = item['name']
            macros = item['macros']
            
            try:
                cals = float(macros.get('calories', 0))
                protein = float(macros.get('protein', 0))
                carbs = float(macros.get('carbs', 0))
                fat = float(macros.get('fat', 0))
                fiber = float(macros.get('fiber', 0))
                sodium = float(macros.get('sodium', 0))
                sugar = float(macros.get('sugar', 0))
                
                portion_oz = 3.5
                
                pool_entry = {
                    "name": food_name,
                    "cals": round(cals * portion_oz / 3.5, 1),
                    "p": round(protein * portion_oz / 3.5, 1),
                    "c": round(carbs * portion_oz / 3.5, 1),
                    "f": round(fat * portion_oz / 3.5, 1),
                    "fiber": round(fiber * portion_oz / 3.5, 1),
                    "sodium": round(sodium * portion_oz / 3.5, 1),
                    "sugar": round(sugar * portion_oz / 3.5, 1),
                    "oz": portion_oz,
                    "_cuisine_origin": "global",
                    "meal_timing": macros.get('meal_tags', macros.get('meal_timing', []))
                }
                
                pool.append(pool_entry)
            except Exception as e:
                logger.debug(f" Skipping '{food_name}': Invalid nutrients ({e})")
                continue
        
        return pool
    
    
    def _build_safe_pool_payload(self, categorized_pool: Dict[str, List[str]], 
                                  meal_type: str, user_profile: Dict, 
                                  macro_lookup: Dict) -> Dict:
        cuisine = user_profile.get('cuisine', 'global')
        if isinstance(cuisine, list):
            cuisine = cuisine[0] if cuisine else 'global'
        cuisine = normalize_cuisine(cuisine) 
        
        dietary_pref = user_profile.get('dietary_preference', 'non-vegetarian')
        filtered_categorized_pool = categorized_pool
        def extract_metadata(food_names: List[str], category: str) -> List[Dict]:
            items = []
            for name in food_names[:50]:  
                macros = macro_lookup.get(name, {})
                items.append({
                    "name": name,
                    "calories": macros.get('calories', 0),
                    "protein": macros.get('protein', 0),
                    "carbs": macros.get('carbs', 0),
                    "fat": macros.get('fat', 0),
                    "fiber": macros.get('fiber', 0),
                    "cuisine": macros.get('_cuisine_origin', 'unknown'),
                    "category": category
                })
            return items
        
        payload = {
            "meal_type": meal_type,
            "cuisine_preference": str(cuisine).lower().strip(),
            "dietary_preference": dietary_pref,
            "available_carbs": extract_metadata(filtered_categorized_pool.get('complex_carbs', []), 'complex_carbs'),
            "available_proteins": extract_metadata(filtered_categorized_pool.get('proteins', []), 'proteins'),
            "available_veggies": extract_metadata(filtered_categorized_pool.get('fibrous_veggies', []), 'fibrous_veggies'),
        }
        
        if meal_type.lower() in ['breakfast']:
            payload["slot_requirements"] = {
                "protein_slot": {"required": True, "count": 1},
                "veggie_slot": {"required": True, "count": 1}
            }
        elif meal_type.lower() in ['lunch', 'dinner']:
            payload["slot_requirements"] = {
                "carb_slot": {"required": True, "count": 1},
                "protein_slot": {"required": True, "count": 1},
                "veggie_slot": {"required": True, "count": 1}
            }
        else:
            payload["slot_requirements"] = {
                "protein_fat_slot": {"required": True, "count": 1},
                "fiber_slot": {"required": True, "count": 1}
            }
        
        return payload
    
    async def _call_contextual_intelligence(self, safe_pools_payload: Dict, 
                                            meal_type: str, 
                                            profile_context: Dict) -> Optional[Dict]:
        if not ENABLE_CONTEXTUAL_INTELLIGENCE:
            logger.debug(" Contextual Intelligence disabled via config")
            return None
        
        logger.info(f" Calling Contextual Intelligence for {meal_type}...")
        logger.debug(f"   Payload: {len(safe_pools_payload.get('available_proteins', []))} proteins, "
                    f"{len(safe_pools_payload.get('available_carbs', []))} carbs, "
                    f"{len(safe_pools_payload.get('available_veggies', []))} veggies")
        
        try:
            async with aiohttp.ClientSession() as session:
                async with asyncio.wait_for(
                    session.post(
                        CONTEXTUAL_INTELLIGENCE_ENDPOINT,
                        json=safe_pools_payload,
                        headers={"Content-Type": "application/json"}
                    ),
                    timeout=CONTEXTUAL_INTELLIGENCE_TIMEOUT
                ) as response:
                    if response.status == 200:
                        result = await response.json()
                        logger.info(f" Contextual Intelligence response for {meal_type}: "
                                  f"{result.get('carb', 'N/A')} + {result.get('protein', 'N/A')} + {result.get('veggie', 'N/A')}")
                        return result
                    else:
                        logger.warning(f" Contextual Intelligence returned status {response.status} for {meal_type}")
                        return None
        
        except asyncio.TimeoutError:
            logger.warning(f"⏱️ Contextual Intelligence timeout ({CONTEXTUAL_INTELLIGENCE_TIMEOUT}s) for {meal_type}")
            return None
        except aiohttp.ClientError as e:
            logger.warning(f" Contextual Intelligence network error for {meal_type}: {e}")
            return None
        except Exception as e:
            logger.error(f" Contextual Intelligence unexpected error for {meal_type}: {e}")
            return None
    
    def _validate_ai_selection(self, ai_response: Dict, safe_pools: Dict[str, List[str]], 
                               meal_type: str) -> bool:
        if not ai_response:
            return False
        if meal_type.lower() in ['breakfast']:
            selections = {
                'protein': ai_response.get('protein'),
                'veggie': ai_response.get('veggie')
            }
            required_pools = {
                'protein': safe_pools.get('proteins', []),
                'veggie': safe_pools.get('fibrous_veggies', [])
            }
        elif meal_type.lower() in ['lunch', 'dinner']:
            selections = {
                'carb': ai_response.get('carb'),
                'protein': ai_response.get('protein'),
                'veggie': ai_response.get('veggie')
            }
            required_pools = {
                'carb': safe_pools.get('complex_carbs', []),
                'protein': safe_pools.get('proteins', []),
                'veggie': safe_pools.get('fibrous_veggies', [])
            }
        else: 
            selections = {
                'protein_fat': ai_response.get('protein_fat'),
                'fiber': ai_response.get('fiber')
            }
            required_pools = {
                'protein_fat': safe_pools.get('protein_fat_snacks', []),
                'fiber': safe_pools.get('fiber_snacks', [])
            }
        
        for slot_name, selected_item in selections.items():
            if not selected_item:
                logger.warning(f" HALLUCINATION CHECK: Missing {slot_name} selection for {meal_type}")
                return False
            
            valid_pool = required_pools.get(slot_name, [])
            if selected_item not in valid_pool:
                logger.error(f" HALLUCINATION DETECTED: '{selected_item}' not in safe {slot_name} pool for {meal_type}")
                return False
        
        logger.info(f" Hallucination check passed for {meal_type}")
        return True
    
    async def _batch_get_ai_meal_selections(self, categorized_pool: Dict[str, List[str]],
                                            snack_pool: List[str], user_profile: Dict,
                                            macro_lookup: Dict) -> Dict[str, Optional[Dict]]:
        logger.info(" BATCH AI SELECTION: Initiating concurrent calls for all 5 meals...")
        meal_types = ['Breakfast', 'Morning Snack', 'Lunch', 'Evening Snack', 'Dinner']
        payloads = []
        for meal_type in meal_types:
            payload = self._build_safe_pool_payload(
                categorized_pool, meal_type, user_profile, macro_lookup
            )
            payloads.append((meal_type, payload))
        tasks = [
            self._call_contextual_intelligence(payload, meal_type, user_profile)
            for meal_type, payload in payloads
        ]
        
        try:
            results = await asyncio.gather(*tasks, return_exceptions=True)
        except Exception as e:
            logger.error(f" Batch AI selection catastrophic failure: {e}")
            results = [None] * len(meal_types)
        
        ai_selections = {}
        for i, meal_type in enumerate(meal_types):
            result = results[i]
            if isinstance(result, Exception):
                logger.warning(f" {meal_type} AI call raised exception: {result}")
                ai_selections[meal_type] = None
            else:
                ai_selections[meal_type] = result
        
        success_count = sum(1 for v in ai_selections.values() if v is not None)
        logger.info(f" BATCH AI SELECTION COMPLETE: {success_count}/5 meals returned valid responses")
        
        return ai_selections
    
    def _get_safe_random_failsafe(self, category: str, blacklist: set, user_profile: Dict, 
                                   meal_name: str = "", current_meal_category_counts: Dict[str, int] = None) -> Optional[Dict]:

        if current_meal_category_counts:
            complex_carb_count = current_meal_category_counts.get('complex_carbs', 0)
            
            if complex_carb_count >= 1 and category == 'complex_carbs':
                logger.error(f" CATEGORY BLOCKING: Meal already has {complex_carb_count} complex carb(s)")
                logger.error(f"   BLOCKING request for 'complex_carbs' category failsafe")
                logger.error(f"   Returning None to force caller to try a different category (proteins/fats)")
                return None
        
        meal_specific_pool = None
        if meal_name:
            meal_normalized = meal_name.lower().strip()
            if 'breakfast' in meal_normalized:
                meal_specific_pool = self.failsafe_breakfast_pool
                logger.debug(f" Using BREAKFAST-specific global failsafe pool ({len(meal_specific_pool)} items)")
            elif 'morning' in meal_normalized and 'snack' in meal_normalized:
                meal_specific_pool = self.failsafe_morning_snack_pool
                logger.debug(f" Using MORNING SNACK-specific global failsafe pool ({len(meal_specific_pool)} items)")
            elif 'lunch' in meal_normalized:
                meal_specific_pool = self.failsafe_lunch_pool
                logger.debug(f" Using LUNCH-specific global failsafe pool ({len(meal_specific_pool)} items)")
            elif 'evening' in meal_normalized and 'snack' in meal_normalized:
                meal_specific_pool = self.failsafe_evening_snack_pool
                logger.debug(f" Using EVENING SNACK-specific global failsafe pool ({len(meal_specific_pool)} items)")
            elif 'dinner' in meal_normalized:
                meal_specific_pool = self.failsafe_dinner_pool
                logger.debug(f" Using DINNER-specific global failsafe pool ({len(meal_specific_pool)} items)")
        
        pool = None
        pool_source = "category-based"
        
        if meal_name:
            meal_normalized = meal_name.lower().strip()
            if 'breakfast' in meal_normalized and self.failsafe_breakfast_pool:
                pool = self.failsafe_breakfast_pool
                pool_source = "breakfast meal-specific"
                logger.debug(f" Using BREAKFAST-specific global failsafe pool ({len(pool)} items)")
            elif 'morning' in meal_normalized and 'snack' in meal_normalized and self.failsafe_morning_snack_pool:
                pool = self.failsafe_morning_snack_pool
                pool_source = "morning snack meal-specific"
                logger.debug(f" Using MORNING SNACK-specific global failsafe pool ({len(pool)} items)")
            elif 'lunch' in meal_normalized and self.failsafe_lunch_pool:
                pool = self.failsafe_lunch_pool
                pool_source = "lunch meal-specific"
                logger.debug(f" Using LUNCH-specific global failsafe pool ({len(pool)} items)")
            elif 'evening' in meal_normalized and 'snack' in meal_normalized and self.failsafe_evening_snack_pool:
                pool = self.failsafe_evening_snack_pool
                pool_source = "evening snack meal-specific"
                logger.debug(f" Using EVENING SNACK-specific global failsafe pool ({len(pool)} items)")
            elif 'dinner' in meal_normalized and self.failsafe_dinner_pool:
                pool = self.failsafe_dinner_pool
                pool_source = "dinner meal-specific"
                logger.debug(f" Using DINNER-specific global failsafe pool ({len(pool)} items)")
        
        if not pool:
            if category == 'veggie':
                pool = self.failsafe_veggie_pool
            elif category == 'protein_fat':
                pool = self.failsafe_protein_fat_pool
            elif category == 'fiber_produce':
                pool = self.failsafe_fiber_produce_pool
            elif category == 'complex_carbs':
                pool = self.failsafe_complex_carbs_pool
            elif category == 'proteins':
                pool = self.failsafe_proteins_pool
            else:
                logger.error(f"Unknown failsafe category: {category}")
                return None
            logger.debug(f" Using {category} category-based failsafe pool ({len(pool)} items)")
        
        if not pool:
            logger.error(f"No failsafe pool available for category '{category}' and meal '{meal_name}'")
            return None
        
        if meal_name:
            meal_normalized = meal_name.lower().strip()
            required_meal_tag = None
            
            if 'breakfast' in meal_normalized:
                required_meal_tag = 'breakfast'
            elif 'lunch' in meal_normalized:
                required_meal_tag = 'lunch'
            elif 'dinner' in meal_normalized:
                required_meal_tag = 'dinner'
            elif 'snack' in meal_normalized:
                required_meal_tag = 'snack'
            
            if required_meal_tag:
                original_pool_size = len(pool)
                meal_timing_filtered_pool = []
                
                for item in pool:
                    item_meal_timing = item.get('meal_timing', [])
                    if not item_meal_timing:
                        meal_timing_filtered_pool.append(item)
                        continue
                    
                    if isinstance(item_meal_timing, str):
                        item_meal_timing = [item_meal_timing]
                    
                    item_meal_timing_lower = [tag.lower().strip() for tag in item_meal_timing if tag]
                    
                    if required_meal_tag in item_meal_timing_lower:
                        meal_timing_filtered_pool.append(item)
                    else:
                        logger.debug(f"   MEAL TIMING FILTER: '{item['name']}' blocked (tags: {item_meal_timing_lower}, need: {required_meal_tag})")
                
                if meal_timing_filtered_pool:
                    pool = meal_timing_filtered_pool
                    logger.info(f" MEAL TIMING FILTER: {len(pool)}/{original_pool_size} failsafe items match '{required_meal_tag}' timing")
                else:
                    logger.warning(f" MEAL TIMING FILTER: No failsafe items match '{required_meal_tag}' - using all {original_pool_size} items")
        
        if current_meal_category_counts:
            complex_carb_count = current_meal_category_counts.get('complex_carbs', 0)
            
            if complex_carb_count >= 1 and category in ['veggie', 'fiber_produce', 'protein_fat']:
                COMPLEX_CARB_KEYWORDS = [
                    'rice', 'oats', 'oatmeal', 'quinoa', 'barley', 'buckwheat', 'millet',
                    'couscous', 'bulgur', 'farro', 'pasta', 'noodle', 'bread', 'roti',
                    'potato', 'sweet potato', 'lentils', 'beans', 'chickpeas', 'dal'
                ]
                
                original_pool_size = len(pool)
                pool = [
                    item for item in pool
                    if not any(carb_kw in item['name'].lower() for carb_kw in COMPLEX_CARB_KEYWORDS)
                ]
                
                if len(pool) < original_pool_size:
                    logger.warning(f" ANTI-STACKING SHIELD: Removed {original_pool_size - len(pool)} complex carb items from {category} failsafe pool")
                    logger.warning(f"   Meal already has {complex_carb_count} complex carb(s), forcing selection of veggie/protein")
                
                if not pool:
                    logger.error(f" ANTI-STACKING SHIELD: All {category} failsafes were complex carbs. Cannot select.")
                    return None
        
        safe_pool = []
        for item in pool:
            name_lower = item['name'].lower()
            is_safe = True
            
            for keyword in blacklist:
                if keyword.lower() in name_lower:
                    is_safe = False
                    logger.debug(f" Failsafe blocked by blacklist: {item['name']} (contains '{keyword}')")
                    break
            
            if is_safe:
                safe_pool.append(item)
        
        if not safe_pool:
            logger.error(f" All {category} failsafes blocked by user constraints (allergies/restrictions)")
            return None
        dietary_preference = user_profile.get('dietary_preference', 'non vegetarian')
        if isinstance(dietary_preference, list):
            dietary_preference = dietary_preference[0] if dietary_preference else 'non vegetarian'
        
        dietary_preference_lower = str(dietary_preference).lower()
        
        if dietary_preference_lower in ['vegetarian', 'vegan', 'lacto-vegetarian', 'ovo-vegetarian']:
            MEAT_SEAFOOD_KEYWORDS = [
                'chicken', 'turkey', 'duck', 'goose', 'quail', 'hen', 'poultry',
                'beef', 'pork', 'lamb', 'mutton', 'veal', 'venison', 'goat', 'bison',
                'steak', 'bacon', 'ham', 'sausage', 'salami', 'pepperoni',
                'fish', 'salmon', 'tuna', 'cod', 'tilapia', 'mackerel', 'trout', 'haddock',
                'sardine', 'anchovy', 'herring', 'catfish', 'bass', 'snapper', 'sole',
                'halibut', 'flounder', 'perch', 'pike', 'carp', 'swordfish', 'mahi',
                'cutlass', 'cutlassfish', 'barracuda', 'kingfish', 'grouper', 'pollock',
                'whitebait', 'shirasu', 'fry', 'fingerling', 'smelt',  
                'sashimi', 'sushi', 'fillet', 'filet',
                'shrimp', 'prawn', 'crab', 'lobster', 'oyster', 'clam', 'mussel', 'scallop',
                'crawfish', 'crayfish', 'squid', 'octopus', 'calamari',
                'seafood', 'meat', 'animal'
            ]
            
            if dietary_preference_lower == 'vegan':
                VEGAN_EXCLUDE_KEYWORDS = ['egg', 'eggs', 'albumin', 'omelette', 'omelet',
                                         'milk', 'cheese', 'yogurt', 'cream', 'butter', 'ghee',
                                         'dairy', 'whey', 'casein', 'paneer']
                MEAT_SEAFOOD_KEYWORDS.extend(VEGAN_EXCLUDE_KEYWORDS)
            
            dietary_safe_pool = []
            for item in safe_pool:
                name_lower = item['name'].lower()
                contains_meat_seafood = any(kw in name_lower for kw in MEAT_SEAFOOD_KEYWORDS)
                
                if contains_meat_seafood:
                    logger.warning(f" DIETARY FILTER: Blocked '{item['name']}' from {category} failsafe pool (user is {dietary_preference})")
                else:
                    dietary_safe_pool.append(item)
            
            safe_pool = dietary_safe_pool
            
            if not safe_pool:
                logger.error(f" All {category} failsafes blocked after applying {dietary_preference} filter")
                return None
            
            logger.info(f" DIETARY FILTER APPLIED: {len(safe_pool)} {dietary_preference}-safe {category} failsafes available")
        
        # 🚀 MULTI-CUISINE FIX (April 30, 2026): Respect ALL requested cuisines for failsafes
        user_cuisine = user_profile.get('diet_preference_cuisine', 'global')
        
        # Handle comma-separated string from database
        if isinstance(user_cuisine, str) and ',' in user_cuisine:
            user_cuisine = [c.strip() for c in user_cuisine.split(',') if c.strip()]
        
        if isinstance(user_cuisine, list):
            user_cuisines_list = [normalize_cuisine(c) for c in user_cuisine if c] if user_cuisine else ['global']
        else:
            user_cuisines_list = [normalize_cuisine(user_cuisine)] if user_cuisine else ['global']
        
        # Check failsafes against ALL requested cuisines
        user_cuisine_normalized_list = [str(c).lower().strip() for c in user_cuisines_list]
        
        cuisine_safe_pool = []
        for item in safe_pool:
            item_name = item['name']
            item_cuisine = item.get('_cuisine_origin', 'global')
            is_allowed = False
            
            # Always accept global failsafes
            if item_cuisine == 'global':
                is_allowed = True
                logger.debug(f" GLOBAL FAILSAFE ACCEPTED: '{item_name}' (all cuisines accept global failsafes)")
            
            # Check against ANY of the requested cuisines
            if not is_allowed:
                for user_cuisine_norm in user_cuisine_normalized_list:
                    if user_cuisine_norm in CUISINE_BASE_STAPLES:
                        if item_name in CUISINE_BASE_STAPLES[user_cuisine_norm]:
                            is_allowed = True
                            logger.debug(f" CUISINE MATCH: '{item_name}' found in '{user_cuisine_norm}' staples")
                            break
            
            # Global staples are always allowed
            if not is_allowed and item_name in CUISINE_BASE_STAPLES.get('global', []):
                is_allowed = True
                logger.debug(f" GLOBAL MATCH: '{item_name}' found in global staples pool")
            
            # Fuzzy matching against requested cuisines
            if not is_allowed:
                item_lower = item_name.lower()
                
                for user_cuisine_norm in user_cuisine_normalized_list:
                    if user_cuisine_norm in CUISINE_BASE_STAPLES:
                        for staple in CUISINE_BASE_STAPLES[user_cuisine_norm]:
                            staple_keywords = staple.lower().split()
                            matching_keywords = [kw for kw in staple_keywords if kw in item_lower and len(kw) > 3]
                            if len(matching_keywords) >= min(2, len(staple_keywords)):
                                is_allowed = True
                                logger.debug(f" FUZZY CUISINE MATCH: '{item_name}' matches '{staple}' from '{user_cuisine_norm}'")
                                break
                        if is_allowed:
                            break
                
                # Fuzzy global matching
                if not is_allowed:
                    for staple in CUISINE_BASE_STAPLES.get('global', []):
                        staple_keywords = staple.lower().split()
                        matching_keywords = [kw for kw in staple_keywords if kw in item_lower and len(kw) > 3]
                        if len(matching_keywords) >= min(2, len(staple_keywords)):
                            is_allowed = True
                            logger.debug(f" FUZZY GLOBAL MATCH: '{item_name}' matches '{staple}' from global pool")
                            break
            
            if is_allowed:
                cuisine_safe_pool.append(item)
            else:
                logger.debug(f" CUISINE FILTER: Blocked '{item_name}' (not in {user_cuisine_normalized_list} or 'global' pools)")
        
        if not cuisine_safe_pool:
            logger.error(f" CUISINE FILTER: All {category} failsafes blocked by cuisine purity filter")
            logger.error(f" Requested cuisines: {user_cuisine_normalized_list}, available cuisines: {list(CUISINE_BASE_STAPLES.keys())}")
            logger.error(f"  DEBUG: Failsafe items: {[item['name'] for item in safe_pool[:5]]}")
            logger.error(f"  DEBUG: Check if failsafe items should be in {user_cuisine_normalized_list} or 'global' staples")
            logger.warning(f" EMERGENCY FALLBACK: Restoring full safe_pool to prevent total meal generation failure")
            cuisine_safe_pool = safe_pool
        else:
            logger.info(f" CUISINE PURITY APPLIED: {len(cuisine_safe_pool)}/{len(safe_pool)} failsafes match {user_cuisine_normalized_list} or 'global'")
        
        safe_pool = cuisine_safe_pool
        
        symptom_aggravating = user_profile.get('symptom_aggravating_foods', [])
        if symptom_aggravating:
            symptom_safe_pool = []
            for item in safe_pool:
                name_lower = item['name'].lower()
                is_symptom_safe = True
                
                symptom_filter_map = {
                    'fried or greasy foods': ['fried', 'fritter', 'battered', 'tempura', 'crispy'],
                    'fried foods': ['fried', 'fritter', 'battered', 'tempura', 'crispy'],
                    'greasy foods': ['fried', 'greasy', 'oily'],
                    'dairy products': ['milk', 'cheese', 'yogurt', 'cream', 'butter', 'dairy', 'cheddar', 'cottage cheese'],
                    'spicy foods': ['spicy', 'hot', 'chili', 'pepper', 'jalapeño', 'cayenne']
                }
                
                for symptom in symptom_aggravating:
                    symptom_lower = str(symptom).lower()
                    for symptom_cat, keywords in symptom_filter_map.items():
                        if symptom_cat in symptom_lower:
                            for kw in keywords:
                                if kw in name_lower:
                                    is_symptom_safe = False
                                    logger.debug(f" Failsafe blocked by symptom: {item['name']} (symptom: {symptom})")
                                    break
                            if not is_symptom_safe:
                                break
                    if not is_symptom_safe:
                        break
                
                if is_symptom_safe:
                    symptom_safe_pool.append(item)
            
            safe_pool = symptom_safe_pool
        
        if not safe_pool:
            logger.error(f" All {category} failsafes blocked by symptom-aggravating foods")
            return None
        
        unused_pool = [item for item in safe_pool 
                      if item['name'] not in self.used_failsafes_today 
                      and item['name'] not in self.daily_used_foods]
        
        logger.debug(f"   FAILSAFE UNIQUENESS: {len(unused_pool)}/{len(safe_pool)} items not used today (checked both failsafe and daily trackers)")
        
        if not unused_pool:
            logger.warning(f" All safe {category} failsafes already used today. Allowing repetition.")
            unused_pool = safe_pool
        
        cross_day_fresh_pool = [item for item in unused_pool if item['name'] not in self.used_failsafes_previous_day]
        
        if not cross_day_fresh_pool:
            logger.info(f" All unused {category} failsafes were used yesterday. Using items from previous day.")
            cross_day_fresh_pool = unused_pool
        
        if cross_day_fresh_pool:
            food_names = [item['name'] for item in cross_day_fresh_pool]
            macro_map = {item['name']: {'is_common': True, 'is_exotic': False, 'is_holiday': False} for item in cross_day_fresh_pool}
            selected_name = self._prioritize_common_foods(food_names, macro_map)
            selected = next(item for item in cross_day_fresh_pool if item['name'] == selected_name)
            self.used_failsafes_today.add(selected['name'])
            
            logger.info(f" Selected safe random failsafe: '{selected['name']}' ({pool_source}) for {meal_name}")
            logger.info(f"   Available options: {len(safe_pool)}, Unused: {len(unused_pool)}")
            
            grams = selected['oz'] * 28.35
            # Look up food_id and recipe from all_foods_macros
            _failsafe_macros = self.all_foods_macros.get(selected['name'], {})
            _failsafe_recipe = _failsafe_macros.get('_recipe', {})
            formatted = {
                "name": f"{selected['name']} ({selected['oz']} oz)",
                "nutrients": {
                    "Calories": round(selected['cals'], 1),
                    "Protein": round(selected['p'], 1),
                    "Carbohydrates": round(selected['c'], 1),
                    "Fat": round(selected['f'], 1),
                    "Fiber": round(selected['fiber'], 1),
                    "Sodium": round(selected['sodium'], 1),
                    "Iodine": 0.0,
                    "Sugar": round(selected['sugar'], 1),
                    "Cholesterol": 0.0,
                    "Portion Weight": round(grams, 1)
                },
                "food_id": _failsafe_macros.get('_food_id'),
                "ingredients": _failsafe_recipe.get('ingredients', []) if isinstance(_failsafe_recipe, dict) else [],
                "recipe": _failsafe_recipe.get('steps', []) if isinstance(_failsafe_recipe, dict) else [],
            }
            
            return formatted
        
        logger.warning(f" PRIMARY '{category}' failsafe pool exhausted after all filters")
        logger.warning(f"   Attempting SECONDARY FALLBACK HIERARCHY: proteins → protein_fat → veggie")
        secondary_hierarchy = ['proteins', 'protein_fat', 'veggie']
        secondary_hierarchy = [cat for cat in secondary_hierarchy if cat != category]
        complex_carb_count = current_meal_category_counts.get('complex_carbs', 0) if current_meal_category_counts else 0
        if complex_carb_count >= 1:
            secondary_hierarchy = [cat for cat in secondary_hierarchy if cat != 'complex_carbs']
            logger.info(f" Anti-Carb Lock: Meal has {complex_carb_count} complex carb(s), blocking 'complex_carbs' from secondary hierarchy")
        
        for secondary_category in secondary_hierarchy:
            logger.info(f"    Trying secondary category: '{secondary_category}'...")
            if secondary_category == 'proteins':
                secondary_pool = self.failsafe_proteins_pool
            elif secondary_category == 'protein_fat':
                secondary_pool = self.failsafe_protein_fat_pool
            elif secondary_category == 'veggie':
                secondary_pool = self.failsafe_veggie_pool
            elif secondary_category == 'fiber_produce':
                secondary_pool = self.failsafe_fiber_produce_pool
            else:
                continue
            
            secondary_safe_pool = []
            for item in secondary_pool:
                name_lower = item['name'].lower()
                is_safe = True
                for keyword in blacklist:
                    if keyword.lower() in name_lower:
                        is_safe = False
                        break
                
                if is_safe:
                    secondary_safe_pool.append(item)
            
            if secondary_safe_pool:
                dietary_preference = user_profile.get('dietary_preference', 'non vegetarian')
                if isinstance(dietary_preference, list):
                    dietary_preference = dietary_preference[0] if dietary_preference else 'non vegetarian'
                
                dietary_preference_lower = str(dietary_preference).lower()
                
                if dietary_preference_lower in ['vegetarian', 'vegan']:
                    MEAT_SEAFOOD_KEYWORDS = [
                        'chicken', 'beef', 'pork', 'lamb', 'mutton', 'fish', 'salmon', 'tuna',
                        'shrimp', 'prawn', 'crab', 'seafood', 'meat', 'bacon', 'steak', 'fillet'
                    ]
                    
                    dietary_filtered = []
                    for item in secondary_safe_pool:
                        if not any(kw in item['name'].lower() for kw in MEAT_SEAFOOD_KEYWORDS):
                            dietary_filtered.append(item)
                    
                    secondary_safe_pool = dietary_filtered
            
            if secondary_safe_pool:
                food_names = [item['name'] for item in secondary_safe_pool]
                macro_map = {item['name']: {'is_common': True, 'is_exotic': False, 'is_holiday': False} for item in secondary_safe_pool}
                selected_name = self._prioritize_common_foods(food_names, macro_map)
                selected = next(item for item in secondary_safe_pool if item['name'] == selected_name)
                self.used_failsafes_today.add(selected['name'])
                
                logger.info(f" SECONDARY FALLBACK SUCCESS: '{secondary_category}' provided item for original '{category}' slot")
                logger.info(f"   Selected: '{selected['name']}'")
                
                grams = selected['oz'] * 28.35
                # Look up food_id and recipe from all_foods_macros
                _secondary_macros = self.all_foods_macros.get(selected['name'], {})
                _secondary_recipe = _secondary_macros.get('_recipe', {})
                formatted = {
                    "name": f"{selected['name']} ({selected['oz']} oz)",
                    "nutrients": {
                        "Calories": round(selected['cals'], 1),
                        "Protein": round(selected['p'], 1),
                        "Carbohydrates": round(selected['c'], 1),
                        "Fat": round(selected['f'], 1),
                        "Fiber": round(selected['fiber'], 1),
                        "Sodium": round(selected['sodium'], 1),
                        "Iodine": 0.0,
                        "Sugar": round(selected['sugar'], 1),
                        "Cholesterol": 0.0,
                        "Portion Weight": round(grams, 1)
                    },
                    "food_id": _secondary_macros.get('_food_id'),
                    "ingredients": _secondary_recipe.get('ingredients', []) if isinstance(_secondary_recipe, dict) else [],
                    "recipe": _secondary_recipe.get('steps', []) if isinstance(_secondary_recipe, dict) else [],
                }
                
                return formatted
            else:
                logger.warning(f"    Secondary category '{secondary_category}' also exhausted after filters")
        
        logger.error(f" COMPLETE FAILSAFE EXHAUSTION: Primary '{category}' AND all secondary hierarchies exhausted")
        return None
    
    
    def _load_json_dataset(self, file_path: Path) -> Dict:
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                return json.load(f)
        except Exception as e:
            logger.error(f"Failed to load dataset from {file_path}: {e}")
            raise
    
    def _calculate_averaged_macros(self, food_data: Dict, food_name: str = "") -> Dict[str, float]:
        def avg(arr):
            if not arr or len(arr) != 2:
                return 0.0
            valid_values = [v for v in arr if v is not None]
            if not valid_values:
                return 0.0
            return sum(valid_values) / 2.0
        
        avg_protein = avg(food_data.get('protein_per_100g', [0, 0]))
        avg_calories = avg(food_data.get('calories_per_100g', [0, 0]))
        avg_fat = avg(food_data.get('fat_per_100g', [0, 0]))
        avg_fiber = avg(food_data.get('fiber_per_100g', [0, 0]))
        avg_sodium = avg(food_data.get('sodium_per_100g', [0, 0]))
        avg_cholesterol = avg(food_data.get('cholesterol_per_100g', [0, 0]))
        avg_sugar = avg(food_data.get('sugar_per_100g', [0, 0]))
        
        calculated_carbs = max(0.0, (avg_calories - (avg_protein * 4) - (avg_fat * 9)) / 4.0)
        
        carb_keywords = ['pasta', 'rice', 'bread', 'bagel', 'noodle', 'potato', 'pizza', 'macaroni', 'muffin', 'tortilla', 'pita']
        if calculated_carbs < 5.0 and any(kw in food_name.lower() for kw in carb_keywords):
            calculated_carbs = (avg_calories * 0.6) / 4.0
        
        p = avg_protein
        c = calculated_carbs
        f = avg_fat
        cals = avg_calories
        name_lc = food_name.lower()
        
        if any(meat in name_lc for meat in ['beef', 'pork', 'chicken', 'turkey', 'lamb', 'steak', 'sausage']):
            category = 'proteins'
        elif p > c and p > f:
            category = 'proteins'
        elif c > p and cals < 100 and f < 5:
            category = 'fibrous_veggies'
        elif c > p and c > f and cals >= 100:
            category = 'complex_carbs'
        elif f > p and f > c:
            category = 'fats'
        else:
            category = 'complex_carbs'
        
        return {
            'protein': round(avg_protein, 2),
            'calories': round(avg_calories, 2),
            'fat': round(avg_fat, 2),
            'fiber': round(avg_fiber, 2),
            'sodium': round(avg_sodium, 2),
            'cholesterol': round(avg_cholesterol, 2),
            'sugar': round(avg_sugar, 2),
            'carbs': round(calculated_carbs, 2),
            'portion_weight_g': 100.0,
            'category': category
        }
    
    
    def is_safe_from_blacklist(self, food_name: str, blacklist: set, user_profile: Dict = None, food_metadata: Dict = None) -> bool:
        if not blacklist and not user_profile:
            return True
        
        food_lower = food_name.lower()
        name_lc = food_lower
        
        if user_profile:
            medical_conditions = user_profile.get('medical_conditions', [])
            
            is_metabolic_profile = any(
                'type 2 diabetes' in str(cond).lower() or 
                'type 2' in str(cond).lower() or
                'insulin resistance' in str(cond).lower() or
                'pcos' in str(cond).lower() or
                'polycystic' in str(cond).lower()
                for cond in medical_conditions
            )
            
            if is_metabolic_profile:
                refined_carbs = ['pasta', 'bun', 'white bread', 'white rice', 'macaroni', 'noodle', 'spaghetti', 'pizza base', 'polished rice', 'jasmine rice', 'basmati rice']
                if any(carb in name_lc for carb in refined_carbs):
                    logger.debug(f" ANTI-REFINED CARB SHIELD: '{food_name}' blocked for metabolic profile")
                    return False
        
        if blacklist:
            for banned_word in blacklist:
                exception_phrases = BLACKLIST_EXCEPTIONS.get(banned_word, [])
                has_exception = any(exception.lower() in food_lower for exception in exception_phrases)
                
                if has_exception:
                    logger.debug(f" EXCEPTION ALLOWED: '{food_name}' bypasses '{banned_word}' blacklist (compound word exception)")
                    continue  
                
                pattern = r'\b' + re.escape(banned_word.lower()) + r'\b'
                if re.search(pattern, food_lower):
                    logger.debug(f" HARD-DELETE: '{food_name}' blocked by '{banned_word}'")
                    return False
        
        return True
    
