        def _get_food_family(food_name: str) -> set:
            """
            Detect food family membership (berries, cruciferous, nuts, etc.)
            Returns set of families this food belongs to.
            Example: "Fresh Blackberries" → {'berries'}
            """
            food_lower = food_name.lower()
            families = set()
            for family_name, family_members in FOOD_FAMILIES.items():
                for member in family_members:

                    if f' {member} ' in f' {food_lower} ' or food_lower.startswith(f'{member} ') or food_lower.endswith(f' {member}') or food_lower == member:
                        families.add(family_name)
                        break
            return families
        

        # 🍹 BREAKFAST SMOOTHIE REDUCTION - If smoothie/shake available, reduce solid foods
        breakfast_smoothie_mode = False
        if meal_key == 'breakfast':
            # Check if beverage slot has smoothies/shakes available
            SMOOTHIE_SHAKE_KEYWORDS = [
                'smoothie', 'shake', 'protein shake', 'milkshake', 'milk shake',
                'berry smoothie', 'fruit smoothie', 'green smoothie', 'mango smoothie',
                'banana smoothie', 'chocolate shake', 'vanilla shake'
            ]
            
            beverage_pool = self.slot_pools.get('beverage', [])
            warm_beverage_pool = self.slot_pools.get('warm_beverage', [])
            all_beverage_options = beverage_pool + warm_beverage_pool
            
            # Check if smoothies/shakes are available
            available_smoothies = [
                food for food in all_beverage_options
                if any(kw in food.lower() for kw in SMOOTHIE_SHAKE_KEYWORDS)
            ]
            
            if available_smoothies:
                logger.info(f" 🍹 BREAKFAST SMOOTHIE MODE: {len(available_smoothies)} smoothie/shake options detected")
                logger.info(f"    Optimizing breakfast: Smoothie + Protein source + Optional light item")
                logger.info(f"    Available smoothies: {', '.join(available_smoothies[:3])}")
                breakfast_smoothie_mode = True
                
                # Keep protein + smoothie + optional light item (2-3 items total)
                # Structure: Component 1 (protein) + Component 2 (smoothie) + Component 3 (fruit/nut - optional)
                if len(required_slots) >= 3:
                    # Keep all 3: protein + beverage + light item
                    # Don't reduce slots - just prioritize smoothies in beverage slot
                    logger.info(f"    Keeping {len(required_slots)} components: Protein + Smoothie + Light item")
        
        # 🍽️ CUISINE-BASED MEAL COMBINATION FILTERING
        # Determine valid sub-categories for this meal based on cuisine
        user_cuisine = user_profile.get('cuisine', 'global') if user_profile else 'global'
        # 🔒 FIX: Split comma-separated cuisine string from database
        if isinstance(user_cuisine, str) and ',' in user_cuisine:
            user_cuisine = [c.strip() for c in user_cuisine.split(',') if c.strip()]
        if isinstance(user_cuisine, list):
            user_cuisine = user_cuisine[0] if user_cuisine else 'global'
        user_cuisine_normalized = normalize_cuisine(user_cuisine) if user_cuisine else 'global'
        
        # Generate a seed based on day for reproducibility within same day but variety across days
        import hashlib as _hashlib
        day_variation = getattr(self, '_current_plan_variation', 0)
        day_seed_str = f"{user_profile.get('user_id', 'default')}_{meal_key}_{day_variation}"
        day_seed = int(_hashlib.md5(day_seed_str.encode()).hexdigest()[:8], 16)
        
        valid_sub_categories = get_valid_sub_categories_for_meal(
            user_cuisine_normalized, meal_key, seed=day_seed
        )
        
        # Per-slot category mapping: index → source category (for targeted filtering)
        per_slot_category = {}
        
        if valid_sub_categories:
            logger.info(f"  🍽️ CUISINE COMBINATION RULE ({user_cuisine_normalized}/{meal_key}):")
            logger.info(f"    Selected combo: {valid_sub_categories}")
            
            # 🔧 AUTO-EXTEND: If combo has fewer than 4 categories for lunch/dinner, add salad slot
            if meal_key in ('lunch', 'dinner') and len(valid_sub_categories) < 4:
                # Check if combo already has a salad-like category
                has_salad_cat = any('salad' in cat.lower() for cat in valid_sub_categories)
                if not has_salad_cat:
                    valid_sub_categories = list(valid_sub_categories) + ['Salads']
                    logger.info(f"    🥗 AUTO-EXTEND: Added 'Salads' as 4th category ({len(valid_sub_categories)} total)")
                else:
                    # Already has salad - add cooked vegetable or soup for variety
                    if meal_key == 'dinner':
                        valid_sub_categories = list(valid_sub_categories) + ['Soups']
                        logger.info(f"    🍲 AUTO-EXTEND: Added 'Soups' as 4th category for dinner")
                    else:
                        valid_sub_categories = list(valid_sub_categories) + ['Cooked vegetable dishes']
                        logger.info(f"    🥦 AUTO-EXTEND: Added 'Cooked vegetable dishes' as 4th category for lunch")
            
            # 🔧 SLOT OVERRIDE: Convert cuisine combo categories to technical slot names
            # This REPLACES the generic TDEE-based slots with cuisine-specific structure
            cuisine_derived_slots_with_cats = convert_combo_to_slots_with_categories(valid_sub_categories)
            if cuisine_derived_slots_with_cats:
                cuisine_derived_slots = [slot_options for slot_options, _ in cuisine_derived_slots_with_cats]
                # Build per-slot category mapping (0-indexed)
                for idx, (slot_options, source_cat) in enumerate(cuisine_derived_slots_with_cats):
                    per_slot_category[idx] = source_cat
                logger.info(f"    🔄 SLOT OVERRIDE: Replacing {len(required_slots)} generic slots with {len(cuisine_derived_slots)} cuisine-derived slots")
                logger.info(f"    Generic slots were: {required_slots}")
                logger.info(f"    Cuisine-derived slots: {cuisine_derived_slots}")
                logger.info(f"    Per-slot categories: {per_slot_category}")
                required_slots = cuisine_derived_slots
            else:
                logger.warning(f"    ⚠️ SLOT OVERRIDE FAILED: Could not map combo to slots, keeping generic structure")
        else:
            logger.debug(f"  No cuisine combination rules for {user_cuisine_normalized}/{meal_key} - using unrestricted selection")
        
        # 🚫 DINNER NUT BLOCK: Flag for blocking nuts/seeds in dinner
        is_dinner_meal = 'dinner' in meal_key.lower()
        if is_dinner_meal:
            logger.info(f"  🚫 DINNER NUT BLOCK: Active - No nuts/seeds will be selected for dinner")
        
        for component_idx, component_options in enumerate(required_slots, 1):
            logger.debug(f"    Component {component_idx}/{len(required_slots)}: {' OR '.join(component_options)}")
            
            protein_slots = ['protein_source', 'lean_protein', 'protein_snack', 'nut_seed']
            has_protein_option = any(slot in protein_slots for slot in component_options)
            
            if has_protein_option and component_idx == 1:
                if 'breakfast' in meal_key.lower():
                    logger.info(f"    🥜 BREAKFAST PROTEIN PRIORITY: Component 1 prioritizes protein sources: {component_options[0]}")
                elif 'snack' in meal_key.lower():
                    logger.info(f"    🥜 SNACK PROTEIN PRIORITY: Component 1 prioritizes protein sources: {component_options[0]}")
            
            meal_components = []
            for existing_item in meal_items:
                meal_components.append({
                    'name': existing_item.get('name', ''),
                    'macros': self.all_foods_macros.get(existing_item.get('name', ''), {})
                })
            
            selected_food = None
            selected_from_slot = None
            
            for slot_name in component_options:
                slot_food_pool = self.slot_pools.get(slot_name, [])
                
                if not slot_food_pool:
                    logger.debug(f"      Slot '{slot_name}' is empty, trying next option...")
                    continue
                
                # � WEEKLY HARD EXCLUSION (FIRST FILTER - before all others)
                # Remove foods that appeared 2+ times this week - NO BYPASS POSSIBLE
                weekly_excluded = getattr(self, 'weekly_hard_excluded', set())
                if weekly_excluded:
                    def _is_weekly_overused(food_name):
                        name = food_name.lower().strip()
                        if name in weekly_excluded:
                            return True
                        PREP_WORDS = ['homemade', 'cooked', 'baked', 'grilled', 'braised', 'roasted', 
                                      'steamed', 'pan-cooked', 'fresh', 'raw', 'added', 'with added fat', 'with veggies']
                        base = name
                        for prep in sorted(PREP_WORDS, key=len, reverse=True):
                            base = base.replace(prep, '')
                        base = ' '.join(base.split()).strip(' ,')
                        return base in weekly_excluded if base else False
                    
                    non_overused_pool = [f for f in slot_food_pool if not _is_weekly_overused(f)]
                    excluded_count = len(slot_food_pool) - len(non_overused_pool)
                    if non_overused_pool:
                        if excluded_count > 0:
                            logger.info(f"      🚫 WEEKLY EXCLUDE: Removed {excluded_count} overused foods from '{slot_name}', {len(non_overused_pool)} remain")
                        slot_food_pool = non_overused_pool
                    else:
                        # ALL foods in this slot are weekly-overused - SKIP this slot entirely
                        logger.warning(f"      🚫 WEEKLY EXCLUDE: ALL {len(slot_food_pool)} foods in '{slot_name}' are weekly-overused - trying next slot option")
                        continue  # Try next slot_name in component_options
                
                # �🚀 CROSS-DAY CATEGORY FILTER (April 30, 2026): Prevent same food_category consecutive days
                if used_food_categories:
                    category_filtered_pool = []
                    for food_name in slot_food_pool:
                        if food_name in self.all_foods_macros:
                            food_category = self.all_foods_macros[food_name].get('food_category', '').lower().strip()
                            if food_category and food_category in used_food_categories:
                                logger.debug(f"      CROSS-DAY CATEGORY BLOCK: '{food_name}' (category='{food_category}' used in previous days)")
                                continue
                        category_filtered_pool.append(food_name)
                    
                    if category_filtered_pool:
                        logger.info(f"      CROSS-DAY CATEGORY FILTER: {len(slot_food_pool)} → {len(category_filtered_pool)} foods (removed {len(slot_food_pool) - len(category_filtered_pool)} previously used categories)")
                        slot_food_pool = category_filtered_pool
                    elif len(slot_food_pool) > 0:
                        # All foods blocked by category - allow repetition to prevent meal generation failure
                        logger.warning(f"      CROSS-DAY CATEGORY WARNING: All {len(slot_food_pool)} foods in '{slot_name}' have previously used categories - allowing repetition")
                        # Keep original pool
                
                # 🍹 BREAKFAST SMOOTHIE PRIORITY - Prioritize smoothies/shakes over tea/coffee
                if breakfast_smoothie_mode and slot_name in ['beverage', 'warm_beverage']:
                    SMOOTHIE_SHAKE_KEYWORDS = [
                        'smoothie', 'shake', 'protein shake', 'milkshake', 'milk shake',
                        'berry smoothie', 'fruit smoothie', 'green smoothie', 'mango smoothie',
                        'banana smoothie', 'chocolate shake', 'vanilla shake'
                    ]
                    
                    smoothie_pool = [
                        food for food in slot_food_pool
                        if any(kw in food.lower() for kw in SMOOTHIE_SHAKE_KEYWORDS)
                    ]
                    
                    if smoothie_pool:
                        logger.info(f"      🍹 SMOOTHIE PRIORITY: Using {len(smoothie_pool)} smoothies/shakes from '{slot_name}' (ignoring tea/coffee)")
                        slot_food_pool = smoothie_pool  # Override pool to only smoothies
                    else:
                        logger.warning(f"      No smoothies available in '{slot_name}' - falling back to regular beverages")
                
                if meal_has_legume:
                    LEGUME_KEYWORDS_FOR_FILTER = [
                        'lentil', 'lentils', 'dal', 'daal', 'dhal', 'masoor', 'moong', 'mung',
                        'toor', 'tur', 'urad', 'urid', 'arhar', 'chana', 'chole', 
                        'chickpea', 'chickpeas', 'garbanzo', 'gram',
                        'hummus', 'falafel',
                        'bean', 'beans', 'rajma', 'kidney bean', 'black bean', 'pinto', 
                        'navy bean', 'white bean', 'lima bean', 'fava', 'broad bean',
                        'black-eyed', 'black eyed', 'cowpea', 'pigeon pea',
                        'pea', 'peas', 'split pea', 'green pea',
                        'soy', 'soya', 'soybean', 'tofu', 'tempeh', 'edamame'
                    ]
                    
                    original_pool_size = len(slot_food_pool)
                    slot_food_pool = [
                        food for food in slot_food_pool
                        if not any(kw in food.lower() for kw in LEGUME_KEYWORDS_FOR_FILTER)
                    ]
                    
                    if len(slot_food_pool) < original_pool_size:
                        logger.info(f"        GLOBAL LEGUME BLOCK: Meal already has legume - filtered {original_pool_size - len(slot_food_pool)} legume items from '{slot_name}' ({original_pool_size} → {len(slot_food_pool)})")
                        logger.info(f"         Prevents legume stacking like 'Black Eyed Peas Curry + Black-Eyed Peas Salad + Bean Casserole'")
                    
                    if not slot_food_pool:
                        logger.debug(f"      Slot '{slot_name}' empty after legume filtering - trying next option...")
                        continue
                
                # 🚫 DINNER NUT/SEED BLOCK: Remove all nut/seed foods from dinner
                if is_dinner_meal:
                    original_pool_size = len(slot_food_pool)
                    slot_food_pool = [
                        food for food in slot_food_pool
                        if not is_nut_or_seed_food(food, self.all_foods_macros.get(food, {}))
                    ]
                    nuts_removed = original_pool_size - len(slot_food_pool)
                    if nuts_removed > 0:
                        logger.info(f"      🚫 DINNER NUT BLOCK: Removed {nuts_removed} nut/seed items from '{slot_name}' ({original_pool_size} → {len(slot_food_pool)})")
                    
                    if not slot_food_pool:
                        logger.debug(f"      Slot '{slot_name}' empty after dinner nut blocking - trying next option...")
                        continue
                
                # 🔒 CONDIMENT/SPREAD BLOCK FROM PROTEIN SLOTS: Prevent spreads/sauces from filling main slots
                PROTEIN_SLOT_NAMES = {'protein_main', 'protein_source', 'lean_protein'}
                if slot_name in PROTEIN_SLOT_NAMES and slot_food_pool:
                    original_pool_size = len(slot_food_pool)
                    non_condiment_pool = [
                        food for food in slot_food_pool
                        if self.all_foods_macros.get(food, {}).get('food_category', '').lower().strip() 
                           not in ('condiments, sauces & add-ons',)
                    ]
                    if len(non_condiment_pool) >= 2:
                        slot_food_pool = non_condiment_pool
                        removed = original_pool_size - len(slot_food_pool)
                        if removed > 0:
                            logger.info(f"      🔒 CONDIMENT BLOCK: Removed {removed} condiment/sauce foods from protein slot '{slot_name}' ({original_pool_size} → {len(slot_food_pool)})")
                    # else: keep original pool (don't starve the slot)
                
                # 🍽️ CUISINE COMBINATION FILTER: Filter foods by PER-SLOT source category
                # Use per-slot category (specific to this slot) instead of all categories
                slot_category = per_slot_category.get(component_idx - 1)  # component_idx is 1-based
                filter_categories = [slot_category] if slot_category else valid_sub_categories
                if filter_categories and slot_food_pool:
                    original_pool_size = len(slot_food_pool)
                    cuisine_filtered_pool = [
                        food for food in slot_food_pool
                        if is_food_in_sub_categories(self.all_foods_macros.get(food, {}), filter_categories)
                    ]
                    
                    # Only apply filter if we still have enough foods (min 2)
                    if len(cuisine_filtered_pool) >= 2:
                        slot_food_pool = cuisine_filtered_pool
                        filtered_count = original_pool_size - len(slot_food_pool)
                        if filtered_count > 0:
                            logger.info(f"      🍽️ CUISINE COMBO FILTER: '{slot_name}' filtered {filtered_count} items by category '{slot_category or 'all'}' ({original_pool_size} → {len(slot_food_pool)})")
                    elif len(cuisine_filtered_pool) >= 1:
                        # At least 1 food matches - use it but log warning
                        slot_food_pool = cuisine_filtered_pool
                        logger.warning(f"      🍽️ CUISINE COMBO: Only {len(cuisine_filtered_pool)} food(s) match category '{slot_category or 'all'}' in '{slot_name}' - using available")
                    else:
                        # No foods match - keep original pool to prevent meal generation failure
                        logger.warning(f"      🍽️ CUISINE COMBO: No foods in '{slot_name}' match category '{slot_category or 'all'}' ({filter_categories}) - using unrestricted pool")
                
                # 🔒 INTRA-DAY FOOD_ID DEDUP: Block foods already used in other meals today
                if self.daily_used_food_ids and slot_food_pool:
                    original_pool_size = len(slot_food_pool)
                    id_filtered_pool = [
                        food for food in slot_food_pool
                        if self.all_foods_macros.get(food, {}).get('_food_id', '') not in self.daily_used_food_ids
                        or not self.all_foods_macros.get(food, {}).get('_food_id', '')
                    ]
                    if len(id_filtered_pool) >= 2:
                        slot_food_pool = id_filtered_pool
                        removed = original_pool_size - len(slot_food_pool)
                        if removed > 0:
                            logger.info(f"      🔒 FOOD_ID DEDUP: Removed {removed} already-used foods from '{slot_name}' ({original_pool_size} → {len(slot_food_pool)})")
                    elif id_filtered_pool:
                        slot_food_pool = id_filtered_pool
                    # else: keep original pool if all foods would be blocked
                
                # 🔒 INTRA-MEAL SUB_CATEGORY DEDUP: Block foods from already-used sub-categories
                if meal_used_sub_categories and slot_food_pool:
                    original_pool_size = len(slot_food_pool)
                    sub_cat_filtered = [
                        food for food in slot_food_pool
                        if (self.all_foods_macros.get(food, {}).get('sub_food_category', '').lower().strip() 
                            not in meal_used_sub_categories)
                        or not self.all_foods_macros.get(food, {}).get('sub_food_category', '')
                    ]
                    if len(sub_cat_filtered) >= 2:
                        slot_food_pool = sub_cat_filtered
                        removed = original_pool_size - len(slot_food_pool)
                        if removed > 0:
                            logger.info(f"      🔒 SUB-CATEGORY DEDUP: Removed {removed} items with already-used sub-categories from '{slot_name}' ({original_pool_size} → {len(slot_food_pool)})")
                            logger.debug(f"         Used sub-categories: {sorted(meal_used_sub_categories)}")
                    elif sub_cat_filtered:
                        slot_food_pool = sub_cat_filtered
                    # else: keep original pool
                
                # 🔒 SPREAD/SAUCE LIMIT: Max 1 spread/sauce/dip per meal (they need companions)
                if meal_has_spread_or_sauce and slot_food_pool:
                    original_pool_size = len(slot_food_pool)
                    no_spread_pool = [
                        food for food in slot_food_pool
                        if not is_spread_or_sauce_food(self.all_foods_macros.get(food, {}))
                    ]
                    if len(no_spread_pool) >= 2:
                        slot_food_pool = no_spread_pool
                        removed = original_pool_size - len(slot_food_pool)
                        if removed > 0:
                            logger.info(f"      🔒 SPREAD/SAUCE LIMIT: Removed {removed} spread/sauce items from '{slot_name}' (meal already has one)")
                    elif no_spread_pool:
                        slot_food_pool = no_spread_pool
                    # else: keep original pool
                
                meal_tag_filtered = []
                meal_tag_lower = meal_name_normalized.lower()
                
                if 'breakfast' in meal_tag_lower:
                    required_tags = ['breakfast']
                elif 'morning' in meal_tag_lower and 'snack' in meal_tag_lower:
                    required_tags = ['snack', 'morning snack']  
                elif 'lunch' in meal_tag_lower:
                    required_tags = ['lunch']
                elif 'evening' in meal_tag_lower and 'snack' in meal_tag_lower:
                    required_tags = ['snack', 'evening snack'] 
                elif 'snack 2' in meal_tag_lower:
                    required_tags = ['snack', 'evening snack'] 
                elif 'dinner' in meal_tag_lower:
                    required_tags = ['dinner', 'lunch']  # Dinner accepts lunch-tagged foods too (proteins/grains are interchangeable)
                else:
                    required_tags = [] 
                
                strict_filtered = []
                fallback_filtered = []
                
                for food_name in slot_food_pool:
                    if food_name not in self.all_foods_macros:
                        continue
                    
                    food_macros = self.all_foods_macros[food_name]
                    food_meal_tags = food_macros.get('meal_tags', [])
                    
                    if not food_meal_tags:
                        strict_filtered.append(food_name)
                        continue
                    
                    food_tags_lower = [tag.lower().strip() for tag in food_meal_tags]
                    
                    if required_tags:

                        has_match = any(req_tag in food_tags_lower for req_tag in required_tags)
                        
                        if has_match:

                            strict_filtered.append(food_name)
                            logger.debug(f"         TAG MATCH: '{food_name}' has required tag(s) {required_tags} (all tags: {food_tags_lower})")
                        else:
                            fallback_filtered.append(food_name)
                            logger.debug(f"        POOL FILTER: '{food_name}' in fallback pool (tags: {food_tags_lower}, required: {required_tags})")
                    else:
                        strict_filtered.append(food_name)
                
                if strict_filtered:
                    meal_tag_filtered = strict_filtered
                    logger.debug(f"      ✅ Slot '{slot_name}': {len(strict_filtered)} foods match meal tag (strict)")
                elif fallback_filtered:
                    # 🚨 STRICT MEAL TIMING ENFORCEMENT - Only allow fallback if pool is critically small
                    MIN_STRICT_THRESHOLD = 3  # Require at least 3 properly tagged foods
                    
                    if len(strict_filtered) < MIN_STRICT_THRESHOLD:
                        BREAKFAST_CEREAL_KEYWORDS = [
                            'oat', 'oats', 'porridge', 'oatmeal', 'muesli', 'granola', 'cereal',
                            'cornflakes', 'corn flakes', 'wheat flakes', 'bran flakes', 'bircher',
                            'cheerios', 'special k', 'frosted flakes',
                            'overnight oat', 'steel cut oat', 'rolled oat',
                            'almond granola', 'honey granola', 'granola bar', 'granola cluster'
                        ]

                        strict_fallback = []
                        for food in fallback_filtered:
                            food_macros = self.all_foods_macros.get(food, {})
                            food_meal_tags = food_macros.get('meal_tags', [])
                            food_tags_lower = [tag.lower().strip() for tag in food_meal_tags]

                            # ❌ BLOCK breakfast-only items from lunch/dinner
                            if ('lunch' in meal_tag_lower or 'dinner' in meal_tag_lower):
                                is_breakfast_only = ('breakfast' in food_tags_lower and 
                                                   len(food_tags_lower) == 1) 
                                if is_breakfast_only:
                                    logger.debug(f"         ❌ EXCLUSIVE BLOCK: '{food}' is BREAKFAST-ONLY item, blocked from {meal_name_normalized}")
                                    continue
                            
                            # ❌ BLOCK evening items from morning snacks
                            if 'morning' in meal_tag_lower and 'snack' in meal_tag_lower:
                                is_evening_only = (('evening snack' in food_tags_lower or 'dinner' in food_tags_lower) and
                                                 'morning snack' not in food_tags_lower and 'breakfast' not in food_tags_lower)
                                if is_evening_only:
                                    logger.debug(f"         ❌ EXCLUSIVE BLOCK: '{food}' is EVENING-ONLY item, blocked from Morning Snack")
                                    continue
                            
                            # ❌ BLOCK morning items from evening snacks
                            if 'evening' in meal_tag_lower and 'snack' in meal_tag_lower:
                                is_morning_only = (('morning snack' in food_tags_lower or 'breakfast' in food_tags_lower) and
                                                 'evening snack' not in food_tags_lower and 'dinner' not in food_tags_lower)
                                if is_morning_only:
                                    logger.debug(f"         ❌ EXCLUSIVE BLOCK: '{food}' is MORNING-ONLY item, blocked from Evening Snack")
                                    continue
                            
                            strict_fallback.append(food)
                        
                        fallback_filtered = strict_fallback
                        
                        # ❌ BLOCK breakfast cereals from non-breakfast meals
                        if ('lunch' in meal_tag_lower or 'dinner' in meal_tag_lower or 'snack' in meal_tag_lower):
                            fallback_filtered = [
                                food for food in fallback_filtered
                                if not any(kw in food.lower() for kw in BREAKFAST_CEREAL_KEYWORDS)
                            ]
                            
                            # 🔒 STRICT GRAIN FILTERING for lunch/dinner
                            if slot_name in ['grain_base', 'starch_base', 'light_grain']:
                                properly_tagged_foods = []
                                for food in fallback_filtered:
                                    if food not in self.all_foods_macros:
                                        continue  # ❌ Skip foods without macro data
                                    
                                    food_macros = self.all_foods_macros[food]
                                    food_meal_tags = food_macros.get('meal_tags', [])
                                    food_tags_lower = [tag.lower().strip() for tag in food_meal_tags]
                                    

                                    has_lunch_or_dinner = any(tag in food_tags_lower for tag in ['lunch', 'dinner'])
                                    

                                    if has_lunch_or_dinner:
                                        properly_tagged_foods.append(food)
                                        logger.debug(f"          ✅ GRAIN SHARED: '{food}' tagged for lunch/dinner (usable in both)")
                                    elif not food_meal_tags:
                                        # ❌ STRICTER: Don't allow untagged grains in lunch/dinner by default
                                        logger.debug(f"          ❌ GRAIN BLOCKED: '{food}' has no meal tags (requires explicit lunch/dinner tag)")
                                    else:
                                        logger.debug(f"          ❌ GRAIN BLOCKED: '{food}' tagged for {food_tags_lower} (not lunch/dinner)")
                                
                                fallback_filtered = properly_tagged_foods
                            
                            if not fallback_filtered:
                                logger.debug(f"      ❌ Slot '{slot_name}': All fallback foods blocked (cereals or improper meal tags)")
                                continue
                        
                        meal_tag_filtered = fallback_filtered
                        if meal_tag_filtered:
                            logger.warning(f"      ⚠️ Slot '{slot_name}': Using {len(fallback_filtered)} STRICTLY FILTERED fallback foods (wrong-meal items removed)")
                            logger.warning(f"         Only foods compatible with {required_tags} allowed (strict cross-meal rules enforced)")
                        else:
                            logger.debug(f"      ❌ Slot '{slot_name}': All fallback foods rejected by strict meal timing rules")
                            continue
                    else:
                        # Pool is large enough - NO fallback allowed
                        logger.warning(f"      ❌ Slot '{slot_name}': Fallback DISABLED - {len(strict_filtered)} properly tagged foods available (min: {MIN_STRICT_THRESHOLD})")
                        logger.warning(f"         Enforcing STRICT meal timing - only properly tagged foods allowed")
                        continue
                else:
                    logger.debug(f"      Slot '{slot_name}': No foods available after meal tag filtering, trying next option...")
                    continue

                
                def _fuzzy_similarity(name1: str, name2: str) -> float:
                    
                    
                    SIMILARITY_STOP_WORDS = {
                        'homemade', 'fresh', 'organic', 'with', 'and', 'the', 'a', 'an', 'of', 'in',
                        'baked', 'grilled', 'cooked', 'braised', 'steamed', 'boiled', 'roasted', 'sauteed', 'fried', 'style',
                        'american', 'italian', 'french', 'indian', 'chinese', 'japanese', 'mexican', 'european', 'asian',
                        'peeled', 'chopped', 'sliced', 'diced', 'minced', 'shredded', 'grated', 'cubed', 'whole',
                        'raw', 'unsalted', 'salted', 'sweetened', 'unsweetened', 'light', 'dark', 'medium', 'dried',
                        'frozen', 'canned', 'packaged', 'mixed', 'plain', 'natural'
                    }
                    
                    def normalize_word(word: str) -> str:
                        word = ''.join(char for char in word if char not in string.punctuation)
                        
                        if not word:  
                            return ''
                        
                        if word.endswith('ies') and len(word) > 4:  
                            return word[:-3] + 'y'
                        elif word.endswith('oes') and len(word) > 4: 
                            return word[:-2]
                        elif word.endswith('es') and len(word) > 3: 
                            if word[-3] not in 'aeiou':  
                                return word[:-2]
                            return word[:-1] 
                        elif word.endswith('s') and len(word) > 3:  
                            return word[:-1]
                        return word
                    
                    words1 = {
                        normalize_word(w) 
                        for w in name1.lower().split() 
                        if normalize_word(w) and normalize_word(w) not in SIMILARITY_STOP_WORDS and len(normalize_word(w)) > 2
                    }
                    words2 = {
                        normalize_word(w) 
                        for w in name2.lower().split() 
                        if normalize_word(w) and normalize_word(w) not in SIMILARITY_STOP_WORDS and len(normalize_word(w)) > 2
                    }
                    
                    if not words1 or not words2:
                        return 0.0
                    
                    intersection = words1 & words2
                    union = words1 | words2
                    
                    return len(intersection) / len(union) if union else 0.0
                
                SIMILARITY_THRESHOLD = 0.25  


                is_mandatory_grain_slot = (
                    component_idx == 2 and 
                    meal_key in ['lunch', 'dinner'] and 
                    slot_name in ['grain_base', 'starch_base', 'light_grain']
                )

                used_food_families = set()

                used_food_families.update(meal_used_families)
                
                diversity_filtered = []
                blocked_by_family = []
                blocked_by_similarity = []
                
                for food_name in meal_tag_filtered:
                    is_duplicate = False
                    block_reason = None
                    
                    food_families = _get_food_family(food_name)
                    
                    # 🔒 AUGMENT family detection with DB sub_food_category
                    # Catches items like "Edamame And Veggie Bowl" which has quinoa as ingredient
                    # but doesn't mention "quinoa" in the display name
                    food_macros_for_family = self.all_foods_macros.get(food_name, {})
                    food_sub_cat_for_family = food_macros_for_family.get('sub_food_category', '').lower().strip()
                    if food_sub_cat_for_family:
                        # Map common sub_food_category values to FOOD_FAMILIES keys
                        SUB_CAT_TO_FAMILY = {
                            'tofu': 'soy_tofu', 'tempeh': 'soy_tofu', 'edamame': 'soy_tofu', 'soy': 'soy_tofu',
                            'quinoa': 'grains', 'rice': 'grains', 'oat': 'grains', 'oats': 'grains',
                            'wheat': 'grains', 'barley': 'grains', 'millet': 'grains',
                            'lentil': 'legumes', 'lentils': 'legumes', 'chickpea': 'legumes', 
                            'bean': 'legumes', 'beans': 'legumes', 'pea': 'legumes',
                            'bread': 'bread_bakery', 'toast': 'bread_bakery', 'loaf': 'bread_bakery',
                            'berry': 'berries', 'berries': 'berries',
                            'nut': 'nuts', 'nuts': 'nuts', 'almond': 'nuts', 'walnut': 'nuts',
                            'seed': 'seeds', 'seeds': 'seeds',
                        }
                        for sub_cat_keyword, family_name in SUB_CAT_TO_FAMILY.items():
                            if sub_cat_keyword in food_sub_cat_for_family:
                                food_families.add(family_name)
                                break
                    
                    # 🔒 STRICTER: Only allow grain exemption if pool is CRITICALLY small (< 2 items)
                    grain_exemption_active = (is_mandatory_grain_slot and len(meal_tag_filtered) < 2)
                    
                    is_snack_meal = 'snack' in meal_name.lower()

                    # 🔒 STRICTER: Only allow snack exemption if pool is VERY small (< 3 items)
                    snack_exemption_active = (is_snack_meal and len(meal_tag_filtered) < 3)

                    if food_families & used_food_families and not grain_exemption_active and not snack_exemption_active: 
                        overlapping_families = food_families & used_food_families
                        is_duplicate = True
                        block_reason = f"FAMILY: {', '.join(overlapping_families)} (already used in this meal)"
                        blocked_by_family.append((food_name, overlapping_families))
                        logger.debug(f"        ❌ FAMILY BLOCKED: '{food_name}' → families {food_families} overlap with meal families {used_food_families}")

                    # 🔒 FOOD TYPE BLOCKING - Prevent multiple items of same TYPE in one day
                    # This blocks: "barley khichdi" + "bajra khichdi" + "moong dal khichdi" (all are khichdi type)
                    if not is_duplicate:
                        food_name_normalized = food_name.lower().strip()
                        
                        FOOD_TYPE_KEYWORDS = {
                            'khichdi': ['khichdi', 'khichadi', 'kichdi'],
                            'curry': ['curry', 'curries', 'korma', 'masala curry'],
                            'dal': ['dal', 'daal', 'dhal', 'lentil curry'],
                            'pulao': ['pulao', 'pilaf', 'pilau'],
                            'biryani': ['biryani', 'biriyani'],
                            'paratha': ['paratha', 'parantha'],
                            'dosa': ['dosa', 'dosai'],
                            'idli': ['idli', 'idly'],
                            'upma': ['upma', 'uppuma'],
                            'poha': ['poha', 'pohe'],
                            'salad': ['salad', 'slaw'],
                            'sandwich': ['sandwich', 'wrap', 'burger'],
                            # REMOVED umbrella categories that blocked entire food groups daily:
                            # - 'heavy_carb': per-meal grain limit already prevents duplicates
                            # - 'protein_dish': individual checks + protein_family check suffice
                            # - 'nut_seed': different nuts across meals is fine
                            # REMOVED individual protein types (tofu, paneer, egg) from daily blocking:
                            # - Having tofu at breakfast and dinner is nutritionally fine
                            # - Per-meal food_category check prevents tofu+tofu in same meal
                            # - Cross-meal protein_family check handles variety
                        }
                        
                        # Detect food type of current item
                        food_type = None
                        for type_name, keywords in FOOD_TYPE_KEYWORDS.items():
                            if any(kw in food_name_normalized for kw in keywords):
                                food_type = type_name
                                break
                        
                        # Check if this food type was already used today (2 methods)
                        if food_type:
                            # Method 1: Check for TYPE marker (faster)
                            type_marker = f"__TYPE_{food_type}"
                            if type_marker in self.daily_used_foods:
                                is_duplicate = True
                                block_reason = f"FOOD TYPE MARKER: '{food_type}' already used today"
                                blocked_by_similarity.append((food_name, f"<{food_type} type>", 0.99))
                                logger.debug(f"       ❌ FOOD TYPE BLOCKED (marker): '{food_name}' ({food_type}) already used today")
                            else:
                                # Method 2: Check actual food names for keywords (fallback)
                                for used_food in self.daily_used_foods:
                                    if used_food.startswith('__TYPE_'):
                                        continue  # Skip type markers
                                    used_food_normalized = used_food.lower().strip()
                                    # Check if used food has the same type
                                    for kw in FOOD_TYPE_KEYWORDS.get(food_type, []):
                                        if kw in used_food_normalized:
                                            is_duplicate = True
                                            block_reason = f"FOOD TYPE: '{food_type}' already used as '{used_food}'"
                                            blocked_by_similarity.append((food_name, used_food, 0.98))
                                            logger.debug(f"       ❌ FOOD TYPE BLOCKED: '{food_name}' ({food_type}) already used as '{used_food}'")
                                            break
                                    if is_duplicate:
                                        break

                    if not is_duplicate:
                        food_name_normalized = food_name.lower().strip()
                                                # 🔒 ENHANCED BASE FOOD EXTRACTION - remove ALL variations
                        # This prevents: "bajra khichdi with bottle gourd" + "bajra khichdi with green beans"
                        base_food = food_name_normalized
                        for separator in [' with ', ' and ', ', ', ' (']:
                            base_food = base_food.split(separator)[0].strip()
                        
                        # Extract core words (remove cooking methods, descriptors)
                        COOKING_METHODS = ['grilled', 'baked', 'roasted', 'fried', 'steamed', 'boiled', 
                                          'sauteed', 'sautéed', 'tandoori', 'curried', 'stir fry', 'stir-fry']
                        base_words = []
                        for word in base_food.split():
                            if word not in COOKING_METHODS and len(word) > 2:
                                base_words.append(word)
                        core_food = ' '.join(base_words[:3]) if base_words else base_food  # Keep first 3 significant words
                        
                        for used_food in self.daily_used_foods:
                            used_food_normalized = used_food.lower().strip()
                            used_base_food = used_food_normalized
                            for separator in [' with ', ' and ', ', ', ' (']:
                                used_base_food = used_base_food.split(separator)[0].strip()
                            
                            # Extract core words from used food
                            used_base_words = []
                            for word in used_base_food.split():
                                if word not in COOKING_METHODS and len(word) > 2:
                                    used_base_words.append(word)
                            used_core_food = ' '.join(used_base_words[:3]) if used_base_words else used_base_food
                            
                            # Check: exact match, base food match, AND core food match
                            if food_name_normalized == used_food_normalized:
                                is_duplicate = True
                                block_reason = f"EXACT MATCH: '{used_food}' (already used today)"
                                blocked_by_similarity.append((food_name, used_food, 1.0))
                                logger.debug(f"       ❌ EXACT MATCH: '{food_name}' = '{used_food}' - BLOCKED")
                                break
                            elif base_food == used_base_food and len(base_food) > 3:
                                is_duplicate = True
                                block_reason = f"BASE FOOD MATCH: '{base_food}' already used as '{used_food}'"
                                blocked_by_similarity.append((food_name, used_food, 0.95))
                                logger.debug(f"       ❌ BASE FOOD MATCH: '{food_name}' base='{base_food}' matches '{used_food}' - BLOCKED")
                                break
                            elif core_food == used_core_food and len(core_food) > 5 and core_food != base_food:
                                is_duplicate = True
                                block_reason = f"CORE FOOD MATCH: '{core_food}' already used as '{used_food}'"
                                blocked_by_similarity.append((food_name, used_food, 0.90))
                                logger.debug(f"       ❌ CORE FOOD MATCH: '{food_name}' core='{core_food}' matches '{used_food}' - BLOCKED")
                                break
                    
                    if not is_duplicate:
                        diversity_filtered.append(food_name)
                    else:
                        logger.debug(f"       DUPLICATE BLOCKED: '{food_name}' - {block_reason}")
                
                blocked_count = len(meal_tag_filtered) - len(diversity_filtered)
                if blocked_count > 0:
                    if is_mandatory_grain_slot and len(meal_tag_filtered) < 3:
                        logger.info(f"       GRAIN DIVERSITY PROTECTION: Family blocking RELAXED for grain slot (only {len(meal_tag_filtered)} grains available)")
                        logger.info(f"         Preserving {len(diversity_filtered)} grain options to prevent same-day repetition")
                    if snack_exemption_active:
                        logger.info(f"        SNACK DIVERSITY RELAXED: Tiny pool ({len(meal_tag_filtered)} items < 5) - allowing family repetition")
                    logger.info(f"      DAILY UNIQUENESS: Blocked {blocked_count} foods ({len(blocked_by_family)} by meal family, {len(blocked_by_similarity)} by exact match)")
                    logger.info(f"       EXACT MATCHING: Blocks identical names + base food variations (e.g., 'khichdi with X')")
                    logger.info(f"       FAMILY BLOCKING: NOW CROSS-MEAL - prevents same family in Morning + Evening snacks")
                    if blocked_by_family:
                        family_examples = blocked_by_family[:3] 
                        for food, families in family_examples:
                            logger.info(f"       MEAL FAMILY BLOCKED: '{food}' (families: {', '.join(families)})")
                
                logger.debug(f"       FILTER CASCADE for '{slot_name}' (Component {component_idx}):")
                logger.debug(f"         START: {len(meal_tag_filtered)} foods after meal tag filter")
                logger.debug(f"         → Daily uniqueness: {len(diversity_filtered)} foods remain (-{blocked_count})")
                
                STOP_WORDS = {
                    'homemade', 'fresh', 'organic', 'with', 'and', 'the', 'a', 'an', 'of', 'in',
                    'baked', 'grilled', 'cooked', 'braised', 'steamed', 'boiled', 'roasted', 
                    'sautéed', 'sauteed', 'fried', 'stewed', 'poached', 'broiled', 'pan-fried',
                    'slow-cooked', 'pressure-cooked', 'raw', 'smoked', 'toasted', 'charred',
                    'marinated', 'glazed', 'caramelized', 'blanched', 'seared'
                }
                
                logger.debug(f"         SIMILARITY FILTER: ENABLED at 25% threshold + semantic family blocking")
                logger.debug(f"         → Similarity filter: {len(diversity_filtered)} unique foods remain (25% threshold + family blocking active)")
                
                
                if diversity_filtered:
                    FOOD_TYPE_KEYWORDS = {
                        'porridge': ['porridge', 'oatmeal', 'oats', 'muesli', 'bircher', 'overnight oats'],
                        'curry': ['curry', 'masala curry', 'korma', 'saag'],
                        'salad': ['salad', 'slaw', 'mixed greens'],
                        'soup': ['soup', 'broth', 'chowder', 'stew'],
                        'bread': ['roti', 'chapati', 'naan', 'paratha', 'bread', 'bun', 'loaf', 'toast',
                                  'bagel', 'roll', 'sandwich', 'slices', 'wrap', 'focaccia', 'ciabatta'],
                        'rice': ['rice', 'biryani', 'pulao', 'khichdi'],
                        'dal': ['dal', 'daal', 'lentil'],
                        'tofu': ['tofu', 'bean curd'],
                        'paneer': ['paneer', 'cottage cheese'],
                        'egg': ['egg', 'omelet', 'omelette', 'bhurji', 'scramble'],
                        'sandwich': ['sandwich', 'wrap', 'burger'],
                        # 🛡️ UMBRELLA CATEGORIES - Bypass unreliable database Food_category
                        'heavy_carb': ['pulao', 'biryani', 'khichdi', 'rice', 'roti', 'paratha', 'naan', 'chapati', 'dosa', 'idli', 'quinoa', 'pasta', 'bread', 'bagel', 'roll', 'loaf', 'toast', 'grits'],
                        'nut_seed': ['almond', 'walnut', 'cashew', 'pistachio', 'peanut', 'pumpkin seed', 'chia', 'flax', 'mixed nuts', 'sunflower seed', 'sesame'],
                        'protein_dish': ['tofu', 'tempeh', 'paneer', 'egg', 'chicken', 'fish', 'soy chunk', 'seitan'],
                    }
                    
                    meal_food_types = set()
                    for existing_item in meal_components:
                        existing_name = existing_item['name'].lower()
                        for food_type, keywords in FOOD_TYPE_KEYWORDS.items():
                            if any(kw in existing_name for kw in keywords):
                                meal_food_types.add(food_type)
                    
                    type_filtered = []
                    for food_name in diversity_filtered:
                        food_name_lower = food_name.lower()
                        
                        is_redundant = False
                        for food_type, keywords in FOOD_TYPE_KEYWORDS.items():
                            if food_type in meal_food_types:
                                if any(kw in food_name_lower for kw in keywords):
                                    is_redundant = True
                                    logger.debug(f"        REDUNDANCY FILTER: '{food_name}' is a {food_type} (already have one)")
                                    break
                        
                        if not is_redundant:
                            type_filtered.append(food_name)
                    
                    if not type_filtered:
                        logger.warning(f"       TYPE REDUNDANCY: All {len(diversity_filtered)} foods in slot '{slot_name}' match already-used types - trying next slot option")
                        logger.error(f"         → Type redundancy: 0 foods remain (-{len(diversity_filtered)})  ALL BLOCKED - BOTTLENECK!")
                        continue  
                    else:
                        final_filtered = type_filtered
                        if len(type_filtered) < len(diversity_filtered):
                            logger.info(f"       TYPE REDUNDANCY FILTER: Removed {len(diversity_filtered) - len(type_filtered)} redundant items")
                            logger.error(f"         → Type redundancy filter: {len(type_filtered)} foods remain (-{len(diversity_filtered) - len(type_filtered)})")
                        else:
                            logger.error(f"         → Type redundancy filter: {len(type_filtered)} foods remain (no redundancy)")
                else:
                    final_filtered = []
                
                if not final_filtered:
                    non_previous_meal_foods = [f for f in meal_tag_filtered if f not in self.previous_meal_foods]
                    
                    if non_previous_meal_foods:
                        logger.debug(f"      Slot '{slot_name}': All foods used in last {len(self.used_failsafes_previous_day)} day(s), but using {len(non_previous_meal_foods)} foods NOT from previous meal")
                        final_filtered = non_previous_meal_foods
                    else:
                        logger.debug(f"      Slot '{slot_name}': All foods recently used with no alternatives - trying next slot option")
                        continue  
                
                if meal_name_normalized.lower() in ['breakfast', 'lunch', 'dinner']:
                    dessert_keywords = ['dessert', 'candy', 'candied', 'sweet', 'cake', 'cookie', 
                                       'brownie', 'pie', 'tart', 'pudding', 'ice cream', 'frosting',
                                       'icing', 'chocolate bar', 'donut', 'doughnut', 'pastry']
                    
                    non_dessert_foods = []
                    for food_name in final_filtered:
                        food_name_lower = food_name.lower()
                        is_dessert = any(kw in food_name_lower for kw in dessert_keywords)
                        if not is_dessert:
                            non_dessert_foods.append(food_name)
                    
                    if non_dessert_foods:
                        final_filtered = non_dessert_foods
                
                STANDALONE_COOKING_INGREDIENTS = [
                    'heated butter', 'melted butter', 'butter (melted)', 'clarified butter', 'butter stick',
                    'ghee', 'pure ghee', 'heated ghee', 'clarified ghee',
                    'vegetable oil', 'olive oil', 'canola oil', 'coconut oil', 'sunflower oil',
                    'cooking oil', 'oil (heated)', 'heated oil', 'sesame oil', 'peanut oil',
                    'extra virgin olive oil', 'avocado oil', 'grapeseed oil', 'flaxseed oil',
                    'mustard oil', 'rice bran oil', 'palm oil', 'soybean oil',
                    'salt', 'table salt', 'sea salt', 'himalayan salt',
                    'sugar', 'white sugar', 'brown sugar', 'powdered sugar',
                    'ground pepper', 'black pepper', 'white pepper',
                    'raw onion', 'raw garlic', 'raw ginger', 'plain flour', 'all-purpose flour'
                ]
                
                non_cooking_ingredient_foods = []
                for food_name in final_filtered:
                    food_name_lower = food_name.lower().strip()
                    
                    is_cooking_ingredient = any(
                        ingredient == food_name_lower or food_name_lower.startswith(ingredient + ' ')
                        or food_name_lower.endswith(' ' + ingredient)
                        for ingredient in STANDALONE_COOKING_INGREDIENTS
                    )
                    
                    # Additional check: reject items that ARE just an oil/fat with no other substance
                    # e.g. "Extra Virgin Olive Oil" ends with " oil" and has no other food words
                    if not is_cooking_ingredient and food_name_lower.endswith(' oil'):
                        is_cooking_ingredient = True
                    
                    if not is_cooking_ingredient:
                        non_cooking_ingredient_foods.append(food_name)
                    else:
                        logger.debug(f"       REJECTED COOKING INGREDIENT: '{food_name}' (should be part of prepared dishes, not standalone)")
                
                if non_cooking_ingredient_foods:
                    final_filtered = non_cooking_ingredient_foods
                    logger.debug(f"       COOKING INGREDIENT FILTER: {len(non_cooking_ingredient_foods)} foods remain")
                    if len(non_cooking_ingredient_foods) < len(final_filtered):
                        logger.debug(f"         → Cooking ingredient filter: {len(non_cooking_ingredient_foods)} foods remain (-{len(final_filtered) - len(non_cooking_ingredient_foods)})")
                    else:
                        logger.debug(f"         → Cooking ingredient filter: {len(non_cooking_ingredient_foods)} foods remain (no ingredients)")
                else:
                    logger.warning(f"       COOKING INGREDIENT FILTER: All foods are standalone ingredients - keeping for emergency")
                

                
                before_group_filter_count = len(final_filtered)
                group_unique_filtered = []
                
                CRITICAL_GROUPS = {
                    'protein_main', 'protein_source', 'lean_protein', 
                    'grain_base', 'starch_base', 'light_grain',
                    'fruit', 'fruit_snack', 'nut_seed',
                    'primary_vegetable', 'cooked_vegetable',
                    'soup_or_broth', 'fermented_side'
                }
                
                for food_name in final_filtered:
                    if food_name not in self.all_foods_macros:
                        continue
                    
                    food_macros = self.all_foods_macros[food_name]
                    food_group_data = food_macros.get('food_group_full', [])
                    if isinstance(food_group_data, list):
                        food_groups = [fg.strip() for fg in food_group_data if fg and fg.strip()]
                    elif isinstance(food_group_data, str):
                        food_groups = [fg.strip() for fg in food_group_data.split('|') if fg.strip()]
                    else:
                        food_groups = []
                    
                    critical_groups_in_food = [fg for fg in food_groups if fg in CRITICAL_GROUPS]
                    has_conflict = any(fg in meal_used_food_groups for fg in critical_groups_in_food)
                    
                    # 🔒 STARCH MUTUAL EXCLUSION: grain_base, starch_base, light_grain are mutually exclusive
                    # If meal already has ANY starch/grain slot filled, block foods with OTHER starch/grain slots
                    if not has_conflict:
                        STARCH_GROUPS = {'grain_base', 'starch_base', 'light_grain'}
                        food_starch_groups = [fg for fg in critical_groups_in_food if fg in STARCH_GROUPS]
                        used_starch_groups = STARCH_GROUPS & meal_used_food_groups
                        if food_starch_groups and used_starch_groups:
                            has_conflict = True
                            logger.debug(f"        STARCH EXCLUSION: '{food_name}' has {food_starch_groups} but meal already uses {used_starch_groups}")
                    
                    # 🔒 SOFT CATEGORY PENALTY: Category conflicts handled by scoring (-50 penalty),
                    # not boolean blocking. Only food_group (slot) conflicts remain as hard blocks.
                    
                    if not has_conflict:
                        group_unique_filtered.append(food_name)
                        if critical_groups_in_food:
                            logger.debug(f"        ACCEPTED '{food_name}' -> Critical groups: {critical_groups_in_food} (all groups: {food_groups})")
                    else:
                        conflicting_groups = [fg for fg in critical_groups_in_food if fg in meal_used_food_groups]
                        logger.debug(f"        REJECTED '{food_name}': critical groups {critical_groups_in_food} conflict with used {conflicting_groups}")
                        logger.debug(f"          Food has groups: {food_groups}")
                        logger.debug(f"          Meal already used: {sorted(list(meal_used_food_groups))}")
                
                if group_unique_filtered:
                    final_filtered = group_unique_filtered
                    logger.info(f"        CRITICAL GROUP DIVERSITY: {len(group_unique_filtered)} foods remain (blocking duplicate protein/grain groups only)")
                    group_count = len(meal_used_food_groups)
                    logger.debug(f"         → Critical group filter: {len(group_unique_filtered)} foods remain (-{before_group_filter_count - len(group_unique_filtered)}) | Meal has {group_count} critical groups blocked: {sorted(list(meal_used_food_groups)) if meal_used_food_groups else 'none yet'}")
                    if meal_used_food_groups:
                        logger.info(f"           Meal has critical groups: {sorted(list(meal_used_food_groups))} (protein_main, protein_source, lean_protein, grain_base, starch_base)")
                    else:
                        logger.info(f"           First component - no critical groups yet (will register after selection)")
                else:
                    logger.warning(f"        CRITICAL GROUP CONFLICT: All {len(final_filtered)} foods in slot '{slot_name}' conflict with used critical groups {meal_used_food_groups}")
                    logger.debug(f"         → Critical group filter: 0 foods remain (-{before_group_filter_count})  ALL BLOCKED BY GROUPS: {meal_used_food_groups} - BOTTLENECK!")
                    logger.warning(f"          STRICT ENFORCEMENT: Trying next slot option from: {' OR '.join(component_options)}")
                    logger.warning(f"          Only protein/grain groups are blocked; non-critical groups (fruit, fat, condiment) can repeat")
                    continue  
                
                ingredient_unique_filtered = []
                PRIMARY_INGREDIENT_PATTERNS = [
                    'black eyed peas', 'black-eyed peas', 'chickpea', 'chickpeas', 'garbanzo',
                    'lentil', 'lentils', 'masoor', 'moong', 'mung', 'toor', 'urad', 'dal', 'daal',
                    'kidney bean', 'black bean', 'pinto bean', 'navy bean', 'lima bean', 'fava bean',
                    'rajma', 'chana', 'chole', 
                    'tempeh', 'tofu', 'paneer', 'soy chunk', 'soy chunks', 'soy', 'soya',
                    'quinoa', 'rice', 'barley', 'millet', 'oats', 'oat', 'pasta', 'noodles',
                    'spinach', 'kale', 'cabbage', 'cauliflower', 'broccoli', 'eggplant', 'zucchini',
                    'tomato', 'potato', 'sweet potato', 'yam', 'cassava',
                    'chicken', 'beef', 'pork', 'lamb', 'fish', 'salmon', 'tuna', 'shrimp', 'prawn'
                ]
                
                for food_name in final_filtered:
                    food_name_lower = food_name.lower()
                    
                    food_name_before_prep = food_name_lower.split(' with ')[0].split(' and ')[0].split(' in ')[0].split(' topped')[0]
                    
                    detected_primary = None
                    for ingredient_pattern in PRIMARY_INGREDIENT_PATTERNS:
                        if ingredient_pattern in food_name_before_prep:
                            detected_primary = ingredient_pattern
                            break
                    
                    food_ingredients = set()
                    for keyword in INGREDIENT_KEYWORDS:
                        if keyword in food_name_lower:
                            food_ingredients.add(keyword)
                    
                    has_primary_conflict = detected_primary and detected_primary in meal_used_ingredients
                    has_generic_conflict = any(ing in meal_used_ingredients for ing in food_ingredients)
                    
                    if not has_primary_conflict and not has_generic_conflict:
                        ingredient_unique_filtered.append(food_name)
                    else:
                        if has_primary_conflict:
                            logger.debug(f"         PRIMARY INGREDIENT BLOCK: '{food_name}' shares base ingredient '{detected_primary}' with existing meal item")
                
                if ingredient_unique_filtered:
                    final_filtered = ingredient_unique_filtered
                    logger.debug(f"      INGREDIENT UNIQUENESS: {len(ingredient_unique_filtered)} foods remain after filtering used ingredients")
                else:
                    logger.debug(f"      INGREDIENT UNIQUENESS: All foods conflict with used ingredients ({meal_used_ingredients}) - trying next slot option")
                    continue  
                
                is_snack = 'snack' in meal_name.lower()
                
                def cuisine_matches(tier_cuisine_str: str, food_cuisine_str: str) -> bool:
                    """Check if two cuisine strings match, handling common variations"""
                    tier_lower = tier_cuisine_str.lower().strip()
                    food_lower = food_cuisine_str.lower().strip()
                    
                    if tier_lower == food_lower:
                        return True

                    tier_words = set(tier_lower.split())
                    food_words = set(food_lower.split())
                    
                    if tier_words == food_words and len(tier_words) > 1:
                        return True
                    
                    synonyms = {
                        'global': {'universal', 'world'},
                        'southeast asian': {'south east asian', 'sea'},
                        'east asian': {'eastern asian'},
                        'middle eastern': {'middle east', 'mideast'},
                    }
                    
                    if tier_lower in synonyms:
                        if food_lower in synonyms[tier_lower]:
                            return True
                    
                    if food_lower in synonyms:
                        if tier_lower in synonyms[food_lower]:
                            return True
                    
                    return False
                
                if meal_primary_cuisine and not is_snack and component_idx <= 2:
                    # 🔒 SCOPED CUISINE: Only enforce strict cuisine for Comp 1 (Protein) & Comp 2 (Grain)
                    # Components 3-4 (Vegetable/Soup/Side) get cuisine as a scoring bonus instead
                    cascade_cuisines = CUISINE_CASCADE.get(meal_primary_cuisine, [meal_primary_cuisine])
                    if not cascade_cuisines:
                        cascade_cuisines = [meal_primary_cuisine]
                    
                    cuisine_consistent_filtered = []
                    tier_found = None
                    
                    for tier_index, tier_cuisine in enumerate(cascade_cuisines, 1):
                        tier_foods = []
                        
                        for food_name in final_filtered:
                            if food_name not in self.all_foods_macros:
                                continue
                            
                            food_macros = self.all_foods_macros[food_name]
                            food_cuisines = food_macros.get('cuisine', [])
                            if not isinstance(food_cuisines, list):
                                food_cuisines = [food_cuisines] if food_cuisines else []
                            
                            food_matches_tier = False
                            for food_cuisine in food_cuisines:
                                if cuisine_matches(tier_cuisine, food_cuisine):
                                    food_matches_tier = True
                                    break
                            
                            if food_matches_tier:
                                tier_foods.append(food_name)
                            else:
                                food_cuisines_lower = [c.lower().strip() for c in food_cuisines if c]
                                if tier_cuisine.lower() == 'global':
                                    if 'global' in food_cuisines_lower:
                                        tier_foods.append(food_name)
                        
                        if tier_foods:
                            cuisine_consistent_filtered = tier_foods
                            tier_found = tier_index
                            tier_name = tier_cuisine
                            logger.info(f"        CUISINE TIER {tier_index}: Found {len(tier_foods)} foods matching '{tier_cuisine}' (stopped cascade)")
                            break
                        else:
                            logger.debug(f"          Tier {tier_index} ('{tier_cuisine}'): 0 foods found, trying next tier...")
                    
                    if cuisine_consistent_filtered:
                        final_filtered = cuisine_consistent_filtered
                        if tier_found == 1:
                            logger.info(f"        PRIMARY CUISINE: Using {len(cuisine_consistent_filtered)} '{tier_name}' foods (Tier {tier_found})")
                        else:
                            logger.warning(f"        CASCADE FALLBACK: Using {len(cuisine_consistent_filtered)} '{tier_name}' foods (Tier {tier_found}/{len(cascade_cuisines)})")
                    else:
                        logger.warning(f"        ALL TIERS EXHAUSTED: No foods in any of {len(cascade_cuisines)} tiers {cascade_cuisines}")
                        logger.warning(f"          Using ALL {len(final_filtered)} foods as global fallback (structure > cuisine)")
                
                medical_conditions = user_profile.get('medical_conditions', []) if user_profile else []
                has_type2_diabetes = any(
                    'type 2 diabetes' in str(cond).lower() or
                    'diabetes type 2' in str(cond).lower() or
                    't2dm' in str(cond).lower()
                    for cond in medical_conditions
                )


                
                if has_type2_diabetes or 'fiber' in str(user_profile.get('goals', [])).lower():
                    MAX_FIBER_PER_SERVING = 8.0
                    moderate_fiber_foods = []
                    for food_name in final_filtered:
                        food_macros = self.all_foods_macros.get(food_name, {})
                        fiber_per_serving = food_macros.get('fiber', 0)
                        estimated_serving_fiber = fiber_per_serving * 1.5
                        
                        if estimated_serving_fiber <= MAX_FIBER_PER_SERVING:
                            moderate_fiber_foods.append(food_name)
                        else:
                            logger.debug(f"       FIBER CAP: '{food_name}' rejected (estimated {estimated_serving_fiber:.1f}g fiber per serving > {MAX_FIBER_PER_SERVING}g)")
                    
                    if moderate_fiber_foods:
                        final_filtered = moderate_fiber_foods
                        logger.info(f"       FIBER FILTER: Kept {len(moderate_fiber_foods)} moderate-fiber foods (max {MAX_FIBER_PER_SERVING}g per serving)")
                
                if slot_name in ['hydration', 'warm_beverage', 'veg_beverage']:
                    if meal_name_normalized.lower() in ['breakfast', 'morning_snack', 'evening_snack']:
                        fruit_juice_keywords = [
                            'juice', 'orange juice', 'apple juice', 'grape juice', 'pineapple juice',
                            'mango juice', 'cranberry juice', 'grapefruit juice', 'pomegranate juice',
                            'fruit drink', 'fruit punch', 'smoothie with fruit juice', 'nectar'
                        ]
                        
                        non_fruit_juice_foods = []
                        for food_name in final_filtered:
                            food_name_lower = food_name.lower()
                            is_fruit_juice = any(kw in food_name_lower for kw in fruit_juice_keywords)
                            is_veg_juice = any(veg in food_name_lower for veg in ['carrot', 'cucumber', 'beet', 'celery', 'tomato', 'vegetable'])
                            
                            if not (is_fruit_juice and not is_veg_juice):
                                non_fruit_juice_foods.append(food_name)
                        
                        if non_fruit_juice_foods:
                            final_filtered = non_fruit_juice_foods
                            logger.debug(f"      FRUIT JUICE FILTER: Removed {len(diversity_filtered) - len(final_filtered)} fruit juice items from {slot_name}")
                    
                    if meal_name_normalized.lower() == 'morning_snack':
                        non_green_tea_foods = []
                        for food_name in final_filtered:
                            food_name_lower = food_name.lower()
                            is_green_tea = 'green tea' in food_name_lower
                            if not is_green_tea:
                                non_green_tea_foods.append(food_name)
                        
                        if non_green_tea_foods:
                            final_filtered = non_green_tea_foods
                            logger.debug(f"      GREEN TEA FILTER: Removed green tea items from {slot_name}")
                if not final_filtered:
                    logger.debug(f"      Slot '{slot_name}': No valid foods after filtering, trying next option...")
                    logger.error(f"       FILTER CASCADE RESULT: 0 foods survived - slot '{slot_name}' exhausted, trying next option")
                    continue
                
                if user_profile and final_filtered:
                    _normalized_conds = self._normalize_user_conditions(user_profile)
                    _normalized_conds = [c for c in _normalized_conds if c in self.DIETARY_CONDITIONS_ONLY]
                    if _normalized_conds:
                        HARD_BLOCK_CONDITIONS = {
                            'gerd / acid reflux', 'ibs / irritable bowel syndrome', "crohn's disease",
                            'celiac disease', 'kidney disease (ckd)', 'liver disease (nafld/cirrhosis)',
                            'diabetes type 1', 'diabetes type 2', 'prediabetes',
                        }
                        _medically_safe = []
                        for _food_name in final_filtered:
                            _fmacros = self.all_foods_macros.get(_food_name, {})
                            _food_avoid = _fmacros.get('medical_conditions_avoid', [])
                            
                            _is_avoided = False
                            if _food_avoid:
                                _avoid_lower = [m.lower().strip().replace('_', ' ').replace('/', ' / ') for m in _food_avoid if m]
                                for _uc in _normalized_conds:
                                    for _ac in _avoid_lower:
                                        if (_uc == _ac or (len(_uc) > 4 and _uc in _ac) or (len(_ac) > 4 and _ac in _uc)):
                                            if _uc in HARD_BLOCK_CONDITIONS:
                                                _is_avoided = True
                                            break
                                    if _is_avoided:
                                        break
                            
                            if _is_avoided:
                                logger.debug(f"       ASSEMBLY MEDICAL AVOID: '{_food_name}' removed (critical condition)")
                                continue
                            
                            _medically_safe.append(_food_name)
                        
                        if _medically_safe:
                            _removed = len(final_filtered) - len(_medically_safe)
                            if _removed > 0:
                                logger.info(f"       ASSEMBLY MEDICAL FILTER: {_removed}/{len(final_filtered)} foods removed for '{slot_name}' ({len(_medically_safe)} remaining)")
                            final_filtered = _medically_safe
                        else:
                            logger.warning(f"       ASSEMBLY MEDICAL FILTER: ALL foods removed for '{slot_name}'! Keeping pool.")
                
                if not final_filtered:
                    logger.debug(f"      Slot '{slot_name}': No valid foods after medical filtering, trying next option...")
                    continue

                is_mandatory_grain_slot = (
                    component_idx == 2 and 
                    meal_key in ['lunch', 'dinner'] and 
                    slot_name in ['grain_base', 'starch_base', 'light_grain']
                )
                
                if component_idx > 1 and current_meal_animal_protein_count > 0 and not is_mandatory_grain_slot:
                    ANIMAL_PROTEIN_KEYWORDS = [
                        'chicken', 'beef', 'pork', 'lamb', 'veal', 'steak', 'meatball', 'mince',
                        'salmon', 'cod', 'shrimp', 'fish', 'crab', 'trout', 'mackerel', 'whiting',
                        'flounder', 'seafood', 'tuna', 'lobster', 'clam', 'conch', 'oyster', 'tilapia',
                        'basa', 'haddock', 'sole', 'prawn', 'scallop', 'hen', 'drumstick', 'turkey',
                        'grouper', 'herring', 'swordfish', 'albacore', 'perch', 'pompano',
                        'halibut', 'catfish', 'snapper', 'mahi', 'sardine', 'anchovy',
                        'barramundi', 'seabass', 'bass', 'egg', 'omelet', 'omelette',
                        'brisket', 'pike', 'flank', 'roast', 'ribs', 'chuck', 'sirloin',
                        'tenderloin', 'cutlet', 'chop', 'fillet', 'wings', 'breast', 'thigh', 'leg'
                    ]
                    
                    non_protein_foods = []
                    blocked_protein_count = 0
                    allowed_combo_count = 0
                    
                    for food_name in final_filtered:
                        food_name_lower = food_name.lower()
                        has_protein_keyword = any(kw in food_name_lower for kw in ANIMAL_PROTEIN_KEYWORDS)
                        
                        if has_protein_keyword:
                            food_macros = self.all_foods_macros.get(food_name, {})
                            food_groups_data = food_macros.get('food_group_full', [])
                            if isinstance(food_groups_data, str):
                                food_groups = [fg.strip().lower() for fg in food_groups_data.split('|') if fg.strip()]
                            elif isinstance(food_groups_data, list):
                                food_groups = [fg.strip().lower() for fg in food_groups_data if fg and fg.strip()]
                            else:
                                food_groups = []
                            
                            is_grain_combo = any(tag in food_groups for tag in ['grain_base', 'starch_base', 'light_grain', 'complex_carbs'])
                            is_vegetable_combo = any(tag in food_groups for tag in ['primary_vegetable', 'cooked_vegetable', 'fibrous_veggies'])
                            
                            if is_grain_combo or is_vegetable_combo:
                                non_protein_foods.append(food_name)
                                allowed_combo_count += 1
                                logger.debug(f"          COMBO ALLOWED: '{food_name}' is grain/veg combo - not counted as pure protein")
                            else:
                                blocked_protein_count += 1
                                logger.debug(f"         PROTEIN BLOCKING: '{food_name}' is PURE protein - blocked from Component {component_idx}")
                        else:
                            non_protein_foods.append(food_name)
                    
                    if blocked_protein_count > 0:
                        logger.warning(f"        PROTEIN STACKING PREVENTION: Blocked {blocked_protein_count} PURE protein items from '{slot_name}' slot (Component {component_idx})")
                        logger.warning(f"          Reason: Meal already has {current_meal_animal_protein_count} protein item - MAX 1 ALLOWED")
                        if allowed_combo_count > 0:
                            logger.info(f"           Allowed {allowed_combo_count} grain/vegetable combo foods (not pure proteins)")
                    
                    if non_protein_foods:
                        final_filtered = non_protein_foods
                        logger.info(f"           VALIDATION PASSED: {len(non_protein_foods)} non-protein foods remain for selection")
                    else:
                        logger.error(f"           SLOT EXHAUSTED: All {len(final_filtered)} foods in '{slot_name}' were protein items - trying next slot option")
                        continue
                elif is_mandatory_grain_slot:
                    logger.info(f"         MANDATORY GRAIN SLOT: Allowing all {len(final_filtered)} grains (protein stacking prevention BYPASSED)")
                    logger.info(f"           Grains naturally contain protein - portion control will manage total protein")
  
                
                logger.debug(f"       FILTER CASCADE COMPLETE: {len(final_filtered)} foods survived all filters and ready for selection")
                
                if self.used_failsafes_previous_day and final_filtered:
                    prev_day_normalized = {f.lower().strip() for f in self.used_failsafes_previous_day}
                    # 🔍 DEBUG: Log matching details
                    sample_prev = list(prev_day_normalized)[:3]
                    sample_pool = [f.lower().strip() for f in final_filtered[:3]]
                    overlap = [f for f in final_filtered if f.lower().strip() in prev_day_normalized]
                    logger.info(f"       🔍 CROSS-DAY DEBUG: prev_day has {len(prev_day_normalized)} entries, pool has {len(final_filtered)} foods")
                    if sample_prev:
                        logger.info(f"       🔍 PREV SAMPLE: {sample_prev}")
                    if overlap:
                        logger.info(f"       🔍 OVERLAP FOUND: {overlap[:5]}")
                    cross_day_fresh = [f for f in final_filtered if f.lower().strip() not in prev_day_normalized]
                    
                    # 🔒 HARD BLOCK: Always prefer fresh foods, no threshold bypass
                    if cross_day_fresh:
                        logger.info(f"       CROSS-DAY PRE-FILTER: {len(final_filtered)} → {len(cross_day_fresh)} foods (removed {len(final_filtered) - len(cross_day_fresh)} from previous day)")
                        final_filtered = cross_day_fresh
                    else:
                        logger.warning(f"       CROSS-DAY PRE-FILTER: ALL {len(final_filtered)} foods from previous day - keeping for fallback but will try to skip")
                
                # 🔒 NON-CONSECUTIVE DAY FILTER: Also remove foods from days -2+
                non_consecutive_pool = getattr(self, 'non_consecutive_foods_pool', set())
                if non_consecutive_pool and final_filtered:
                    non_consec_normalized = {f.lower().strip() for f in non_consecutive_pool}
                    non_consec_fresh = [f for f in final_filtered if f.lower().strip() not in non_consec_normalized]
                    if non_consec_fresh:
                        logger.info(f"       NON-CONSECUTIVE FILTER: {len(final_filtered)} → {len(non_consec_fresh)} foods (removed {len(final_filtered) - len(non_consec_fresh)} from earlier days)")
                        final_filtered = non_consec_fresh
                    else:
                        logger.debug(f"       NON-CONSECUTIVE FILTER: All foods from earlier days - will enforce max 2 reuse at selection")

                if meal_key.lower() in ['breakfast', 'lunch', 'dinner'] and user_profile:
                    user_cuisine = user_profile.get('cuisine', 'global')
                    
                    # 🚀 MULTI-CUISINE FIX (April 30, 2026): Respect ALL requested cuisines, not just first
                    # Handle comma-separated string from database
                    if isinstance(user_cuisine, str) and ',' in user_cuisine:
                        user_cuisine = [c.strip() for c in user_cuisine.split(',') if c.strip()]
                    
                    if isinstance(user_cuisine, list):
                        user_cuisines_list = [normalize_cuisine(c) for c in user_cuisine if c] if user_cuisine else ['global']
                    else:
                        user_cuisines_list = [normalize_cuisine(user_cuisine)] if user_cuisine else ['global']
                    
                    # Build combined cascade for ALL requested cuisines
                    all_cuisine_cascades = []
                    for cuisine in user_cuisines_list:
                        cuisine_lower = str(cuisine).lower().strip()
                        cuisine_cascade = CUISINE_CASCADE.get(cuisine_lower, [cuisine_lower])
                        all_cuisine_cascades.extend(cuisine_cascade)
                    
                    # 🚀 PRIORITIZATION FIX: Exclude 'global' from cascade when specific cuisines requested
                    # This prevents generic 'global' foods from dominating the selection
                    has_specific_cuisine = any(c.lower() != 'global' for c in user_cuisines_list)
                    if has_specific_cuisine:
                        # Remove 'global' and generic tags to prioritize regional foods
                        all_cuisine_cascades = [c for c in all_cuisine_cascades if str(c).lower().strip() not in ['global', 'international', 'none']]
                    
                    # Deduplicate and normalize
                    cuisine_cascade_lower = list(set(str(c).lower().strip() for c in all_cuisine_cascades))
                    
                    logger.info(f"       MULTI-CUISINE FILTER: Checking foods against {len(user_cuisines_list)} cuisines: {user_cuisines_list}")
                    logger.info(f"       COMBINED CASCADE: {len(cuisine_cascade_lower)} allowed cuisines: {cuisine_cascade_lower[:10]}...")
                    logger.info(f"       GLOBAL EXCLUDED: {has_specific_cuisine} (prioritizing regional foods)")
                    
                    # 🚀 PRIORITIZATION: Score foods by how closely they match requested cuisines
                    regional_foods_with_score = []
                    global_foods_backup = []
                    
                    # Build list of ALL cuisines in user's cascades ONCE (for Tier 1 matching)
                    user_full_cascades = []
                    for uc in user_cuisines_list:
                        uc_cascade = CUISINE_CASCADE.get(uc, [uc])
                        user_full_cascades.extend(uc_cascade)
                    user_full_cascades_lower = list(set(str(c).lower().strip() for c in user_full_cascades))
                    
                    logger.info(f"       USER REQUESTED: {user_cuisines_list}")
                    logger.info(f"       FULL CASCADES (Tier 1): {user_full_cascades_lower[:15]}...")
                    
                    for food_name in final_filtered:
                        food_cuisines = self.all_foods_macros.get(food_name, {}).get('cuisine', [])
                        if isinstance(food_cuisines, str):
                            food_cuisines = [food_cuisines]
                        food_cuisines_lower = [str(c).lower().strip() for c in food_cuisines if c]
                        
                        if not food_cuisines_lower:
                            continue
                        
                        # Calculate specificity score
                        # Tier 1 (100 points): Direct match to user's requested cuisines or their cascades
                        # Tier 2 (50 points): Match to broader cascade cuisines
                        # Tier 3 (BACKUP): Global foods only when regional exhausted
                        score = 0
                        matched_regional = False
                        has_global_tag = False
                        
                        for fc in food_cuisines_lower:
                            # Tier 1: Match to user's requested cuisines OR their direct cascades (highest priority)
                            if fc in user_full_cascades_lower:
                                score = max(score, 100)
                                matched_regional = True
                            # Tier 2: Match to broader cascade cuisines (medium priority)
                            elif fc in cuisine_cascade_lower and fc not in ['global', 'international']:
                                score = max(score, 50)
                                matched_regional = True
                            # Track if has 'global' tag (for fallback pool)
                            if fc in ['global', 'international']:
                                has_global_tag = True
                        
                        # TIER 1-2: Add regional matches (user's preferred cuisines)
                        if matched_regional:
                            regional_foods_with_score.append((food_name, score))
                            # Set cuisine priority for emergency failsafe
                            if score == 100:
                                self.all_foods_macros[food_name]['_cuisine_priority'] = 1  # Tier 1: Direct match
                            elif score == 50:
                                self.all_foods_macros[food_name]['_cuisine_priority'] = 2  # Tier 2: Cascade match
                        # TIER 3: Keep global foods as BACKUP ONLY (use when regional pool exhausted)
                        elif has_global_tag and has_specific_cuisine:
                            global_foods_backup.append(food_name)
                            self.all_foods_macros[food_name]['_cuisine_priority'] = 3  # Tier 3: Global fallback
                        # Foods that don't match regional OR global - mark as lowest priority
                        else:
                            if food_name in self.all_foods_macros:
                                self.all_foods_macros[food_name]['_cuisine_priority'] = 999  # Unmatched foods
                    
                    # Sort regional foods by score (highest first)
                    regional_foods_with_score.sort(key=lambda x: x[1], reverse=True)
                    cuisine_filtered = [food for food, score in regional_foods_with_score]
                    
                    # Log distribution
                    if regional_foods_with_score:
                        tier1_count = sum(1 for _, s in regional_foods_with_score if s == 100)
                        tier2_count = sum(1 for _, s in regional_foods_with_score if s == 50)
                        logger.info(f"       ✅ REGIONAL FOODS: Tier1(exact)={tier1_count}, Tier2(cascade)={tier2_count}, Total={len(cuisine_filtered)}")
                        logger.info(f"       🔄 GLOBAL BACKUP: {len(global_foods_backup)} foods reserved (use only when regional exhausted)")
                    
                    # 🚨 FALLBACK: Only use global foods if regional pool is insufficient
                    min_regional_threshold = 3  # Minimum foods needed (lowered to prevent over-dilution with global foods)
                    if len(cuisine_filtered) < min_regional_threshold and global_foods_backup:
                        shortage = min_regional_threshold - len(cuisine_filtered)
                        logger.warning(f"       ⚠️ REGIONAL POOL LOW: Only {len(cuisine_filtered)} foods (need ≥{min_regional_threshold})")
                        logger.warning(f"       🔄 ADDING UP TO {shortage} GLOBAL FOODS as emergency fallback (minimizing to preserve cuisine preference)")
                        # Add minimal global foods, prioritizing user's cuisine preference
                        cuisine_filtered.extend(global_foods_backup[:shortage])
                        logger.info(f"       FINAL POOL: {len(cuisine_filtered)} foods ({len(regional_foods_with_score)} regional + {min(shortage, len(global_foods_backup))} global)")
                    
                    if len(cuisine_filtered) == 0:
                        logger.warning(f"        TIER 1 REGIONAL CASCADE EMPTY: No foods match {cuisine_cascade}")
                        logger.warning(f"        TIER 2 GLOBAL FALLBACK: Adding PURE global foods only (April 8, 2026 fix)")
                        
                        global_equivalent_tags = {'global', 'none', 'international', 'western'}
                        
                        debug_count_empty = 0
                        debug_count_global = 0
                        debug_count_rejected = 0
                        debug_samples = []
                        
                        for food_name in final_filtered:
                            food_cuisines = self.all_foods_macros.get(food_name, {}).get('cuisine', [])
                            if isinstance(food_cuisines, str):
                                food_cuisines = [food_cuisines]
                            food_cuisines_lower = [str(c).lower().strip() for c in food_cuisines if c]

                            is_universal = (
                                not food_cuisines_lower or  
                                any(tag in global_equivalent_tags for tag in food_cuisines_lower) 
                            )
                            
                            if not food_cuisines_lower:
                                debug_count_empty += 1
                            elif any(tag in global_equivalent_tags for tag in food_cuisines_lower):
                                debug_count_global += 1
                            else:
                                debug_count_rejected += 1
                                if len(debug_samples) < 5:
                                    debug_samples.append(f"{food_name}={food_cuisines_lower}")
                            
                            if is_universal:
                                cuisine_filtered.append(food_name)
                        
                        logger.warning(f"        TIER 2 DEBUG: empty={debug_count_empty}, global={debug_count_global}, rejected={debug_count_rejected}, total_pool={len(final_filtered)}")
                        if debug_samples:
                            logger.error(f"        REJECTED SAMPLES: {', '.join(debug_samples)}")

                    if len(cuisine_filtered) > 0:
                        global_equivalent_tags = {'global', 'none', 'international', 'western'}
                        tier1_violations = []
                        
                        for food_name in cuisine_filtered:
                            food_cuisines = self.all_foods_macros.get(food_name, {}).get('cuisine', [])
                            if isinstance(food_cuisines, str):
                                food_cuisines = [food_cuisines]
                            food_cuisines_lower = [str(c).lower().strip() for c in food_cuisines if c]
                            
                            is_pure_global = (
                                food_cuisines_lower and 
                                all(tag in global_equivalent_tags for tag in food_cuisines_lower)
                            )
                            
                            if is_pure_global:
                                tier1_violations.append(food_name)
                        
                        if tier1_violations:
                            if not self._silent_mode:  # 🚀 Only log violations if NOT in silent mode
                                logger.error(f"         CUISINE VIOLATION DETECTED IN TIER 1: {len(tier1_violations)} pure global foods leaked!")
                                logger.error(f"        Violating foods: {tier1_violations[:5]}")
                            cuisine_filtered = [f for f in cuisine_filtered if f not in tier1_violations]
                            if not self._silent_mode:
                                logger.info(f"        ✓ Removed {len(tier1_violations)} pure global foods from TIER 1")
                    
                    if len(cuisine_filtered) < len(final_filtered):
                        tier_used = "TIER 1 (Regional)" if len(cuisine_filtered) > 0 else "TIER 2 (Global Fallback)"
                        logger.info(f"        CUISINE FILTER ({tier_used}): '{user_cuisine}' cascade {cuisine_cascade} kept {len(cuisine_filtered)}/{len(final_filtered)} foods")
                        
                        if tier_used == "TIER 1 (Regional)":
                            logger.info(f"        ✓ 0% CUISINE VIOLATION: All {len(cuisine_filtered)} foods match '{user_cuisine}' cascade")
                        else:
                            logger.info(f"        ⚠ TIER 2 ACTIVATED: Using {len(cuisine_filtered)} universal foods as fallback")
                        
                        final_filtered = cuisine_filtered
                    
                    # Check cuisine coverage with multi-cuisine support
                    if len(final_filtered) > 0:
                        exact_matches = 0
                        for f in final_filtered:
                            food_cuisines = str(self.all_foods_macros.get(f, {}).get('cuisine', '')).lower()
                            # Check if food matches ANY of the requested cuisines
                            if any(uc in food_cuisines for uc in [str(c).lower() for c in user_cuisines_list]):
                                exact_matches += 1
                        
                        exact_pct = (exact_matches / len(final_filtered)) * 100
                        if exact_pct < 30: 
                            logger.info(f"        CUISINE COVERAGE: '{user_cuisines_list}' exact matches {exact_matches}/{len(final_filtered)} ({exact_pct:.1f}%), using cascade fallback")
                
                if 'protein' in slot_name.lower() and len(final_filtered) > 3:
                    protein_sorted = sorted(
                        final_filtered,
                        key=lambda f: self.all_foods_macros.get(f, {}).get('protein', 0),
                        reverse=True
                    )
                    
                    is_main_meal = meal_key.lower() in ['breakfast', 'lunch', 'dinner']
                    is_lunch_or_dinner = meal_key.lower() in ['lunch', 'dinner']
                    
                    if is_lunch_or_dinner:
                        used_protein_families = set()
                        for other_meal_key, other_family in self.daily_meal_protein_families.items():
                            if other_meal_key.lower() != meal_key.lower() and other_meal_key.lower() in ['lunch', 'dinner']:
                                if other_family in {'seafood', 'poultry', 'red_meat'}:
                                    used_protein_families.add(other_family)
                                    logger.info(f"        PROTEIN DIVERSITY: {other_meal_key} already using {other_family} family")
                        
                        if used_protein_families:
                            protein_sorted_before = len(protein_sorted)
                            protein_sorted = [
                                f for f in protein_sorted 
                                if self._detect_protein_family(f) not in used_protein_families
                            ]
                            filtered_count = protein_sorted_before - len(protein_sorted)
                            if filtered_count > 0:
                                logger.info(f"        PROTEIN FAMILY FILTER: Removed {filtered_count} {used_protein_families} proteins from pool")
                                logger.info(f"        Remaining pool: {len(protein_sorted)} proteins from other families")
                            
                            if len(protein_sorted) == 0:
                                logger.error(f"        CRITICAL: All proteins filtered by family diversity rule!")
                                logger.error(f"        Restoring original pool to prevent empty meal")
                                protein_sorted = sorted(
                                    final_filtered,
                                    key=lambda f: self.all_foods_macros.get(f, {}).get('protein', 0),
                                    reverse=True
                                )
                    
                    if is_main_meal:
                        top_count = max(1, len(protein_sorted) * 30 // 100)
                        top_proteins = protein_sorted[:top_count]
                        
                        dietary_preference = user_profile.get('dietary_preference', ['Non-Vegetarian']) if user_profile else ['Non-Vegetarian']
                        if isinstance(dietary_preference, str):
                            dietary_preference = [dietary_preference]
                        diet_pref_lower = [str(d).lower() for d in dietary_preference]
                        is_non_veg = any('non-vegetarian' in d or 'non vegetarian' in d or 'nonvegetarian' in d for d in diet_pref_lower)
                        if not is_non_veg:
                            is_non_veg = not any(
                                ('vegetarian' in d and 'non' not in d) or 'vegan' in d 
                                for d in diet_pref_lower
                            )
                        
                        if is_lunch_or_dinner and is_non_veg:
                            ANIMAL_KW = [
                                'chicken', 'beef', 'pork', 'lamb', 'veal', 'steak', 'meatball', 'mince',
                                'salmon', 'cod', 'shrimp', 'fish', 'crab', 'trout', 'mackerel', 'whiting',
                                'flounder', 'seafood', 'tuna', 'lobster', 'clam', 'conch', 'oyster', 'tilapia',
                                'basa', 'haddock', 'sole', 'prawn', 'scallop', 'hen', 'drumstick', 'turkey',
                                'grouper', 'herring', 'swordfish', 'albacore', 'perch', 'pompano',
                                'halibut', 'catfish', 'snapper', 'mahi', 'sardine', 'anchovy',
                                'barramundi', 'seabass', 'bass', 'egg', 'omelet', 'omelette',
                                'brisket', 'pike', 'flank', 'roast', 'ribs', 'chuck', 'sirloin',
                                'tenderloin', 'cutlet', 'chop', 'fillet', 'wings', 'breast', 'thigh', 'leg'
                            ]
                            animal_top = [f for f in top_proteins if any(kw in f.lower() for kw in ANIMAL_KW)]
                            if animal_top:
                                logger.info(f"        NON-VEG PREFERENCE: {len(animal_top)} animal proteins found in top {top_count} (discarding {len(top_proteins) - len(animal_top)} plant proteins for {meal_key})")
                                top_proteins = animal_top
                            else:
                                animal_all = [f for f in protein_sorted if any(kw in f.lower() for kw in ANIMAL_KW)]
                                if animal_all:
                                    logger.warning(f"        NON-VEG FALLBACK: No animal proteins in top {top_count}, using {len(animal_all)} animal proteins from full pool for {meal_key}")
                                    top_proteins = animal_all[:max(1, len(animal_all) * 30 // 100)]
                                else:
                                    logger.warning(f"        NON-VEG NO ANIMAL: No animal proteins available in '{slot_name}' pool for {meal_key} - using plant proteins as fallback")
                        
                        selected_food = self._prioritize_common_foods(top_proteins, self.all_foods_macros)
                        
                        if selected_food:
                            protein_g = self.all_foods_macros.get(selected_food, {}).get('protein', 0)
                            logger.info(f"        HEAVY PROTEIN SELECTED: '{selected_food}' ({protein_g:.1f}g/100g protein) from top {top_count}/{len(protein_sorted)} heaviest sources for {meal_key}")
                    else:
                        top_half = protein_sorted[:max(1, len(protein_sorted) // 2)]
                        selected_food = self._prioritize_common_foods(top_half, self.all_foods_macros)
                        
                        if selected_food:
                            protein_g = self.all_foods_macros.get(selected_food, {}).get('protein', 0)
                            logger.info(f"        SNACK PROTEIN SELECTED: '{selected_food}' ({protein_g:.1f}g/100g protein) from top {len(top_half)}/{len(protein_sorted)} protein sources for {meal_key}")
                
                elif 'fruit' in slot_name.lower() and 'snack' in meal_name.lower() and len(final_filtered) > 1:
                    used_fruit_families = set()
                    if hasattr(self, 'daily_snack_fruit_families') and self.daily_snack_fruit_families:
                        for other_snack_name, other_family in self.daily_snack_fruit_families.items():
                            if other_snack_name.lower() != meal_name.lower():
                                used_fruit_families.add(other_family)
                                logger.info(f"        FRUIT DIVERSITY: {other_snack_name} already using {other_family} family")
                    
                    if used_fruit_families:
                        fruit_filtered_before = len(final_filtered)
                        final_filtered_with_family = [
                            f for f in final_filtered 
                            if self._detect_fruit_family(f) not in used_fruit_families
                        ]
                        filtered_count = fruit_filtered_before - len(final_filtered_with_family)
                        
                        if filtered_count > 0:
                            logger.info(f"        FRUIT FAMILY FILTER: Removed {filtered_count} {used_fruit_families} fruits from pool")
                            logger.info(f"        Remaining pool: {len(final_filtered_with_family)} fruits from other families")
                            final_filtered = final_filtered_with_family
                        
                        if len(final_filtered) == 0:
                            logger.error(f"        CRITICAL: All fruits filtered by family diversity rule!")
                            logger.error(f"        🔒 SAFE RESTORATION: Restoring from FILTERED pool (not raw pool) to preserve Food_category uniqueness")
                            
                            # 🔒 ARCHITECTURAL FIX: Handle empty group_unique_filtered gracefully
                            if group_unique_filtered:
                                # Restore from category-safe pool (best option)
                                final_filtered = group_unique_filtered[:fruit_filtered_before]
                                logger.warning(f"        Restored {len(final_filtered)} foods from group_unique_filtered (Food_category checks preserved)")
                            else:
                                # Emergency: group_unique_filtered is empty, build last-resort pool that still respects categories
                                logger.error(f"        EMERGENCY: group_unique_filtered is empty! Building last-resort pool with category enforcement")
                                emergency_pool = []
                                for food_name in self.slot_pools.get(slot_name, []):
                                    # 🚫 WEEKLY EXCLUSION: Skip overused foods even in emergency
                                    if food_name.lower().strip() in weekly_excluded:
                                        continue
                                    food_macros_emergency = self.all_foods_macros.get(food_name, {})
                                    food_cat_raw = food_macros_emergency.get('food_category', '').strip()
                                    food_cat_norm = food_cat_raw.lower() if food_cat_raw else 'unknown'
                                    
                                    # STRICTLY enforce category uniqueness even in emergency
                                    if food_cat_norm not in meal_used_food_categories:
                                        emergency_pool.append(food_name)
                                
                                if emergency_pool:
                                    final_filtered = emergency_pool
                                    logger.warning(f"        Emergency pool: {len(emergency_pool)} foods (category-safe)")
                                else:
                                    logger.critical(f"        TOTAL FAILURE: No foods available even in emergency pool (all categories exhausted)")
                                    final_filtered = []  # Will trigger 'continue' below
                    
                    # 🔒 DIVERSITY PRE-FILTER: Remove overused foods BEFORE selection so next-best candidate is chosen
                    if final_filtered:
                        _usage_cap = 2  # Uniform cap: max 2 appearances per food per week for ALL components
                        _gw = getattr(self, '_global_weekly_usage', {})
                        _div_pool = [f for f in final_filtered if _gw.get(self._normalize_for_tracking(f), 0) < _usage_cap]
                        if _div_pool:
                            logger.info(f"        DIVERSITY PRE-FILTER (comp {component_idx}): {len(final_filtered)} → {len(_div_pool)} foods (cap={_usage_cap}x)")
                            final_filtered = _div_pool
                        else:
                            # Fallback: ALL candidates overused — pick the LEAST-used subset for maximum diversity
                            _usage_counts = [(f, _gw.get(self._normalize_for_tracking(f), 0)) for f in final_filtered]
                            _min_usage = min(c for _, c in _usage_counts)
                            _least_used = [f for f, c in _usage_counts if c == _min_usage]
                            if len(_least_used) < len(final_filtered):
                                logger.info(f"        DIVERSITY FALLBACK (comp {component_idx}): All ≥{_usage_cap}x, keeping {len(_least_used)} least-used (count={_min_usage})")
                                final_filtered = _least_used
                    
                    selected_food = self._prioritize_common_foods(final_filtered, self.all_foods_macros)
                else:
                    if (component_idx >= 2 or is_snack) and len(final_filtered) < 5:
                        original_count = len(final_filtered)
                        if len(final_filtered) < 5:
                            wider_pool = []
                            used_swaps_normalized = {f.lower().strip() for f in used_swaps}
                            daily_used_normalized = {f.lower().strip() for f in self.daily_used_foods}
                            for f in self.slot_pools.get(slot_name, []):
                                f_norm = f.lower().strip()
                                if f_norm in used_swaps_normalized or f_norm in daily_used_normalized:
                                    continue
                                if f_norm in weekly_excluded:
                                    continue
                                if f_norm in {x.lower().strip() for x in final_filtered}:
                                    continue  # Already in pool
                                # Accept uncommon foods (no is_common check)
                                wider_pool.append(f)
                            if wider_pool:
                                final_filtered = final_filtered + wider_pool
                                logger.info(f"        POOL WIDENING (comp {component_idx}): Dropped is_common filter, {original_count} → {len(final_filtered)} foods")
                        
                        # Step 2: If still < 5, pull from ALL slots matching meal_timing
                        if len(final_filtered) < 5:
                            meal_tag_lower = meal_name_normalized.lower()
                            timing_pool = []
                            
                            # 🔒 BREAKFAST SLOT INTEGRITY: Only allow semantically compatible pools
                            # Prevents starch/protein items from leaking into beverage/fruit slots
                            BREAKFAST_COMPATIBLE_SLOTS = {
                                'beverage': ['warm_beverage', 'dairy_or_alt', 'light_grain', 'fruit', 'fruit_snack'],
                                'warm_beverage': ['beverage', 'dairy_or_alt', 'light_grain', 'fruit', 'fruit_snack'],
                                'dairy_or_alt': ['beverage', 'warm_beverage', 'light_grain', 'fruit', 'fruit_snack'],
                                'light_grain': ['beverage', 'warm_beverage', 'dairy_or_alt', 'fruit', 'fruit_snack'],
                                'fruit': ['fruit_snack', 'nut_seed', 'dairy_or_alt'],
                                'nut_seed': ['fruit', 'fruit_snack', 'dairy_or_alt'],
                                'fruit_snack': ['fruit', 'nut_seed', 'dairy_or_alt'],
                            }
                            is_breakfast_meal = 'breakfast' in meal_tag_lower
                            allowed_alt_slots = BREAKFAST_COMPATIBLE_SLOTS.get(slot_name, None) if is_breakfast_meal else None
                            
                            for alt_slot, alt_foods in self.slot_pools.items():
                                if alt_slot == slot_name:
                                    continue
                                # 🔒 For breakfast: only pull from compatible slots (no proteins/starches in beverage/fruit slots)
                                if allowed_alt_slots is not None and alt_slot not in allowed_alt_slots:
                                    continue
                                for f in alt_foods:
                                    f_norm = f.lower().strip()
                                    if f_norm in used_swaps_normalized or f_norm in daily_used_normalized:
                                        continue
                                    if f_norm in weekly_excluded:
                                        continue
                                    if f_norm in {x.lower().strip() for x in final_filtered}:
                                        continue
                                    f_macros = self.all_foods_macros.get(f, {})
                                    f_tags = [t.lower().strip() for t in f_macros.get('meal_tags', [])]
                                    # Must match current meal timing
                                    if any(meal_tag_lower.split('_')[0] in t for t in f_tags) or any(t in meal_tag_lower for t in f_tags):
                                        timing_pool.append(f)
                            if timing_pool:
                                # 🔒 FAMILY CHECK ON WIDENED ITEMS: Prevent same-family foods from leaking in
                                if meal_used_families:
                                    family_safe_pool = []
                                    for f in timing_pool[:10]:
                                        f_families = _get_food_family(f)
                                        # Also check DB food_category/sub_food_category for robust detection
                                        f_macros_check = self.all_foods_macros.get(f, {})
                                        f_sub_cat = f_macros_check.get('sub_food_category', '').lower().strip()
                                        f_food_cat = f_macros_check.get('food_category', '').lower().strip()
                                        if f_sub_cat and f_sub_cat in meal_used_sub_categories:
                                            logger.debug(f"          POOL WIDEN BLOCKED: '{f}' sub_cat '{f_sub_cat}' already in meal")
                                            continue
                                        if f_families & meal_used_families:
                                            logger.debug(f"          POOL WIDEN BLOCKED: '{f}' families {f_families} overlap with {meal_used_families}")
                                            continue
                                        family_safe_pool.append(f)
                                    timing_pool_to_add = family_safe_pool
                                else:
                                    timing_pool_to_add = timing_pool[:10]
                                if timing_pool_to_add:
                                    final_filtered = final_filtered + timing_pool_to_add
                                    logger.info(f"        POOL WIDENING (comp {component_idx}): Cross-slot timing match, now {len(final_filtered)} foods (family-checked)")
                                else:
                                    logger.info(f"        POOL WIDENING (comp {component_idx}): All {len(timing_pool[:10])} candidates blocked by family/sub-category")
                    
                    # 🔒 DIVERSITY PRE-FILTER: Remove overused foods BEFORE selection so next-best candidate is chosen
                    if final_filtered:
                        _usage_cap = 2  # Uniform cap: max 2 appearances per food per week for ALL components
                        _gw = getattr(self, '_global_weekly_usage', {})
                        _div_pool = [f for f in final_filtered if _gw.get(self._normalize_for_tracking(f), 0) < _usage_cap]
                        if _div_pool:
                            logger.info(f"        DIVERSITY PRE-FILTER (comp {component_idx}): {len(final_filtered)} → {len(_div_pool)} foods (cap={_usage_cap}x)")
                            final_filtered = _div_pool
                        else:
                            # Fallback: ALL candidates overused — pick the LEAST-used subset for maximum diversity
                            _usage_counts = [(f, _gw.get(self._normalize_for_tracking(f), 0)) for f in final_filtered]
                            _min_usage = min(c for _, c in _usage_counts)
                            _least_used = [f for f, c in _usage_counts if c == _min_usage]
                            if len(_least_used) < len(final_filtered):
                                logger.info(f"        DIVERSITY FALLBACK (comp {component_idx}): All ≥{_usage_cap}x, keeping {len(_least_used)} least-used (count={_min_usage})")
                                final_filtered = _least_used
                    
                    selected_food = self._prioritize_common_foods(final_filtered, self.all_foods_macros)
                
                # 🔒 GRACEFUL COMPONENT SKIP: For comp 2+ and snacks, reject foods already used 2+ times this week
                # An incomplete meal is better than eating Milk Dumplings 5 days in a row
                if selected_food and (component_idx >= 2 or is_snack):
                    global_usage_check = getattr(self, '_global_weekly_usage', {})
                    selected_tracking_name = self._normalize_for_tracking(selected_food)
                    weekly_use_count = global_usage_check.get(selected_tracking_name, 0)
                    if weekly_use_count >= 2:
                        logger.warning(f"    COMP {component_idx} SKIP: '{selected_food}' already used {weekly_use_count}x this week (normalized: '{selected_tracking_name}') - skipping component")
                        selected_food = None
                        continue
                
                is_snack = 'snack' in meal_name.lower()
                if is_snack and selected_food:
                    food_macros_check = self.all_foods_macros.get(selected_food, {})
                    food_calories = food_macros_check.get('calories', 0)
                    
                    if food_calories <= 1.0:  
                        logger.warning(f"    ZERO-CALORIE REJECTION: '{selected_food}' has {food_calories} kcal (not appropriate for snack)")
                        selected_food = None  
                        continue
                
                if is_snack and selected_food:
                    food_name_lower = selected_food.lower()
                    DIP_KEYWORDS = ['dip', 'hummus', 'guacamole', 'spread', 'raita with dip', 'sauce', 'chutney dip']
                    
                    is_dip = any(kw in food_name_lower for kw in DIP_KEYWORDS)
                    
                    if is_dip:
                        logger.warning(f"    DIP REJECTION FOR SNACK: '{selected_food}' is a dip/spread (not appropriate for snack)")
                        selected_food = None  
                        continue
                
                if is_snack and selected_food:
                    food_macros_heavy_check = self.all_foods_macros.get(selected_food, {})
                    food_calories_per_100g = food_macros_heavy_check.get('calories', 0)
                    food_protein_g = food_macros_heavy_check.get('protein', 0)
                    
                    HEAVY_LEGUME_KEYWORDS = ['bean', 'lentil', 'chickpea', 'garbanzo', 'fava', 'edamame', 'soybean', 'lupini']
                    is_heavy_legume = any(kw in selected_food.lower() for kw in HEAVY_LEGUME_KEYWORDS)
                    
                    is_too_dense = food_calories_per_100g > 800
                    
                    DESSERT_SNACK_KEYWORDS = ['meringue', 'pastry', 'cake', 'cookie', 'brownie', 'muffin', 'waffle', 'pancake', 'donut']
                    is_dessert_snack = any(kw in selected_food.lower() for kw in DESSERT_SNACK_KEYWORDS)
                    
                    BAKED_PROTEIN_KEYWORDS = [
                        'tart', 'quiche', 'casserole', 'frittata', 'strata', 'souffle', 'soufflé',
                        'pie', 'galette', 'cobbler', 'crisp', 'crumble',
                        'baked egg', 'baked omelet', 'baked omelette', 'egg bake',
                        'lasagna', 'lasagne', 'moussaka', 'gratin', 'au gratin'
                    ]
                    is_baked_protein = any(kw in selected_food.lower() for kw in BAKED_PROTEIN_KEYWORDS)
                    
                    is_high_protein = food_protein_g > 5.0
                    
                    if is_heavy_legume:
                        logger.warning(f"    HEAVY SNACK REJECTION: '{selected_food}' is a legume/bean (too heavy for light snack)")
                        selected_food = None
                        continue
                    
                    is_too_dense = food_calories_per_100g > 800
                    
                    if is_too_dense:
                        logger.warning(f"    DENSE SNACK REJECTION: '{selected_food}' has {food_calories_per_100g:.0f} kcal/100g (> 800 = too dense for light snack)")
                        selected_food = None
                        continue
                    
                    if is_dessert_snack:
                        logger.warning(f"    DESSERT SNACK REJECTION: '{selected_food}' is dessert-like (not appropriate for healthy snack)")
                        selected_food = None
                        continue
                    
                    if is_baked_protein and is_high_protein:
                        logger.warning(f"    BAKED PROTEIN REJECTION: '{selected_food}' is a baked protein dish ({food_protein_g:.1f}g protein) - too heavy for light snack")
                        logger.warning(f"      User requirement: snacks should be 'ekdm light sa' (nuts/seeds/fruits/salad only)")
                        selected_food = None
                        continue
                
                if 'breakfast' in meal_name.lower() and selected_food:
                    food_name_lower = selected_food.lower()
                    
                    BREAKFAST_BEVERAGE_BLOCKLIST = [
                        'tea', 'coffee', 'espresso', 'latte', 'cappuccino', 'mocha',
                        'black tea', 'green tea', 'herbal tea', 'chai', 'matcha',
                        'iced tea', 'iced coffee', 'cold brew',
                        'energy drink', 'soda', 'cola', 'sprite', 'fanta',
                        'hot chocolate', 'cocoa drink'
                    ]
                    
                    BREAKFAST_BEVERAGE_ALLOWLIST = [
                        'smoothie', 'shake', 'buttermilk', 'lassi', 'milk shake',
                        'protein shake', 'fruit shake', 'berry smoothie', 'mango smoothie'
                    ]
                    
                    is_blocked_beverage = any(kw in food_name_lower for kw in BREAKFAST_BEVERAGE_BLOCKLIST)
                    is_allowed_beverage = any(kw in food_name_lower for kw in BREAKFAST_BEVERAGE_ALLOWLIST)
                    
                    if is_blocked_beverage and not is_allowed_beverage:
                        logger.warning(f"     BEVERAGE BLOCKED FOR BREAKFAST: '{selected_food}' is tea/coffee (inappropriate for breakfast)")
                        logger.warning(f"       Breakfast should have smoothies, nuts, seeds, or fruits instead of tea/coffee")
                        selected_food = None
                        continue
                
                if selected_food:
                    food_name_lower = selected_food.lower()
                    ANIMAL_PROTEIN_KEYWORDS = [
                        'chicken', 'beef', 'pork', 'lamb', 'veal', 'steak', 'meatball', 'mince', 
                        'salmon', 'cod', 'shrimp', 'fish', 'crab', 'trout', 'mackerel', 'whiting', 
                        'flounder', 'seafood', 'tuna', 'lobster', 'clam', 'conch', 'oyster', 'tilapia', 
                        'basa', 'haddock', 'sole', 'prawn', 'scallop', 'hen', 'drumstick', 'turkey',
                        'grouper', 'herring', 'swordfish', 'albacore', 'perch', 'pompano',
                        'halibut', 'catfish', 'snapper', 'mahi', 'sardine', 'anchovy',
                        'barramundi', 'seabass', 'bass', 'egg', 'omelet', 'omelette',
                        'brisket', 'pike', 'flank', 'roast', 'ribs', 'chuck', 'sirloin',
                        'tenderloin', 'cutlet', 'chop', 'fillet', 'wings', 'breast', 'thigh', 'leg'
                    ]
                    
                    is_animal_protein = any(kw in food_name_lower for kw in ANIMAL_PROTEIN_KEYWORDS)
                    
                    is_protein_slot = slot_name in ['protein_main', 'lean_protein', 'protein_source', 'protein_snack']
                    
                    if is_animal_protein and is_protein_slot and current_meal_animal_protein_count >= 1:
                        logger.warning(f"    ANIMAL PROTEIN LIMIT: '{selected_food}' would be protein #{current_meal_animal_protein_count + 1} in {meal_name} (Max: 1/meal in protein slots)")
                        logger.warning(f"      Current meal already has {current_meal_animal_protein_count} animal protein(s) in protein slots - rejecting to prevent stacking")
                        selected_food = None 
                        continue
                
                if selected_food:
                    food_macros_check = self.all_foods_macros.get(selected_food, {})
                    tdee = user_profile.get('tdee', 2000) if user_profile else 2000
                    is_valid_portion, portion_reason = self._validate_portion_size(
                        selected_food, food_macros_check, meal_name, component_idx, len(required_slots), tdee
                    )
                    
                    if not is_valid_portion:
                        if "TOO LARGE" in portion_reason:
                            match = re.search(r'is (\d+\.\d+) oz.*exceeds (\d+\.\d+) oz', portion_reason)
                            if match:
                                current_oz = float(match.group(1))
                                max_oz = float(match.group(2))
                                scale_factor = max_oz / current_oz
                                
                                if scale_factor >= 0.3:
                                    logger.info(f"    ✓ AUTO-SCALED: '{selected_food}' from {current_oz:.1f} oz → {max_oz:.1f} oz (scale: {scale_factor:.2f}x)")
                                else:
                                    logger.warning(f"     SCALE TOO SMALL: '{selected_food}' would be {scale_factor*100:.0f}% of original (min: 30%)")
                                    selected_food = None
                                    continue
                            else:
                                logger.warning(f"    {portion_reason}")
                                selected_food = None  
                                continue
                        else:
                            logger.warning(f"    {portion_reason}")
                            selected_food = None  
                            continue
                    else:
                        logger.debug(f"      {portion_reason}")
                
                if selected_food:
                    food_macros_check = self.all_foods_macros.get(selected_food, {})
                    db_meal_timing = food_macros_check.get('meal_tags', [])
                    
                    if db_meal_timing:
                        meal_normalized = meal_name.lower().replace('_', ' ')
                        db_timing_lower = [tag.lower().strip() for tag in db_meal_timing]
                        
                        if 'breakfast' in meal_normalized:
                            required_tags = ['breakfast']
                        elif 'morning' in meal_normalized and 'snack' in meal_normalized:
                            required_tags = ['snack', 'morning snack'] 
                        elif 'lunch' in meal_normalized:
                            required_tags = ['lunch']
                        elif 'evening' in meal_normalized and 'snack' in meal_normalized:
                            required_tags = ['snack', 'evening snack']  
                        elif 'snack 2' in meal_normalized:
                            required_tags = ['snack', 'evening snack'] 
                        elif 'dinner' in meal_normalized:
                            required_tags = ['dinner']
                        else:
                            required_tags = []  
                        
                        if required_tags:
                            has_match = any(req_tag in db_timing_lower for req_tag in required_tags)
                            
                            if not has_match:
                                if ('evening' in meal_normalized or 'snack 2' in meal_normalized) and 'snack' in meal_normalized:
                                    if 'breakfast' in db_timing_lower:
                                        logger.warning(f"     MEAL TIMING VIOLATION: '{selected_food}' is BREAKFAST item, "
                                                     f"NEVER appropriate for Evening Snack")
                                        logger.warning(f"       Food tags: {db_meal_timing}, Current meal: {meal_name}")
                                        selected_food = None  
                                        continue
                                
                                logger.warning(f"    MEAL TIMING MISMATCH: '{selected_food}' is for {db_meal_timing}, "
                                             f"not appropriate for {meal_name}")
                                logger.warning(f"       Expected tags: {required_tags}, Food has: {db_timing_lower}")
                                selected_food = None  
                                continue
                            else:
                                logger.debug(f"       Meal timing valid: '{selected_food}' appropriate for {meal_name}")
                
                if selected_food and meal_items:
                    TYPE_STACKING_PATTERNS = {
                        'porridge': ['porridge', 'oats', 'oat bowl', 'overnight oats', 'kheer with oats'],
                        'dip': ['dip', 'hummus', 'guacamole', 'raita with dip', 'spread'],
                        'smoothie': ['smoothie', 'shake', 'blended', 'protein shake'],
                        'salad_main': ['salad bowl', 'tossed salad', 'mixed salad', 'grain salad', 'pasta salad'],  
                        'khichdi': ['khichdi', 'khichri', 'kichdi', 'kitchari'],
                        'biryani': ['biryani', 'biriyani', 'pulao with protein'],  
                    }
                    
                    selected_food_lower = selected_food.lower()
                    
                    selected_type = None
                    for type_name, patterns in TYPE_STACKING_PATTERNS.items():
                        if any(pattern in selected_food_lower for pattern in patterns):
                            selected_type = type_name
                            break
                    
                    if selected_type:
                        meal_already_has_type = False
                        for existing_item in meal_items:
                            existing_name_lower = existing_item.get('name', '').lower()
                            if any(pattern in existing_name_lower for pattern in TYPE_STACKING_PATTERNS[selected_type]):
                                meal_already_has_type = True
                                break
                        
                        if meal_already_has_type:
                            logger.debug(f"    TYPE DIVERSITY VIOLATION: '{selected_food}' is a {selected_type}, "
                                         f"but meal already has another {selected_type} item")
                            logger.debug(f"      Rejecting to prevent type stacking - trying next option")
                            selected_food = None  
                            continue
                        else:
                            logger.debug(f"       Type diversity OK: First {selected_type} in meal")
                
                selected_from_slot = slot_name
                logger.info(f"    Component {component_idx}: '{selected_food}' from '{slot_name}'")
                
                if selected_food and meal_key in ['lunch', 'dinner']:
                    selected_food_lower = selected_food.lower()
                    PROTEIN_CHECK_KEYWORDS = [
                        'chicken', 'beef', 'pork', 'lamb', 'veal', 'steak', 'meatball', 'mince',
                        'salmon', 'cod', 'shrimp', 'fish', 'crab', 'trout', 'mackerel', 'whiting',
                        'flounder', 'seafood', 'tuna', 'lobster', 'clam', 'conch', 'oyster', 'tilapia',
                        'basa', 'haddock', 'sole', 'prawn', 'scallop', 'hen', 'drumstick', 'turkey',
                        'grouper', 'herring', 'swordfish', 'albacore', 'perch', 'pompano',
                        'halibut', 'catfish', 'snapper', 'mahi', 'sardine', 'anchovy',
                        'barramundi', 'seabass', 'bass', 'egg', 'omelet', 'omelette',
                        'brisket', 'pike', 'flank', 'roast', 'ribs', 'chuck', 'sirloin',
                        'tenderloin', 'cutlet', 'chop', 'fillet', 'wings', 'breast', 'thigh', 'leg', 'duck'
                    ]
                    is_protein_item = any(kw in selected_food_lower for kw in PROTEIN_CHECK_KEYWORDS)
                    
                    if is_protein_item:
                        this_protein_family = self._detect_protein_family(selected_food)
                        main_protein_families = {'seafood', 'poultry', 'red_meat'}
                        
                        if this_protein_family in main_protein_families:
                            for other_meal_key, other_family in self.daily_meal_protein_families.items():
                                if other_meal_key.lower() != meal_key.lower() and other_family in main_protein_families:
                                    if other_family == this_protein_family:
                                        logger.error(f"     PROTEIN FAMILY CONFLICT: '{selected_food}' is {this_protein_family}, already used in {other_meal_key}")
                                        logger.error(f"       Component {component_idx}: Protein detected in ANY slot (not just Component 1)")
                                        logger.error(f"       USER RULE: Lunch and Dinner MUST have DIFFERENT protein families")
                                        logger.error(f"       If {other_meal_key} = {other_family} → {meal_key} CANNOT have {this_protein_family}")
                                        logger.error(f"       Rejecting '{selected_food}' - trying next option")
                                        selected_food = None 
                                        break
                        
                        if not selected_food:
                            continue  

                is_grain_slot = (component_idx == 2 and 
                                 meal_key in ['lunch', 'dinner'] and 
                                 any(grain_opt in component_options for grain_opt in ['grain_base', 'starch_base', 'light_grain']))
  
                selected_normalized = selected_food.lower().strip() if selected_food else None
                used_today = selected_normalized in {f.lower().strip() for f in self.daily_used_foods} if selected_normalized else False
                
                is_snack = 'snack' in meal_name.lower()
                is_small_fruit_pool = is_snack and len(final_filtered) <= 5  # 🔒 Reduced from 10 to 5
                
                if selected_food and used_today:
                    # 🔒 STRICTER REPETITION POLICY - Reduce allowances
                    if is_small_fruit_pool:
                        logger.warning(f"           ⚠️ SNACK POOL CRITICALLY SMALL ({len(final_filtered)} fruits) - ALLOWING SAME-DAY REPETITION: '{selected_food}'")
                        logger.warning(f"           Reason: Limited fruit options after filtering - diversity relaxed for snacks only")
                    else:
                        logger.error(f"          ❌ SAME-DAY REPETITION BLOCKED: '{selected_food}' already used in previous meal TODAY")
                        
                        if is_grain_slot and len(final_filtered) <= 1:  # 🔒 Changed from <=2 to <=1
                            logger.error(f"           🚨 CRITICAL: Grain slot has only {len(final_filtered)} option(s), but '{selected_food}' was used today")
                            logger.error(f"           REFUSING REPETITION: Same-day grain diversity is MANDATORY (3-2-4-2-4 structure enforcement)")
                            logger.error(f"           Solution: Will trigger emergency grain from global pool to avoid violating structure")
                            selected_food = None
                            continue
                        else:
                            logger.error(f"           ❌ BLOCKED: Enforcing daily diversity - searching for alternative")
                            selected_food = None
                            continue
                
                if selected_food and self.used_failsafes_previous_day:
                    was_used_previously = selected_normalized in {f.lower().strip() for f in self.used_failsafes_previous_day}
                    if was_used_previously:
                        # 🔒 ZERO TOLERANCE: No consecutive day repeats, period
                        logger.error(f"         ❌ CROSS-DAY REPETITION BLOCKED: '{selected_food}' was used yesterday")
                        logger.error(f"           Enforcing ZERO consecutive repeats - searching for alternative (pool: {len(final_filtered)})")
                        selected_food = None  
                        continue  
                    else:
                        logger.info(f"        ✅ NEW FOOD: '{selected_food}' not from previous day")
                
                # 🔒 NON-CONSECUTIVE DAY CHECK: Allow max 2 reuses per day from earlier days
                if selected_food:
                    non_consec_pool = getattr(self, 'non_consecutive_foods_pool', set())
                    if non_consec_pool and selected_normalized in {f.lower().strip() for f in non_consec_pool}:
                        reuse_count = getattr(self, 'non_consecutive_reuse_count', 0)
                        max_reuse = 2  # User requirement: max 2 items from non-consecutive days
                        if reuse_count >= max_reuse:
                            logger.error(f"         ❌ NON-CONSECUTIVE LIMIT: '{selected_food}' from earlier days (already {reuse_count}/{max_reuse} reused today)")
                            selected_food = None
                            continue
                        else:
                            self.non_consecutive_reuse_count = reuse_count + 1
                            logger.warning(f"         ⚠️ NON-CONSECUTIVE REUSE: '{selected_food}' ({self.non_consecutive_reuse_count}/{max_reuse} quota used)")
                elif selected_food:
                    logger.warning(f"        ⚠️ HISTORY UNKNOWN: No previous meal history loaded - cannot check for repetition")
                
                if selected_food and user_profile:
                    _sel_macros = self.all_foods_macros.get(selected_food, {})
                    _is_safe, _reason = self._is_clinically_safe(
                        selected_food, _sel_macros, user_profile,
                        daily_sodium, daily_potassium, daily_cholesterol, daily_fat,
                        meal_name=meal_name
                    )
                    if not _is_safe:
                        logger.debug(f"        CLINICAL SAFETY REJECTION: '{selected_food}' failed _is_clinically_safe: {_reason}")
                        selected_food = None
                        continue
                
                break  
            
            if not selected_food:
                cross_meal_slots = []
                
                if component_idx == 1 and meal_key in ['lunch', 'dinner']:
                    # 🔒 PROTEIN FALLBACK: Try ALL protein pools before giving up
                    cross_meal_slots = ['lean_protein', 'protein_source', 'protein_snack', 'protein_main']
                    logger.warning(f"     COMPONENT 1 PROTEIN: Primary slot exhausted - trying ALL protein pools as fallback")
                    
                elif component_idx == 2 and meal_key in ['lunch', 'dinner']:
                    cross_meal_slots = ['grain_base', 'starch_base', 'light_grain']
                    logger.info(f"    Component {component_idx} (CEREAL): Primary grain slots exhausted, trying shared grain slots")
                
                elif meal_key == 'breakfast':
                    # 🔒 BREAKFAST SLOT-AWARE FALLBACK: Prevent proteins leaking into beverage/fruit slots
                    if component_idx == 1:
                        # Protein slot: can fallback to other protein pools
                        cross_meal_slots = ['protein_snack', 'lean_protein', 'protein_source']
                        logger.info(f"    Breakfast Component 1 (protein): Trying other protein pools")
                    elif component_idx == 2:
                        # Beverage/dairy slot: only light/liquid items
                        cross_meal_slots = ['dairy_or_alt', 'fruit', 'fruit_snack', 'nut_seed']
                        logger.info(f"    Breakfast Component 2 (beverage/dairy): Trying compatible light pools")
                    else:
                        # Fruit/nut slot: only fruit/nut items
                        cross_meal_slots = ['fruit', 'fruit_snack', 'nut_seed', 'dairy_or_alt']
                        logger.info(f"    Breakfast Component 3 (fruit/nut): Trying compatible pools")
                elif meal_key == 'lunch':
                    cross_meal_slots = ['cooked_vegetable', 'soup_or_broth', 'condiment_side', 'fermented_side']
                    logger.info(f"    Component {component_idx}: Primary slots exhausted, trying Dinner slots")
                elif meal_key == 'dinner':
                    cross_meal_slots = ['primary_vegetable', 'cooked_vegetable', 'fat_source', 'condiment']
                    logger.info(f"    Component {component_idx}: Primary slots exhausted, trying Lunch slots")
                
                for cross_slot_name in cross_meal_slots:
                    if cross_slot_name not in self.slot_pools:
                        continue
                    
                    used_swaps_normalized = {f.lower().strip() for f in used_swaps}
                    daily_used_normalized = {f.lower().strip() for f in self.daily_used_foods}
                    prev_day_normalized = {f.lower().strip() for f in self.used_failsafes_previous_day} if self.used_failsafes_previous_day else set()
                    
                    # NEW: Filter by food_category too (prevent same category consecutive days)
                    # WEEKLY EXCLUSION in cross-meal fallback (critical fix)
                    weekly_excluded_fallback = getattr(self, 'weekly_hard_excluded', set())
                    slot_food_pool = []
                    for f in self.slot_pools[cross_slot_name]:
                        food_name_normalized = f.lower().strip()
                        if food_name_normalized in used_swaps_normalized or food_name_normalized in daily_used_normalized:
                            continue
                        
                        # 🚫 WEEKLY HARD EXCLUSION in fallback path too
                        if weekly_excluded_fallback and food_name_normalized in weekly_excluded_fallback:
                            continue
                        
                        # 🔒 CROSS-DAY BLOCK: Also block foods from previous day in fallback slots
                        if food_name_normalized in prev_day_normalized:
                            logger.debug(f"      CROSS-DAY BLOCKED (fallback): '{f}' (used yesterday)")
                            continue
                        
                        # Check food_category
                        if f in self.all_foods_macros:
                            food_category = self.all_foods_macros[f].get('food_category', '').lower().strip()
                            
                            # Check Cross-Day
                            if food_category and food_category in used_food_categories:
                                logger.debug(f"      CATEGORY BLOCKED: '{f}' (used yesterday)")
                                continue
                            
                            # Check Intra-Meal
                            # � SOFT PENALTY: Category conflicts handled by scoring function (-50 penalty)
                            # No longer hard-blocking here to prevent component starvation
                            if food_category and food_category in meal_used_food_categories:
                                logger.debug(f"      INTRA-MEAL SOFT: '{f}' (category '{food_category}' already on plate - will get -50 score penalty)")
                                # Allow through - scoring will deprioritize but not eliminate
                        
                        slot_food_pool.append(f)
                    
                    group_unique_foods = []
                    for food_name in slot_food_pool:
                        if food_name not in self.all_foods_macros:
                            continue
                        
                        food_macros = self.all_foods_macros[food_name]
                        food_group_data = food_macros.get('food_group_full', [])
                        if isinstance(food_group_data, list):
                            food_groups = [fg.strip() for fg in food_group_data if fg and fg.strip()]
                        elif isinstance(food_group_data, str):
                            food_groups = [fg.strip() for fg in food_group_data.split('|') if fg.strip()]
                        else:
                            food_groups = []
                        
                        CRITICAL_GROUPS = {'protein_main', 'protein_source', 'lean_protein', 'grain_base', 'starch_base', 'light_grain', 'fruit', 'fruit_snack', 'nut_seed', 'primary_vegetable', 'cooked_vegetable', 'soup_or_broth', 'fermented_side'}
                        critical_groups_in_food = [fg for fg in food_groups if fg in CRITICAL_GROUPS]
                        has_conflict = any(fg in meal_used_food_groups for fg in critical_groups_in_food)
                        
                        # 🔒 STARCH MUTUAL EXCLUSION: grain_base, starch_base, light_grain are mutually exclusive
                        # If meal already has ANY starch/grain slot filled, block foods with OTHER starch/grain slots
                        if not has_conflict:
                            STARCH_GROUPS = {'grain_base', 'starch_base', 'light_grain'}
                            food_starch_groups = [fg for fg in critical_groups_in_food if fg in STARCH_GROUPS]
                            used_starch_groups = STARCH_GROUPS & meal_used_food_groups
                            if food_starch_groups and used_starch_groups:
                                has_conflict = True
                        
                        if not has_conflict:
                            group_unique_foods.append(food_name)
                    
                    if not group_unique_foods:
                        continue
                    
                    
                    CROSS_MEAL_PROTEIN_KEYWORDS = [
                        'chicken', 'beef', 'pork', 'lamb', 'veal', 'steak', 'meatball', 'mince',
                        'salmon', 'cod', 'shrimp', 'fish', 'crab', 'trout', 'mackerel', 'whiting',
                        'flounder', 'seafood', 'tuna', 'lobster', 'clam', 'conch', 'oyster', 'tilapia',
                        'basa', 'haddock', 'sole', 'prawn', 'scallop', 'hen', 'drumstick', 'turkey',
                        'grouper', 'herring', 'swordfish', 'albacore', 'perch', 'pompano',
                        'halibut', 'catfish', 'snapper', 'mahi', 'sardine', 'anchovy',
                        'barramundi', 'seabass', 'bass', 'egg', 'omelet', 'omelette',
                        'brisket', 'pike', 'flank', 'roast', 'ribs', 'chuck', 'sirloin',
                        'tenderloin', 'cutlet', 'chop', 'fillet', 'wings', 'breast', 'thigh', 'leg'
                    ]
                    
                    CROSS_MEAL_CEREAL_KEYWORDS = [
                        'rice', 'basmati', 'jasmine', 'bread', 'roti', 'naan', 'chapati', 'paratha',
                        'wheat', 'whole wheat', 'multigrain', 'oat', 'oats', 'oatmeal', 'porridge',
                        'quinoa', 'millet', 'bajra', 'jowar', 'ragi', 'pasta', 'noodle', 'spaghetti',
                        'couscous', 'bulgur', 'barley', 'idli', 'dosa', 'upma', 'poha',
                        'granola', 'muesli', 'cereal', 'corn flakes', 'cornflakes', 'bran flakes',
                        'wheat flakes', 'cheerios', 'special k', 'frosted flakes', 'bircher',
                        'overnight oat', 'steel cut oat', 'rolled oat', 'granola bar', 'granola cluster',
                        'almond granola', 'honey granola', 'muesli bowl', 'granola bowl', 'porridge bowl'
                    ]
                    
                    filtered_cross_meal_foods = []
                    for food_name in group_unique_foods:
                        food_name_lower = food_name.lower()
                        is_protein = any(kw in food_name_lower for kw in CROSS_MEAL_PROTEIN_KEYWORDS)
                        is_cereal = any(kw in food_name_lower for kw in CROSS_MEAL_CEREAL_KEYWORDS)
                        
                        if component_idx >= 2 and current_meal_animal_protein_count > 0 and is_protein:
                            logger.debug(f"         CROSS-MEAL PROTEIN BLOCK: '{food_name}' blocked (meal has {current_meal_animal_protein_count} protein)")
                            continue
                        
                        # 🔒 FIX: Block cereals from NON-GRAIN components if meal already has a grain
                        # component_idx == 2 is the grain slot — allow the first grain there
                        if is_cereal and len(self.meal_used_grains) > 0 and component_idx != 2:
                            logger.debug(f"         CROSS-MEAL CEREAL BLOCK: '{food_name}' blocked - meal already has grain(s): {list(self.meal_used_grains)}")
                            continue
                        
                        if component_idx >= 3 and is_cereal:
                            logger.debug(f"         CROSS-MEAL CEREAL BLOCK: '{food_name}' blocked from Component {component_idx} (vegetable/fat slot)")
                            continue
                        
                        if is_protein and meal_key in ['lunch', 'dinner']:
                            this_protein_family = self._detect_protein_family(food_name)
                            main_protein_families = {'seafood', 'poultry', 'red_meat'}
                            
                            if this_protein_family in main_protein_families:
                                family_conflict = False
                                for other_meal_key, other_family in self.daily_meal_protein_families.items():
                                    if other_meal_key.lower() != meal_key.lower() and other_family in main_protein_families:
                                        if other_family == this_protein_family:
                                            logger.debug(f"         CROSS-MEAL FAMILY BLOCK: '{food_name}' is {this_protein_family}, already used in {other_meal_key}")
                                            family_conflict = True
                                            break
                                
                                if family_conflict:
                                    continue  
                        
                        filtered_cross_meal_foods.append(food_name)
                    
                    if not filtered_cross_meal_foods:
                        logger.debug(f"      CROSS-MEAL FILTER: All {len(group_unique_foods)} foods blocked (protein or cereal conflicts)")
                        continue  

                    if user_profile and meal_key.lower() in ['breakfast', 'lunch', 'dinner']:
                        user_cuisine = user_profile.get('cuisine', 'global')
                        if isinstance(user_cuisine, list):
                            user_cuisine = user_cuisine[0] if user_cuisine else 'global'
                        user_cuisine = normalize_cuisine(user_cuisine)
                        user_cuisine_lower = str(user_cuisine).lower().strip()
                        
                        cuisine_cascade = CUISINE_CASCADE.get(user_cuisine_lower, [user_cuisine_lower])
                        cuisine_cascade_lower = [str(c).lower().strip() for c in cuisine_cascade]
                        global_equivalent_tags = {'global', 'none', 'international', 'western'}
                        
                        cuisine_filtered_cross = []
                        for food_name in filtered_cross_meal_foods:
                            food_cuisines = self.all_foods_macros.get(food_name, {}).get('cuisine', [])
                            if isinstance(food_cuisines, str):
                                food_cuisines = [food_cuisines]
                            food_cuisines_lower = [str(c).lower().strip() for c in food_cuisines if c]
                            
                            if not food_cuisines_lower:
                                continue
                            
                            if any(
                                cascade_cuisine == fc 
                                for cascade_cuisine in cuisine_cascade_lower
                                for fc in food_cuisines_lower
                            ):
                                cuisine_filtered_cross.append(food_name)
                        
                        if len(cuisine_filtered_cross) == 0:
                            logger.debug(f"      CROSS-MEAL TIER 1 EMPTY: No {user_cuisine} foods in cross-meal pool")
                            for food_name in filtered_cross_meal_foods:
                                food_cuisines = self.all_foods_macros.get(food_name, {}).get('cuisine', [])
                                if isinstance(food_cuisines, str):
                                    food_cuisines = [food_cuisines]
                                food_cuisines_lower = [str(c).lower().strip() for c in food_cuisines if c]
                                
                                is_universal = (
                                    not food_cuisines_lower or
                                    any(tag in global_equivalent_tags for tag in food_cuisines_lower)
                                )
                                
                                if is_universal:
                                    cuisine_filtered_cross.append(food_name)
                        
                        if len(cuisine_filtered_cross) == 0:
                            logger.debug(f"      CROSS-MEAL CUISINE REJECTED: No {user_cuisine} OR pure global foods in '{cross_slot_name}'")
                            logger.debug(f"         Tier 1 (regional): 0 foods | Tier 2 (pure global): 0 foods")
                            logger.debug(f"         Skipping cross-meal slot to maintain 0% cuisine violation")
                            continue  
                        
                        logger.debug(f"      CROSS-MEAL CUISINE FILTER: {len(filtered_cross_meal_foods)} → {len(cuisine_filtered_cross)} foods")
                        filtered_cross_meal_foods = cuisine_filtered_cross
                    
                    if user_profile:
                        _normalized_conds = self._normalize_user_conditions(user_profile)
                        _normalized_conds = [c for c in _normalized_conds if c in self.DIETARY_CONDITIONS_ONLY]
                        if _normalized_conds:
                            HARD_BLOCK_CONDITIONS = {
                                'gerd / acid reflux', 'ibs / irritable bowel syndrome', "crohn's disease",
                                'celiac disease', 'kidney disease (ckd)', 'liver disease (nafld/cirrhosis)',
                                'diabetes type 1', 'diabetes type 2', 'prediabetes',
                            }
                            _safe_cross = []
                            for _fn in filtered_cross_meal_foods:
                                _fm = self.all_foods_macros.get(_fn, {})
                                _fa = _fm.get('medical_conditions_avoid', [])
                                _blocked = False
                                if _fa:
                                    _al = [m.lower().strip().replace('_', ' ').replace('/', ' / ') for m in _fa if m]
                                    for _uc in _normalized_conds:
                                        for _ac in _al:
                                            if (_uc == _ac or (len(_uc) > 4 and _uc in _ac) or (len(_ac) > 4 and _ac in _uc)):
                                                if _uc in HARD_BLOCK_CONDITIONS:
                                                    _blocked = True
                                                break
                                        if _blocked:
                                            break
                                if not _blocked:
                                    _safe_cross.append(_fn)
                            if _safe_cross:
                                filtered_cross_meal_foods = _safe_cross
                            else:
                                logger.warning(f"      CROSS-MEAL MEDICAL FILTER: ALL foods removed for '{cross_slot_name}'! Keeping pool.")
                    
                    selected_food = self._prioritize_common_foods(filtered_cross_meal_foods, self.all_foods_macros)
                    
                    # 🔒 FAMILY CHECK on cross-meal fallback: Prevent same-family foods in breakfast
                    if selected_food and meal_used_families:
                        _cross_families = _get_food_family(selected_food)
                        # Also check DB sub_food_category
                        _cross_macros = self.all_foods_macros.get(selected_food, {})
                        _cross_sub_cat = _cross_macros.get('sub_food_category', '').lower().strip()
                        if _cross_families & meal_used_families:
                            logger.warning(f"      CROSS-MEAL FAMILY BLOCK: '{selected_food}' families {_cross_families} overlap with meal {meal_used_families}")
                            selected_food = None
                            continue
                        if _cross_sub_cat and _cross_sub_cat in meal_used_sub_categories:
                            logger.warning(f"      CROSS-MEAL SUB-CAT BLOCK: '{selected_food}' sub_cat '{_cross_sub_cat}' already in meal")
                            selected_food = None
                            continue
                    
                    if selected_food and user_profile:
                        _sel_macros = self.all_foods_macros.get(selected_food, {})
                        _is_safe, _reason = self._is_clinically_safe(
                            selected_food, _sel_macros, user_profile,
                            daily_sodium, daily_potassium, daily_cholesterol, daily_fat,
                            meal_name=meal_name
                        )
                        if not _is_safe:
                            logger.debug(f"      CROSS-MEAL CLINICAL REJECTION: '{selected_food}' failed safety check: {_reason}")
                            selected_food = None
                            continue  
                    
                    if selected_food:
                        logger.info(f"      CROSS-MEAL SLOT SUCCESS: '{selected_food}' from {cross_slot_name} ({meal_key} borrowed from related meal)")
                        logger.info(f"        Passed protein+cereal blocking (meal protein count: {current_meal_animal_protein_count})")
                        selected_from_slot = cross_slot_name
                        break
            
            if not selected_food:
                logger.warning(f" Component {component_idx}: No valid food found from options: {' OR '.join(component_options)}")
                
                # 🚨 PROTEIN EMERGENCY PASS: If protein slot (component 1) is STILL empty, 
                # retry ALL protein pools WITHOUT cross-day blocking (allow yesterday's proteins)
                if component_idx == 1 and meal_key in ['lunch', 'dinner']:
                    logger.warning(f"   🚨 PROTEIN EMERGENCY: Retrying protein pools WITHOUT cross-day/category blocking")
                    emergency_protein_pools = ['protein_main', 'lean_protein', 'protein_source', 'protein_snack']
                    
                    for emergency_slot in emergency_protein_pools:
                        if emergency_slot not in self.slot_pools:
                            continue
                        
                        used_swaps_normalized = {f.lower().strip() for f in used_swaps}
                        daily_used_normalized = {f.lower().strip() for f in self.daily_used_foods}
                        
                        # ONLY filter by daily-used and swaps - but KEEP weekly exclusion (non-negotiable)
                        weekly_excluded_emergency = getattr(self, 'weekly_hard_excluded', set())
                        emergency_pool = []
                        for f in self.slot_pools[emergency_slot]:
                            food_name_normalized = f.lower().strip()
                            if food_name_normalized in used_swaps_normalized or food_name_normalized in daily_used_normalized:
                                continue
                            if weekly_excluded_emergency and food_name_normalized in weekly_excluded_emergency:
                                continue
                            emergency_pool.append(f)
                        
                        if not emergency_pool:
                            continue
                        
                        # Apply cuisine filter (keep this - cuisine is a hard requirement)
                        if user_profile and meal_key.lower() in ['lunch', 'dinner']:
                            user_cuisine = user_profile.get('cuisine', 'global')
                            if isinstance(user_cuisine, list):
                                user_cuisine = user_cuisine[0] if user_cuisine else 'global'
                            user_cuisine = normalize_cuisine(user_cuisine)
                            user_cuisine_lower = str(user_cuisine).lower().strip()
                            cuisine_cascade = CUISINE_CASCADE.get(user_cuisine_lower, [user_cuisine_lower])
                            cuisine_cascade_lower = [str(c).lower().strip() for c in cuisine_cascade]
                            global_equivalent_tags = {'global', 'none', 'international', 'western'}
                            
                            cuisine_matched = []
                            for food_name in emergency_pool:
                                food_cuisines = self.all_foods_macros.get(food_name, {}).get('cuisine', [])
                                if isinstance(food_cuisines, str):
                                    food_cuisines = [food_cuisines]
                                food_cuisines_lower = [str(c).lower().strip() for c in food_cuisines if c]
                                if not food_cuisines_lower:
                                    continue
                                if any(cc == fc for cc in cuisine_cascade_lower for fc in food_cuisines_lower):
                                    cuisine_matched.append(food_name)
                                elif any(tag in global_equivalent_tags for tag in food_cuisines_lower):
                                    cuisine_matched.append(food_name)
                            
                            if cuisine_matched:
                                emergency_pool = cuisine_matched
                        
                        # Apply medical safety (keep this - safety is non-negotiable)
                        if user_profile:
                            _normalized_conds = self._normalize_user_conditions(user_profile)
                            if _normalized_conds:
                                _safe_emergency = []
                                for _fn in emergency_pool:
                                    _fm = self.all_foods_macros.get(_fn, {})
                                    _fa = _fm.get('medical_conditions_avoid', [])
                                    _blocked = False
                                    if _fa:
                                        _al = [m.lower().strip() for m in _fa if m]
                                        for _uc in _normalized_conds:
                                            for _ac in _al:
                                                if (_uc == _ac or (len(_uc) > 4 and _uc in _ac) or (len(_ac) > 4 and _ac in _uc)):
                                                    _blocked = True
                                                    break
                                            if _blocked:
                                                break
                                    if not _blocked:
                                        _safe_emergency.append(_fn)
                                if _safe_emergency:
                                    emergency_pool = _safe_emergency
                        
                        if emergency_pool:
                            selected_food = self._prioritize_common_foods(emergency_pool, self.all_foods_macros)
                            if selected_food:
                                selected_from_slot = emergency_slot
                                logger.warning(f"   ✅ PROTEIN EMERGENCY SUCCESS: '{selected_food}' from {emergency_slot} (cross-day block relaxed)")
                                break
                    
                    if not selected_food:
                        logger.error(f"   ❌ PROTEIN EMERGENCY FAILED: All protein pools completely exhausted even without blocking")
                
                if not selected_food:
                    logger.warning(f"   Cross-meal slot sharing also exhausted - meal will be missing this component")
                    logger.warning(f"   Macro adjustment will compensate")
                continue
            
            # 🔒 FINAL SAFETY CHECK: Absolute last line of defense against weekly over-repetition
            # This catches foods that slipped through fallback/emergency paths
            _weekly_hard = getattr(self, 'weekly_hard_excluded', set())
            if _weekly_hard and selected_food.lower().strip() in _weekly_hard:
                logger.error(f"    🚫 FINAL SAFETY BLOCK: '{selected_food}' is in weekly_hard_excluded - REJECTING (appeared 2+ times this week)")
                continue
            # Also check via normalized tracking (catches variants like "Cooked X" vs "X")
            _gw_final = getattr(self, '_global_weekly_usage', {})
            if _gw_final:
                _final_norm = self._normalize_for_tracking(selected_food)
                _final_count = _gw_final.get(_final_norm, 0)
                if _final_count >= 2:
                    logger.error(f"    🚫 FINAL USAGE BLOCK: '{selected_food}' (normalized: '{_final_norm}') used {_final_count}x this week - REJECTING")
                    continue
            
            # 🔒 FINAL FAMILY CHECK: Prevent same-family foods from stacking (especially in breakfast)
            if meal_used_families:
                _final_families = _get_food_family(selected_food)
                if _final_families & meal_used_families:
                    logger.error(f"    🚫 FINAL FAMILY BLOCK: '{selected_food}' families {_final_families} overlap with meal families {meal_used_families}")
                    continue

            food_name_from_db = selected_food.strip()
            
            def _extract_core_food_name(name: str) -> str:
                """Extract core food name by removing portions, cooking methods, parentheses, punctuation"""
                import re
                name = re.sub(r'\([^)]*\)', '', name)
                name = re.sub(r'[.,;:!?-]', ' ', name)
                stop_words = {'with', 'and', 'the', 'a', 'an', 'of', 'in', 'homemade', 'fresh', 'organic',
                             'baked', 'grilled', 'cooked', 'braised', 'steamed', 'roasted', 'fried', 'raw',
                             'flesh', 'only', 'whole', 'sliced', 'diced', 'chopped', 'mashed', 'shredded'}
                words = [w.lower().strip() for w in name.split() if w.lower().strip() not in stop_words and len(w) > 1]
                return ' '.join(words)
            
            selected_core = _extract_core_food_name(food_name_from_db)
            is_duplicate_in_meal = False
            for existing_item in meal_items:
                existing_name = existing_item.get('name', '')
                existing_core = _extract_core_food_name(existing_name)
                
                if selected_core == existing_core and selected_core: 
                    logger.error(f" DUPLICATE IN SAME MEAL: '{food_name_from_db}' ≈ '{existing_name}'")
                    logger.error(f"    Core names match: '{selected_core}' (REJECTING - no duplicates allowed in same meal)")
                    is_duplicate_in_meal = True
                    break
                
                def _word_similarity(name1: str, name2: str) -> float:
                    words1 = set(w for w in name1.lower().split() if len(w) > 2)
                    words2 = set(w for w in name2.lower().split() if len(w) > 2)
                    if not words1 or not words2:
                        return 0.0
                    return len(words1 & words2) / len(words1 | words2)
                
                similarity = _word_similarity(selected_core, existing_core)
                if similarity >= 0.70:  
                    logger.error(f" DUPLICATE IN SAME MEAL: '{food_name_from_db}' ≈ '{existing_name}' ({similarity:.0%} similar)")
                    logger.error(f"    Core: '{selected_core}' vs '{existing_core}' - Rejecting similar food")
                    is_duplicate_in_meal = True
                    break
            
            if is_duplicate_in_meal:
                logger.warning(f" Component {component_idx}: Selected food '{food_name_from_db}' is duplicate in this meal - trying next option")
                continue
            
            # 🔒 FOOD TYPE BLOCKING - Block multiple items of same TYPE per day
            # Prevents: "barley khichdi" + "bajra khichdi" + "moong dal khichdi" (all are khichdi type)
            food_name_lower = food_name_from_db.lower().strip()
            
            FOOD_TYPE_KEYWORDS = {
                'khichdi': ['khichdi', 'khichadi', 'kichdi'],
                'curry': ['curry', 'curries', 'korma', 'masala curry'],
                'dal': ['dal', 'daal', 'dhal', 'lentil curry'],
                'pulao': ['pulao', 'pilaf', 'pilau'],
                'biryani': ['biryani', 'biriyani'],
                'paratha': ['paratha', 'parantha'],
                'dosa': ['dosa', 'dosai'],
                'idli': ['idli', 'idly'],
                'upma': ['upma', 'uppuma'],
                'poha': ['poha', 'pohe'],
                'salad': ['salad', 'slaw'],
                'sandwich': ['sandwich', 'wrap', 'burger'],
                # REMOVED umbrella categories that blocked entire food groups daily:
                # - 'heavy_carb': per-meal grain limit already prevents duplicates. Each meal needs grain.
                # - 'protein_dish': individual types (tofu/paneer/egg) + protein_family check suffice.
                # - 'nut_seed': different nuts across meals is fine (breakfast seeds + dinner almond fat).
                # REMOVED individual protein types (tofu, paneer, egg) from daily blocking:
                # - Different tofu/paneer/egg dishes across meals is nutritionally fine
                # - Per-meal duplicate check prevents same-meal repetition
            }
            
            # Detect food type of current item
            current_food_type = None
            for type_name, keywords in FOOD_TYPE_KEYWORDS.items():
                if any(kw in food_name_lower for kw in keywords):
                    current_food_type = type_name
                    break
            
            # Check if this food type was already used today
            is_food_type_duplicate = False
            if current_food_type:
                for used_food in self.daily_used_foods:
                    used_food_normalized = used_food.lower().strip()
                    # Check if used food has the same type
                    for kw in FOOD_TYPE_KEYWORDS.get(current_food_type, []):
                        if kw in used_food_normalized:
                            is_food_type_duplicate = True
                            logger.error(f" ❌ FOOD TYPE BLOCKED: '{food_name_from_db}' ({current_food_type}) - already used '{used_food}' today")
                            logger.error(f"    Maximum 1 {current_food_type} per day - skipping this component")
                            break
                    if is_food_type_duplicate:
                        break
            
            if is_food_type_duplicate:
                logger.warning(f" Component {component_idx}: Food type '{current_food_type}' already used today - trying next option")
                continue
            
            # ==================================================================================
            # 🔒 MEAL-LEVEL FOOD_CATEGORY CHECK - Block category repetition within same meal
            # ==================================================================================
            food_category_raw = food_macros.get('food_category', '').strip()
            
            logger.debug(f"   🔍 CATEGORY CHECK for '{food_name_from_db}':")
            logger.debug(f"      Raw category value: '{food_category_raw}'")
            logger.debug(f"      Current meal_used_food_categories: {list(meal_used_food_categories)}")
            
            if food_category_raw:
                food_category_normalized = food_category_raw.lower()
                logger.debug(f"      Normalized category: '{food_category_normalized}'")
                
                # Check if this category was already used in THIS MEAL
                if food_category_normalized in meal_used_food_categories:
                    # 🔒 HARD-BLOCK for breakfast (ALL components) and Components 1-2 for other meals
                    # Breakfast needs strict category diversity since it only has 2-3 items
                    is_breakfast_category_check = 'breakfast' in meal_key.lower()
                    if component_idx <= 2 or is_breakfast_category_check:
                        logger.error("=" * 80)
                        logger.error(f" ❌ CATEGORY REPEATED IN SAME MEAL DETECTED!")
                        logger.error("=" * 80)
                        logger.error(f"    Food being rejected: '{food_name_from_db}'")
                        logger.error(f"    Category: '{food_category_normalized}' (from '{food_category_raw}')")
                        logger.error(f"    Meal: {meal_name_normalized}")
                        logger.error(f"    Already used categories in this meal: {list(meal_used_food_categories)}")
                        logger.error(f"    Component index: {component_idx}")
                        logger.error(f"    BLOCKING: No duplicate categories allowed{'(breakfast: all comps)' if is_breakfast_category_check else ' for comp 1-2'}")
                        logger.error("=" * 80)
                        logger.warning(f" Component {component_idx}: Category '{food_category_normalized}' already used in this meal - trying next option")
                        continue
                    else:
                        logger.debug(f"      SOFT ALLOW: Component {component_idx} - category '{food_category_normalized}' already used but allowed (comp 3-4 uses scoring penalty)")
                else:
                    logger.debug(f"      ✅ Category '{food_category_normalized}' NOT yet used in this meal - ALLOWED")
            else:
                # Log foods without Food_category - these bypass category checks
                logger.warning(f" ⚠️ NO CATEGORY: '{food_name_from_db}' has no Food_category field (category check SKIPPED)")
                logger.warning(f"    This food will NOT be tracked for category deduplication")
            
            # 🚀 GRAIN DEDUPLICATION - Check if this grain was used in previous days (WEEKLY SCOPE)
            is_grain_repeated = False
            is_bakery_repeated = False
            
            # Check if this is a grain/bakery item
            # Exclude false positives like "cauliflower rice" which is a vegetable, not a grain
            GRAIN_FALSE_POSITIVE_PATTERNS = ['cauliflower rice', 'broccoli rice', 'konjac rice', 'shirataki rice']
            is_grain_item = any(keyword in food_name_lower for keyword in self.GRAIN_FOOD_KEYWORDS)
            if is_grain_item and any(fp in food_name_lower for fp in GRAIN_FALSE_POSITIVE_PATTERNS):
                # Check if the food has NO actual grain/starch food_group
                food_groups_for_grain_check = food_macros.get('food_group_full', []) if food_macros else []
                ACTUAL_GRAIN_GROUPS = {'grain_base', 'starch_base', 'light_grain'}
                if not any(fg in ACTUAL_GRAIN_GROUPS for fg in food_groups_for_grain_check):
                    is_grain_item = False
                    logger.debug(f"      GRAIN FALSE POSITIVE: '{food_name_from_db}' matches keyword but has no grain food_group - not treated as grain")
            is_bakery_item = 'bakery' in food_macros.get('food_category', '').lower() or \
                           any(keyword in food_name_lower for keyword in self.BAKERY_FOOD_KEYWORDS)
            
            # 🚀 MEAL-LEVEL GRAIN CHECK (max 1 grain per meal)
            if is_grain_item and len(self.meal_used_grains) > 0:
                logger.error(f" ❌ MEAL GRAIN LIMIT: Already used {len(self.meal_used_grains)} grain(s) in this meal")
                logger.error(f"    Grains in meal: {list(self.meal_used_grains)}")
                logger.error(f"    Cannot add '{food_name_from_db}' - MAX 1 GRAIN PER MEAL")
                is_grain_repeated = True
            
            # Check grain repetition across the week
            if is_grain_item and not is_grain_repeated:
                # Extract base grain name
                base_grain_name = base_food_name if 'base_food_name' in locals() else food_name_lower
                for separator in [' with ', ' and ', ', ', ' (']:
                    base_grain_name = base_grain_name.split(separator)[0].strip()
                
                # Check if this grain was used in previous days
                for used_grain in self.weekly_used_grains:
                    if base_grain_name in used_grain or used_grain in base_grain_name:
                        is_grain_repeated = True
                        logger.error(f" ❌ GRAIN REPEATED: '{food_name_from_db}' (base: '{base_grain_name}') was already used in a previous day")
                        logger.error(f"    Previous grain: '{used_grain}' - STRICT NO-REPEAT POLICY for grains across week")
                        break
            
            if is_grain_repeated:
                logger.warning(f" Component {component_idx}: Grain '{food_name_from_db}' already used this week or in this meal - trying next option")
                continue
            
            # Check bakery repetition across the week
            if is_bakery_item:
                # Extract base bakery name
                base_bakery_name = base_food_name if 'base_food_name' in locals() else food_name_lower
                for separator in [' with ', ' and ', ', ', ' (']:
                    base_bakery_name = base_bakery_name.split(separator)[0].strip()
                
                # Check if this bakery item was used in previous days
                for used_bakery in self.weekly_used_bakery:
                    if base_bakery_name in used_bakery or used_bakery in base_bakery_name:
                        is_bakery_repeated = True
                        logger.error(f" ❌ BAKERY REPEATED: '{food_name_from_db}' (base: '{base_bakery_name}') was already used in a previous day")
                        logger.error(f"    Previous bakery: '{used_bakery}' - STRICT NO-REPEAT POLICY for bakery across week")
                        break
                
                # Also check if we've exceeded weekly bakery limit
                if not is_bakery_repeated and self.weekly_bakery_count >= self.MAX_WEEKLY_BAKERY:
                    is_bakery_repeated = True
                    logger.error(f" ❌ BAKERY LIMIT: Already used {self.weekly_bakery_count} bakery items this week (max: {self.MAX_WEEKLY_BAKERY})")
            
            if is_bakery_repeated:
                logger.warning(f" Component {component_idx}: Bakery item '{food_name_from_db}' already used or limit reached - trying next option")
                continue
            
            # �🔒 ENHANCED TRACKING: Add both full name AND base food name to daily_used_foods
            # This prevents variations like "bajra khichdi with X" and "bajra khichdi with Y"
            self.daily_used_foods.add(food_name_from_db)
            
            # Extract and track base food name (without "with X", "and Y", etc.)
            base_food_name = food_name_from_db.lower().strip()
            for separator in [' with ', ' and ', ', ', ' (']:
                base_food_name = base_food_name.split(separator)[0].strip()
            
            if base_food_name != food_name_from_db.lower().strip():
                self.daily_used_foods.add(base_food_name)
                logger.debug(f"      🔒 TRACKING BASE: Also tracking '{base_food_name}' to block variations")
            
            # 🔒 TRACK FOOD TYPE: Add to tracking so subsequent meals can't use same type
            if current_food_type:
                self.daily_used_foods.add(f"__TYPE_{current_food_type}")  # Special marker for type tracking
                logger.info(f"      🔒 TYPE TRACKED: '{current_food_type}' blocked for rest of day")
            
            # 🚀 TRACK GRAINS AND BAKERY ITEMS IN WEEKLY SCOPE (NO REPEATS)
            if is_grain_item:
                base_grain_name = base_food_name
                self.weekly_used_grains.add(base_grain_name)
                self.weekly_used_grains.add(food_name_lower)  # Also track full name
                
                # 🚀 MEAL-LEVEL GRAIN TRACKING (max 1 grain per meal)
                self.meal_used_grains.add(base_grain_name)
                
                logger.info(f"      🔒 GRAIN TRACKED (WEEKLY): '{base_grain_name}' blocked for rest of week")
                logger.info(f"         Total grains used this week: {len(self.weekly_used_grains)}")
                logger.info(f"         Grains in this meal: {len(self.meal_used_grains)} (max 1 per meal)")
            
            if is_bakery_item:
                base_bakery_name = base_food_name
                self.weekly_used_bakery.add(base_bakery_name)
                self.weekly_used_bakery.add(food_name_lower)  # Also track full name
                self.weekly_bakery_count += 1
                logger.info(f"      🔒 BAKERY TRACKED (WEEKLY): '{base_bakery_name}' blocked for rest of week")
                logger.info(f"         Bakery count: {self.weekly_bakery_count}/{self.MAX_WEEKLY_BAKERY}")
            
            
            used_swaps.add(food_name_from_db.lower().strip())
            
            # NEW: Track food_category for cross-day variety control
            # 🔧 FIX GAP 2: Only track categories that actually exist (bypass missing)
            food_category_raw = food_macros.get('food_category', '').strip()
            if food_category_raw:
                food_category_normalized = food_category_raw.lower()
                
                # 🔒 MEAL-LEVEL TRACKING: Track category for THIS MEAL (prevents repeats in same meal)
                meal_used_food_categories.add(food_category_normalized)
                logger.info("=" * 80)
                logger.info(f" 🔒 CATEGORY TRACKED (MEAL-LEVEL)")
                logger.info("=" * 80)
                logger.info(f"      Food selected: '{food_name_from_db}'")
                logger.info(f"      Category: '{food_category_normalized}' (from '{food_category_raw}')")
                logger.info(f"      Meal: {meal_name_normalized}")
                logger.info(f"      This category is now BLOCKED for rest of this {meal_name_normalized}")
                logger.info(f"      All categories in this meal so far: {list(meal_used_food_categories)}")
                logger.info("=" * 80)
                
                # Cross-day tracking (for weekly variety)
                used_food_categories.add(food_category_normalized)
                logger.debug(f"    CATEGORY TRACKED (cross-day): '{food_category_normalized}' (from '{food_name_from_db}')")
                
                # Also track for daily uniqueness
                self.daily_used_categories.add(food_category_normalized)
                logger.debug(f"    CATEGORY TRACKED (daily): '{food_category_normalized}' (from '{food_name_from_db}')")
            else:
                logger.debug(f"    CATEGORY TRACKING: '{food_name_from_db}' has no Food_category (bypassed)")
            
            selected_food_normalized = food_name_from_db.lower().strip()
            removed_from_slots = []
            
            for slot_pool_name, slot_pool_foods in self.slot_pools.items():
                
                foods_to_keep = []
                for food_name in slot_pool_foods:
                    food_normalized = food_name.lower().strip()
                    
                    if food_normalized == selected_food_normalized:
                        removed_from_slots.append(slot_pool_name)
                        continue  
                    
                    food_depunctuated = food_normalized.replace('-', ' ').replace('_', ' ')
                    selected_depunctuated = selected_food_normalized.replace('-', ' ').replace('_', ' ')
                    
                    if food_depunctuated == selected_depunctuated:
                        removed_from_slots.append(slot_pool_name)
                        continue  
                    
                    foods_to_keep.append(food_name)
                
                self.slot_pools[slot_pool_name] = foods_to_keep
            
            if removed_from_slots:
                logger.debug(f"       CROSS-SLOT REMOVAL: Removed '{selected_food}' from {len(removed_from_slots)} other slots: {', '.join(set(removed_from_slots))}")
            
            food_macros = self.all_foods_macros[selected_food]
            
            if component_idx == 1 and not meal_primary_cuisine:
                food_cuisines = food_macros.get('cuisine', [])
                if not isinstance(food_cuisines, list):
                    food_cuisines = [food_cuisines] if food_cuisines else []
                food_cuisines_lower = [c.lower().strip() for c in food_cuisines if c and c.lower() != 'global']
                
                if food_cuisines_lower:
                    meal_primary_cuisine = food_cuisines_lower[0]  
                    logger.info(f"       MEAL CUISINE SET: '{meal_primary_cuisine}' (from '{selected_food}')")
                    logger.info(f"         Subsequent components will be filtered to match '{meal_primary_cuisine}' or cascade variants")
                else:
                    logger.debug(f"       First component '{selected_food}' has no specific cuisine (global/universal)")
            
            food_group_data = food_macros.get('food_group_full', [])
            if isinstance(food_group_data, list):
                food_groups = [fg.strip() for fg in food_group_data if fg and fg.strip()]
            elif isinstance(food_group_data, str):
                food_groups = [fg.strip() for fg in food_group_data.split('|') if fg.strip()]
            else:
                food_groups = []
            
            CRITICAL_GROUPS = {'protein_main', 'protein_source', 'lean_protein', 'grain_base', 'starch_base', 'light_grain', 'fruit', 'fruit_snack', 'nut_seed', 'primary_vegetable', 'cooked_vegetable', 'soup_or_broth', 'fermented_side'}
            critical_groups_in_food = [fg for fg in food_groups if fg in CRITICAL_GROUPS]
            
            # Track ALL food_groups from this food (not just one)
            for fg in critical_groups_in_food:
                meal_used_food_groups.add(fg)
            
            # NEW: Track food_category for variety control
            # � FIX GAP 2: Skip foods with missing categories (don't track as 'unknown')
            food_category_raw = food_macros.get('food_category', '').strip()
            if food_category_raw:
                food_category_normalized = food_category_raw.lower()
                meal_used_food_categories.add(food_category_normalized)
                logger.debug(f"        CATEGORY TRACKER: Added '{food_category_raw}' → '{food_category_normalized}'")
            else:
                logger.debug(f"        CATEGORY TRACKER: '{selected_food}' has NO Food_category (bypassed category tracking)")
            
            selected_food_families = _get_food_family(selected_food)
            # 🔒 AUGMENT with DB sub_food_category for robust family tracking
            selected_sub_cat = food_macros.get('sub_food_category', '').lower().strip()
            if selected_sub_cat:
                SUB_CAT_TO_FAMILY_TRACK = {
                    'tofu': 'soy_tofu', 'tempeh': 'soy_tofu', 'edamame': 'soy_tofu', 'soy': 'soy_tofu',
                    'quinoa': 'grains', 'rice': 'grains', 'oat': 'grains', 'oats': 'grains',
                    'wheat': 'grains', 'barley': 'grains', 'millet': 'grains',
                    'lentil': 'legumes', 'lentils': 'legumes', 'chickpea': 'legumes',
                    'bean': 'legumes', 'beans': 'legumes', 'pea': 'legumes',
                    'bread': 'bread_bakery', 'toast': 'bread_bakery', 'loaf': 'bread_bakery',
                    'berry': 'berries', 'berries': 'berries',
                    'nut': 'nuts', 'nuts': 'nuts', 'almond': 'nuts', 'walnut': 'nuts',
                    'seed': 'seeds', 'seeds': 'seeds',
                }
                for sub_cat_keyword, family_name in SUB_CAT_TO_FAMILY_TRACK.items():
                    if sub_cat_keyword in selected_sub_cat:
                        selected_food_families.add(family_name)
                        break
            if selected_food_families:
                meal_used_families.update(selected_food_families)
                logger.debug(f"        MEAL FAMILY TRACKER: Added {selected_food_families} to meal-level tracker")
                logger.debug(f"          → Meal now has families: {sorted(list(meal_used_families))}")
            
            logger.info(f"        REGISTERED '{selected_food}' with food_groups: {food_groups}")
            if critical_groups_in_food:
                logger.info(f"          → Added CRITICAL groups to meal tracker: {critical_groups_in_food}")
                logger.info(f"          → Meal now blocks these CRITICAL groups: {sorted(list(meal_used_food_groups))}")
            else:
                logger.info(f"          → No critical groups in this food (won't block protein/grain types)")
                logger.info(f"          → Current meal CRITICAL groups blocked: {sorted(list(meal_used_food_groups)) if meal_used_food_groups else 'none'}")

            PRIMARY_INGREDIENT_PATTERNS = [
                'black eyed peas', 'black-eyed peas', 'chickpea', 'chickpeas', 'lentil', 'lentils',
                'kidney bean', 'black bean', 'pinto bean', 'navy bean', 'lima bean', 'fava bean',
                'rajma', 'chana', 'moong', 'masoor', 'toor', 'urad', 'dal', 'daal',
                'tempeh', 'tofu', 'paneer', 'soy chunk', 'soy chunks',
                'quinoa', 'rice', 'barley', 'millet', 'pasta', 'noodles',
                'spinach', 'kale', 'cabbage', 'cauliflower', 'broccoli', 'eggplant', 'zucchini',
                'tomato', 'potato', 'sweet potato', 'yam', 'cassava',
                'chicken', 'beef', 'pork', 'lamb', 'fish', 'salmon', 'tuna', 'shrimp'
            ]
            
            food_name_before_prep = food_name_lower.split(' with ')[0].split(' and ')[0].split(' in ')[0].split(' topped')[0]
            detected_primary_ingredient = None
            for ingredient_pattern in PRIMARY_INGREDIENT_PATTERNS:
                if ingredient_pattern in food_name_before_prep:
                    detected_primary_ingredient = ingredient_pattern
                    break
            
            if detected_primary_ingredient:
                meal_used_ingredients.add(detected_primary_ingredient)
                logger.debug(f"        PRIMARY INGREDIENT TRACKED: '{detected_primary_ingredient}' from '{selected_food}'")
            
            for keyword in INGREDIENT_KEYWORDS:
                if keyword in food_name_lower:
                    if detected_primary_ingredient and keyword in detected_primary_ingredient:
                        continue
                    meal_used_ingredients.add(keyword)
            
            LEGUME_DETECTION_KEYWORDS = [
                'lentil', 'lentils', 'dal', 'daal', 'dhal', 'masoor', 'moong', 'mung', 'toor', 'tur', 'urad',
                'chana', 'chole', 'chickpea', 'chickpeas', 'garbanzo', 'gram', 'bean', 'beans', 'rajma',
                'hummus', 'falafel',
                'pea', 'peas', 'split pea', 'black-eyed', 'pigeon pea', 'soy', 'soya', 'tofu', 'edamame',
                'peanut', 'peanuts', 'groundnut', 'groundnuts', 'mungfali',  
                'khichdi', 'khichri', 'kichdi', 'kitchari'
            ]
            
            if any(kw in food_name_lower for kw in LEGUME_DETECTION_KEYWORDS):
                meal_has_legume = True
                logger.debug(f"        LEGUME DETECTED: '{selected_food}' contains legumes - blocking additional legumes for this meal")
            
            # 🔒 TRACK SUB_FOOD_CATEGORY for intra-meal dedup
            food_sub_cat = food_macros.get('sub_food_category', '').lower().strip()
            if food_sub_cat:
                meal_used_sub_categories.add(food_sub_cat)
                logger.debug(f"        SUB-CATEGORY TRACKED: '{food_sub_cat}' from '{selected_food}' - blocking same sub-category for this meal")
            
            # 🔒 TRACK FOOD_ID for intra-day dedup
            food_id = food_macros.get('_food_id', '')
            if food_id:
                self.daily_used_food_ids.add(food_id)
                logger.debug(f"        FOOD_ID TRACKED: '{food_id}' from '{selected_food}' - blocking same food in other meals today")
            
            # 🔒 TRACK SPREAD/SAUCE for limit enforcement
            if is_spread_or_sauce_food(food_macros):
                meal_has_spread_or_sauce = True
                logger.debug(f"        SPREAD/SAUCE DETECTED: '{selected_food}' - blocking additional spreads/sauces for this meal")
            
            dietary_pref_raw = user_profile.get('dietary_preference', '') if user_profile else ''
            if isinstance(dietary_pref_raw, list):
                dietary_pref = dietary_pref_raw[0].lower() if dietary_pref_raw else ''
            else:
                dietary_pref = dietary_pref_raw.lower() if dietary_pref_raw else ''
            is_vegan = 'vegan' in dietary_pref and 'non' not in dietary_pref
            is_vegetarian = 'vegetarian' in dietary_pref and 'non' not in dietary_pref
            
            user_age = user_profile.get('age', 35) if user_profile else 35
            
            
            if is_snack:
                if 'protein' in selected_from_slot.lower() or 'nut_seed' in selected_from_slot.lower():
                    portion_oz = 2.5  
                elif 'fruit' in selected_from_slot.lower():
                    portion_oz = 3.0 
                elif 'savory' in selected_from_slot.lower():
                    portion_oz = 2.0  
                else:
                    portion_oz = 2.5  
                logger.debug(f"       SNACK PORTION: {portion_oz} oz (light snack size)")
            elif 'breakfast' in meal_name.lower():
                # 🍳 BREAKFAST-SPECIFIC PORTIONS: Lighter than lunch/dinner
                if 'protein' in selected_from_slot.lower():
                    if is_vegan:
                        portion_oz = 7.0  # ~200g - breakfast protein cap
                    elif is_vegetarian:
                        portion_oz = 6.0  # ~170g
                    else:
                        portion_oz = 5.0  # ~140g
                elif 'nut_seed' in selected_from_slot.lower():
                    portion_oz = 1.5  # ~42g - nuts/seeds are calorie-dense
                elif 'beverage' in selected_from_slot.lower() or 'warm_beverage' in selected_from_slot.lower():
                    portion_oz = 8.0  # ~225ml - reasonable cup size for smoothie/drink
                elif 'dairy' in selected_from_slot.lower():
                    portion_oz = 5.0  # ~140g - yogurt/milk serving
                elif 'grain' in selected_from_slot.lower():
                    portion_oz = 3.0  # ~85g - 1-2 slices of bread/toast
                elif 'fruit' in selected_from_slot.lower():
                    portion_oz = 4.0  # ~113g - good fruit portion
                else:
                    portion_oz = 4.0  # ~113g default breakfast portion
                logger.debug(f"       BREAKFAST PORTION: {portion_oz} oz for slot '{selected_from_slot}'")
            else:
                if 'protein' in selected_from_slot.lower() or 'nut_seed' in selected_from_slot.lower():
                    if is_vegan:
                        portion_oz = 13.0  
                    elif is_vegetarian:
                        portion_oz = 12.0  
                    else:
                        portion_oz = 9.0 
                elif 'starch' in selected_from_slot.lower() or 'grain' in selected_from_slot.lower():
                    if is_vegan or is_vegetarian:
                        portion_oz = 2.0  
                    else:
                        portion_oz = 3.0
                elif 'beverage' in selected_from_slot.lower() or 'hydration' in selected_from_slot.lower():
                    portion_oz = 1.5
                elif 'condiment' in selected_from_slot.lower() or 'fermented' in selected_from_slot.lower():
                    portion_oz = 1.0
                else:
                    portion_oz = 3.0
            
            NONVEG_KEYWORDS = [
                'chicken', 'beef', 'pork', 'lamb', 'mutton', 'veal', 'goat', 'turkey', 'duck',
                'fish', 'salmon', 'tuna', 'cod', 'tilapia', 'mackerel', 'trout', 'shrimp', 'prawn',
                'crab', 'lobster', 'seafood', 'meat', 'steak', 'meatball', 'kebab', 'sausage',
                'bacon', 'ham', 'venison', 'rabbit', 'quail'
            ]
            is_nonveg = any(kw in food_name_lower for kw in NONVEG_KEYWORDS)
            
            if is_nonveg and not is_snack:
                MAX_NONVEG_OZ = 7.0  
                if portion_oz > MAX_NONVEG_OZ:
                    logger.warning(f"       NON-VEG PORTION LIMIT: '{selected_food}' portion reduced from {portion_oz:.1f} oz to {MAX_NONVEG_OZ} oz (max 200g for non-veg)")
                    portion_oz = MAX_NONVEG_OZ
            
            food_item = self._format_food_item_for_output(selected_food, food_macros, portion_oz=portion_oz)
            
            # 🔒 MINIMUM CALORIE THRESHOLD: Reject items with meaninglessly low calories
            item_calories = food_item.get('nutrients', {}).get('Calories', 0)
            MIN_ITEM_CALORIES = 40  # No item should contribute less than 40 kcal
            if item_calories < MIN_ITEM_CALORIES and not is_snack:
                logger.warning(f"       ❌ MIN CALORIE REJECTION: '{selected_food}' only provides {item_calories:.0f} kcal "
                             f"(min {MIN_ITEM_CALORIES} kcal) at {portion_oz:.1f} oz - skipping")
                continue
            
            is_core_slot = selected_from_slot in CORE_SLOT_NAMES
            food_item['is_core'] = is_core_slot
            
            if is_core_slot:
                logger.debug(f"       Marked as CORE (Accessory Pruner will preserve)")
            else:
                logger.debug(f"       Marked as ACCESSORY (Accessory Pruner may remove if calories too high)")
            
            if has_type2_diabetes and meal_name_normalized.lower() in ['breakfast', 'lunch', 'dinner'] and len(meal_items) >= 2:
                current_meal_cals = sum(item.get('calories', 0) for item in meal_items)
                current_meal_carbs = sum(item.get('nutrients', {}).get('Carbs', 0) for item in meal_items)
                
                new_food_cals = food_item.get('calories', 0)
                new_food_carbs = food_item.get('nutrients', {}).get('Carbs', 0)
                
                projected_total_cals = current_meal_cals + new_food_cals
                projected_total_carbs = current_meal_carbs + new_food_carbs
                
                if projected_total_cals > 0:
                    projected_carb_pct = (projected_total_carbs * 4 / projected_total_cals) * 100
                    
                    if has_type2_diabetes and projected_carb_pct > 30.0:
                        logger.warning(f"       CARB REJECTION: '{selected_food}' would push {meal_name_normalized} to {projected_carb_pct:.1f}% carbs (T2D limit: 30%)")
                        logger.warning(f"         Current: {current_meal_carbs:.0f}g carbs / {current_meal_cals:.0f} cals = {(current_meal_carbs * 4 / current_meal_cals * 100) if current_meal_cals > 0 else 0:.1f}%")
                        logger.warning(f"         Food adds: {new_food_carbs:.0f}g carbs / {new_food_cals:.0f} cals")
                        logger.warning(f"         Projected: {projected_total_carbs:.0f}g carbs / {projected_total_cals:.0f} cals = {projected_carb_pct:.1f}%")
                        logger.warning(f"         Rejecting food - trying next option from {selected_from_slot}")
                        continue  
            
            # 🍽️ AYURVEDIC PAIRING CHECK: Reject incompatible food combinations
            candidate_food_dict = self.all_foods_macros.get(selected_food, {})
            candidate_food_dict_for_traits = {**candidate_food_dict, 'name': selected_food}
            candidate_traits = self._get_food_traits(candidate_food_dict_for_traits)
            if candidate_traits and current_meal_traits and self._has_pairing_conflict(current_meal_traits, candidate_traits):
                logger.warning(f"    🍽️ PAIRING CONFLICT: '{selected_food}' traits {candidate_traits} conflict with meal traits {current_meal_traits} - skipping")
                continue

            meal_items.append(food_item)
            
            # 🍽️ Update running meal traits after successful selection
            current_meal_traits.update(candidate_traits)
            
            is_snack_meal = 'Snack' in meal_name
            if is_snack_meal:
                normalized_snack = self._normalize_for_tracking(selected_food)
                self.daily_used_snacks.add(normalized_snack)
                self.weekly_used_snacks.add(normalized_snack)
            
            animal_protein_keywords = [
                'chicken', 'beef', 'pork', 'lamb', 'veal', 'steak', 'meatball', 'mince', 
                'salmon', 'cod', 'shrimp', 'fish', 'crab', 'trout', 'mackerel', 'whiting', 
                'flounder', 'seafood', 'tuna', 'lobster', 'clam', 'conch', 'oyster', 'tilapia', 
                'basa', 'haddock', 'sole', 'prawn', 'scallop', 'hen', 'drumstick', 'turkey',
                'grouper', 'herring', 'swordfish', 'albacore', 'perch', 'pompano', 'egg', 'omelet', 'omelette',
                'halibut', 'catfish', 'snapper', 'mahi', 'sardine', 'anchovy', 'barramundi', 'seabass', 'bass',
                'brisket', 'ribs', 'roast', 'chuck', 'sirloin', 'tenderloin', 'cutlet', 'chop'
            ]
            selected_food_lower = selected_food.lower()
            has_animal_protein_keyword = any(kw in selected_food_lower for kw in animal_protein_keywords)
            
            selected_food_groups_data = food_macros.get('food_group_full', [])
            if isinstance(selected_food_groups_data, str):
                selected_food_groups_lower = [fg.strip().lower() for fg in selected_food_groups_data.split('|') if fg.strip()]
            elif isinstance(selected_food_groups_data, list):
                selected_food_groups_lower = [fg.strip().lower() for fg in selected_food_groups_data if fg and fg.strip()]
            else:
                selected_food_groups_lower = []
            
            is_grain_or_veg_combo = any(tag in selected_food_groups_lower for tag in ['grain_base', 'starch_base', 'light_grain', 'primary_vegetable', 'cooked_vegetable', 'fibrous_veggies'])
            
            if has_animal_protein_keyword and not is_grain_or_veg_combo:
                current_meal_animal_protein_count += 1
                if current_meal_protein_family is None:
                    current_meal_protein_family = self._detect_protein_family(selected_food)
                    logger.debug(f"       First protein in meal: {current_meal_protein_family} family ({selected_food})")
                logger.debug(f"       Animal protein counter: {current_meal_animal_protein_count}/1 for this meal (MAX 1 per meal strictly enforced)")
            elif has_animal_protein_keyword and is_grain_or_veg_combo:
                logger.debug(f"       PROTEIN COUNT: NOT incremented - '{selected_food}' is grain/vegetable combo, not pure protein")
            
            daily_sodium += food_item.get('nutrients', {}).get('Sodium', 0)
            daily_potassium += food_item.get('nutrients', {}).get('Potassium', 0) 
            daily_cholesterol += food_item.get('nutrients', {}).get('Cholesterol', 0) 
            daily_fat += food_item.get('nutrients', {}).get('Fat', 0)
            if any(kw in selected_food.lower() for kw in ['salami', 'hot dog', 'bacon', 'sausage', 'ham']):
                processed_meat_count += 1
        final_count = len(meal_items)
        
        if final_count > max_items:
            logger.error(f" FORMAT VIOLATION: {meal_name_normalized} has {final_count} items (MAXIMUM: {max_items} - STRICT 3-2-4-2-4 format)")
            logger.error(f"   TRIMMING to {max_items} items to enforce user's strict format requirement")
            meal_items = meal_items[:max_items]  
            final_count = len(meal_items)
            logger.warning(f"     TRIMMED to {final_count} items - format now compliant")
        
        if final_count < min_items:
            logger.warning(f" {meal_name_normalized} has only {final_count} items (minimum: {min_items})")
            logger.warning(f"   Pool exhaustion likely - triggering emergency fallback")
            
            if final_count < min_items:
                logger.error(f" MEAL STRUCTURE VIOLATION: {meal_name_normalized} has only {final_count} items (MINIMUM: {min_items})")
                logger.error(f"   Attempting emergency fallback with cross-meal slot sharing to reach {min_items} items...")
                
                is_component2_cereal_emergency = False
                if meal_key in ['lunch', 'dinner']:
                    tdee_structure = self._get_tdee_based_meal_structure(tdee)
                    meal_structure = tdee_structure.get(meal_key, [])
                    if len(meal_structure) >= 2:
                        component2_slots = meal_structure[1]  
                        expected_cereal_slots = ['grain_base', 'starch_base', 'light_grain']
                        if any(slot in component2_slots for slot in expected_cereal_slots):
                            is_component2_cereal_emergency = True
                            logger.error(f"    COMPONENT 2 CEREAL EMERGENCY: {meal_name_normalized} missing mandatory cereal/grain")
                            logger.error(f"    STRATEGY: Prioritize PURE GRAINS (rice/bread/tortilla) without protein to avoid stacking violations")
                
                if is_snack:
                    emergency_slots = ['fruit_snack', 'nut_seed', 'fruit', 'protein_snack']
                elif meal_key == 'breakfast':
                    emergency_slots = ['dairy_or_alt', 'fruit', 'light_grain', 'fruit_snack', 'protein_snack', 'nut_seed']
                    logger.info(f"   Breakfast: Using primary slots + Morning Snack slots for emergency fallback")
                elif meal_key == 'lunch':
                    # 🔒 FIX: Only include grain slots if meal is MISSING a grain; otherwise use DIFFERENT groups
                    meal_has_grain = len(self.meal_used_grains) > 0
                    if meal_has_grain:
                        emergency_slots = ['primary_vegetable', 'cooked_vegetable', 'lean_protein', 'fat_source', 'soup_or_broth', 'nut_seed']
                        logger.info(f"   Lunch: Meal already has grain - using DIFFERENT groups (veggie/protein/fat) for emergency fallback")
                    else:
                        emergency_slots = ['grain_base', 'starch_base', 'light_grain', 'primary_vegetable', 'cooked_vegetable', 'lean_protein', 'fat_source']
                        logger.info(f"   Lunch: Meal missing grain - using grain slots (priority) + shared Dinner slots for emergency fallback")
                elif meal_key == 'dinner':
                    # 🔒 FIX: Only include grain slots if meal is MISSING a grain; otherwise use DIFFERENT groups
                    meal_has_grain = len(self.meal_used_grains) > 0
                    if meal_has_grain:
                        emergency_slots = ['primary_vegetable', 'cooked_vegetable', 'lean_protein', 'fat_source', 'soup_or_broth', 'nut_seed']
                        logger.info(f"   Dinner: Meal already has grain - using DIFFERENT groups (veggie/protein/fat) for emergency fallback")
                    else:
                        emergency_slots = ['grain_base', 'starch_base', 'light_grain', 'primary_vegetable', 'cooked_vegetable', 'lean_protein', 'fat_source']
                        logger.info(f"   Dinner: Meal missing grain - using grain slots (priority) + shared Lunch slots for emergency fallback")
                else:
                    emergency_slots = ['fruit_snack', 'nut_seed', 'fruit']
                
                current_meal_soup_count = 0
                current_meal_legume_count = 0
                
                emergency_items_needed = min_items - final_count
                logger.info(f"   Need {emergency_items_needed} more items to meet minimum of {min_items}")
                
                for _ in range(emergency_items_needed):
                    added_emergency = False
                    for emergency_slot in emergency_slots:
                        if emergency_slot not in self.slot_pools:
                            continue
                        
                        used_swaps_normalized = {f.lower().strip() for f in used_swaps}
                        daily_used_normalized = {f.lower().strip() for f in self.daily_used_foods}
                        prev_day_normalized = {f.lower().strip() for f in self.used_failsafes_previous_day} if self.used_failsafes_previous_day else set()
                        weekly_excluded_normalized = {f.lower().strip() for f in getattr(self, 'weekly_hard_excluded', set())}
                        
                        # 🔒 EXTRACT BASE FOOD NAMES for duplicate prevention
                        # Prevents: "bajra khichdi with X" + "bajra khichdi with Y" in emergency fallback
                        used_base_foods = {f.split(' with ')[0].split(' and ')[0].strip() for f in used_swaps_normalized}
                        daily_base_foods = {f.split(' with ')[0].split(' and ')[0].strip() for f in daily_used_normalized}
                        
                        is_cereal_emergency = (is_component2_cereal_emergency and 
                                              emergency_slot in ['grain_base', 'starch_base', 'light_grain'])
                        
                        if is_cereal_emergency:
                            unused_grains = [f for f in self.slot_pools[emergency_slot] 
                                           if f.lower().strip() not in used_swaps_normalized 
                                           and f.lower().strip() not in daily_used_normalized
                                           and f.lower().strip() not in prev_day_normalized
                                           and f.lower().strip() not in weekly_excluded_normalized]
                            
                            reusable_grains = [f for f in self.slot_pools[emergency_slot] 
                                             if f.lower().strip() not in used_swaps_normalized 
                                             and f.lower().strip() in daily_used_normalized
                                             and f.lower().strip() not in prev_day_normalized
                                             and f.lower().strip() not in weekly_excluded_normalized]
                            
                            if unused_grains:
                                available_foods = unused_grains
                                logger.error(f"    GRAIN VARIETY: Using {len(unused_grains)} UNUSED grains (prefer different grains per meal)")
                            elif reusable_grains:
                                available_foods = reusable_grains
                                logger.error(f"    GRAIN REUSE (Last Resort): Using {len(reusable_grains)} grains from other meals (no unused grains available)")
                            else:
                                available_foods = []
                                logger.error(f"    NO GRAINS: All {len(self.slot_pools[emergency_slot])} grains exhausted")
                        else:
                            available_foods = [f for f in self.slot_pools[emergency_slot] 
                                             if f.lower().strip() not in used_swaps_normalized 
                                             and f.lower().strip() not in daily_used_normalized
                                             and f.lower().strip() not in prev_day_normalized
                                             and f.lower().strip() not in weekly_excluded_normalized]
                        
                        if is_component2_cereal_emergency and emergency_slot in ['grain_base', 'starch_base', 'light_grain']:

                            if available_foods:
                                logger.info(f"     GRAIN POOL READY: {len(available_foods)} grains available in {emergency_slot}")
                                logger.info(f"       Accepting ALL grains (pure + protein-enriched) for maximum variety")
                            else:
                                logger.error(f"     NO GRAINS AVAILABLE: {emergency_slot} exhausted after all filters")
                                logger.error(f"    PHASE 2 EMERGENCY: Searching entire database ({len(self.all_foods_macros)} foods) for medically-safe grains")
                                
                                grain_keywords = ['rice', 'bread', 'roti', 'chapati', 'quinoa', 'naan', 
                                                 'paratha', 'tortilla', 'pasta', 'couscous', 'bulgur', 
                                                 'millet', 'oats', 'barley', 'farro', 'buckwheat']
                                
                                diabetes_safe_grains = ['quinoa', 'bulgur', 'barley', 'oats', 'buckwheat', 'millet', 'farro']
                                user_has_diabetes = any(
                                    'diabetes' in cond.lower() or 'prediabetes' in cond.lower()
                                    for cond in user_profile.get('medical_conditions', [])
                                )
                                
                                for food_name, food_macros in self.all_foods_macros.items():
                                    food_name_lower = food_name.lower()
                                    
                                    if not any(grain in food_name_lower for grain in grain_keywords):
                                        continue
                                    
                                    # 🔒 CROSS-DAY BLOCK: Skip grains from previous day even in PHASE 2
                                    if food_name_lower.strip() in prev_day_normalized:
                                        continue
                                    
                                    # 🚫 WEEKLY EXCLUSION: Skip grains that appeared 2+ times this week
                                    if food_name_lower.strip() in weekly_excluded_normalized:
                                        continue
                                    
                                    is_diabetes_safe_grain = (
                                        user_has_diabetes and 
                                        any(safe_grain in food_name_lower for safe_grain in diabetes_safe_grains)
                                    )
                                    
                                    is_safe = self.is_safe_from_blacklist(
                                        food_name,
                                        set(),  
                                        user_profile,
                                        food_macros
                                    )
                                    
                                    # NEW: Intra-Meal Emergency Check
                                    em_food_category = food_macros.get('food_category', '').lower().strip()
                                    # � SOFT: Category conflicts handled by scoring, allow through in emergency paths
                                    # Emergency paths should not hard-block or components get skipped entirely
                                    
                                    if not is_safe and not is_diabetes_safe_grain:
                                        continue
                                    
                                    if is_diabetes_safe_grain and not is_safe:
                                        logger.info(f"       🩺 DIABETES EXCEPTION: Allowing '{food_name}' (low-GI grain, portion-controlled)")
                                    
                                    fiber = food_macros.get('fiber', 0)
                                    if fiber > 8.0:  
                                        continue
                                    
                                    available_foods.append(food_name)
                                    if len(available_foods) >= 20:
                                        break
                                
                                if available_foods:
                                    logger.info(f"     PHASE 2 SUCCESS: Found {len(available_foods)} medically-safe grains from database")
                                    logger.info(f"       (Bypassed diversity/similarity filters - medical safety only)")
                                else:
                                    logger.error(f"     PHASE 2 FAILED: No medically-safe grains in entire database")
                                    logger.error(f"    Cannot fulfill mandatory grain requirement - structural violation unavoidable")
                                    available_foods = []
                        
                        # 🚀 CUISINE-FIRST DIVERSITY: Check tiers BEFORE applying food_group filter
                        # Tier 1 foods (user's preferred cuisine) get priority even with duplicate food_groups
                        tier_1_foods_raw = [f for f in available_foods 
                                           if self.all_foods_macros.get(f, {}).get('_cuisine_priority') == 1]
                        tier_2_foods_raw = [f for f in available_foods 
                                           if self.all_foods_macros.get(f, {}).get('_cuisine_priority') == 2]
                        tier_3_foods_raw = [f for f in available_foods 
                                           if self.all_foods_macros.get(f, {}).get('_cuisine_priority', 999) >= 3]
                        
                        # 🚀 CUISINE-FIRST DIVERSITY: Check tiers in priority order, tracking food_category as we go
                        # This prioritizes Tier 1 (user's cuisine) while still enforcing within-meal diversity
                        group_unique_foods = []
                        tracked_meal_categories = set(meal_used_food_categories)  # Copy existing meal categories
                        
                        for tier_foods in [tier_1_foods_raw, tier_2_foods_raw, tier_3_foods_raw]:
                            for food_name in tier_foods:
                                if food_name not in self.all_foods_macros:
                                    continue
                                
                                food_macros = self.all_foods_macros[food_name]
                                # 🔥 Use food_category (unique) instead of food_group (multiple per food)
                                food_category = food_macros.get('food_category', '').strip()
                                
                                # Check if this category was already used in this meal
                                has_conflict = food_category and food_category in tracked_meal_categories
                                
                                if not has_conflict:
                                    group_unique_foods.append(food_name)
                                    # 🔥 KEY FIX: Update tracked categories so next food sees this conflict
                                    if food_category:
                                        tracked_meal_categories.add(food_category)
                        
                        # Log emergency status but still respect diversity
                        if is_component2_cereal_emergency and emergency_slot in ['grain_base', 'starch_base', 'light_grain']:
                            if len(group_unique_foods) < len(available_foods):
                                logger.error(f"    EMERGENCY DIVERSITY: Filtered {len(available_foods)} grains → {len(group_unique_foods)} unique (blocked duplicates)")
                            else:
                                logger.error(f"    EMERGENCY GRAINS: Using {len(group_unique_foods)} diverse grains (cereal priority)")
                            
                            if len(group_unique_foods) == 0:
                                # 🔒 FIX: Do NOT bypass category checks - skip this slot and try next emergency_slot instead
                                logger.warning(f"         ALL GRAINS BLOCKED: Meal already has grain category - skipping grain emergency slot")
                                logger.warning(f"         Will try next emergency_slot (vegetable/protein/fat) instead of forcing duplicate grains")
                                continue  # Skip to next emergency_slot instead of bypassing diversity
                        
                        tier_1_foods = [f for f in group_unique_foods 
                                       if self.all_foods_macros.get(f, {}).get('_cuisine_priority') == 1]
                        tier_2_foods = [f for f in group_unique_foods 
                                       if self.all_foods_macros.get(f, {}).get('_cuisine_priority') == 2]
                        tier_3_foods = [f for f in group_unique_foods 
                                       if self.all_foods_macros.get(f, {}).get('_cuisine_priority', 999) >= 3]

                        allow_tier3_for_medical_grains = (
                            is_component2_cereal_emergency and 
                            emergency_slot in ['grain_base', 'starch_base', 'light_grain'] and
                            not tier_1_foods and not tier_2_foods and tier_3_foods
                        )
                        
                        if allow_tier3_for_medical_grains:
                            tier_cascade = [
                                (tier_1_foods, "Tier 1 (preferred cuisine)"),
                                (tier_2_foods, "Tier 2 (regional fallback)"),
                                (tier_3_foods, "Tier 3 (MEDICAL EXCEPTION: diabetes-safe grains)")
                            ]
                            logger.warning(f"        MEDICAL SAFETY EXCEPTION: Allowing {len(tier_3_foods)} global grains (only option after gluten/legume filters)")
                        else:
                            tier_cascade = [
                                (tier_1_foods, "Tier 1 (preferred cuisine)"),
                                (tier_2_foods, "Tier 2 (regional fallback)")
                            ]
                        
                        if is_component2_cereal_emergency and emergency_slot in ['grain_base', 'starch_base', 'light_grain']:
                            logger.error(f"       TIER POPULATIONS: Tier1={len(tier_1_foods)}, Tier2={len(tier_2_foods)}, Tier3={len(tier_3_foods)} from {len(group_unique_foods)} group-unique foods")
                            if tier_3_foods and not tier_1_foods and not tier_2_foods and not allow_tier3_for_medical_grains:
                                logger.warning(f"        CUISINE ENFORCEMENT: {len(tier_3_foods)} global foods available but BLOCKED (100% cuisine match required)")
                        
                        emergency_added = False
                        for tier_foods, tier_name in tier_cascade:
                            if not tier_foods:
                                continue  
                            
                            if tier_name != "Tier 1 (preferred cuisine)":
                                logger.debug(f"      EMERGENCY: Trying {tier_name} ({len(tier_foods)} foods)")
                            
                            for emergency_food in tier_foods:
                                food_macros = self.all_foods_macros.get(emergency_food, {})
                                if not food_macros or not food_macros.get('meal_tags', food_macros.get('meal_timing')):
                                    food_macros = self.all_foods_macros.get(emergency_food, {})
                                
                                is_pure_grain_emergency = False
                                if is_component2_cereal_emergency and emergency_slot in ['grain_base', 'starch_base', 'light_grain']:
                                    is_pure_grain_emergency = True  
                                
                                food_meal_timing_raw = food_macros.get('meal_timing', food_macros.get('meal_tags', []))
                                if isinstance(food_meal_timing_raw, str):
                                    food_meal_timing = [food_meal_timing_raw.strip().lower()]
                                elif isinstance(food_meal_timing_raw, list):
                                    food_meal_timing = [mt.strip().lower() for mt in food_meal_timing_raw if mt and mt.strip()]
                                else:
                                    food_meal_timing = []
                                
                                meal_name_normalized_lower = meal_name_normalized.lower()
                                
                                if is_snack:
                                    VALID_SNACK_TAGS = {'snack', 'morning snack', 'evening snack', 'snacks'}
                                    has_valid_snack_tag = any(tag in VALID_SNACK_TAGS for tag in food_meal_timing)
                                    
                                    if not has_valid_snack_tag:
                                        logger.error(f"       EMERGENCY VALIDATION FAILED: '{emergency_food}' - Meal timing mismatch: '{emergency_food}' is for {food_meal_timing}, not {meal_name_normalized} (snack)")
                                        logger.error(f"          Snacks MUST have snack tags. Food has: {food_meal_timing}")
                                        continue  
                                else:
                                    has_matching_tag = any(meal_name_normalized_lower in tag for tag in food_meal_timing)
                                    
                                    if not has_matching_tag:
                                        logger.warning(f"  MEAL TIMING VIOLATION: '{emergency_food}' is {food_meal_timing[0] if food_meal_timing else 'untagged'} item, inappropriate for {meal_name_normalized}")
                                        logger.warning(f"    Food tags: {food_meal_timing}, Current meal: {meal_name_normalized}")
                                        continue  # 🔒 STRICT: Never serve wrong-timing food even in emergency

                                
                                emergency_food_lower = emergency_food.lower()
                                food_group_data = food_macros.get('food_group_full', [])
                                if isinstance(food_group_data, str):
                                    emergency_food_groups = [fg.strip().lower() for fg in food_group_data.split('|') if fg.strip()]
                                elif isinstance(food_group_data, list):
                                    emergency_food_groups = [fg.strip().lower() for fg in food_group_data if fg and fg.strip()]
                                else:
                                    emergency_food_groups = []
                                
                                is_grain_combo = any(tag in emergency_food_groups for tag in ['grain_base', 'starch_base', 'light_grain', 'complex_carbs'])
                                is_vegetable_combo = any(tag in emergency_food_groups for tag in ['primary_vegetable', 'cooked_vegetable', 'fibrous_veggies'])
                                is_legume_combo = any(tag in emergency_food_groups for tag in ['legume', 'protein_source']) and ('dal' in emergency_food_lower or 'lentil' in emergency_food_lower or 'bean' in emergency_food_lower or 'chickpea' in emergency_food_lower)
                                
                                is_pure_animal_protein = False
