                                is_grain_or_veg_combo = any(tag in [fg.lower() for fg in emergency_food_groups] for tag in ['grain_base', 'starch_base', 'light_grain', 'primary_vegetable', 'cooked_vegetable', 'fibrous_veggies'])
                                
