                                        PROTEIN_SLOTS = {'protein_main', 'lean_protein', 'protein_source', 'protein_snack'}
                                        GRAIN_CATEGORIES = {'grains, cereals & pulses', 'grains cereals & pulses', 'grains'}
                                        PROTEIN_CATEGORIES = {'meat, poultry & fish', 'meat poultry & fish', 'eggs & egg products', 'seafood'}
                                        DAIRY_CATEGORIES = {'dairy & dairy alternatives', 'dairy'}
                                        
                                        slot_expects_category = False
